window.JOURNEY = {"regions":[{"id":"anhui","zh":"安徽","py":"Ānhuī","en":"Anhui","cities":[{"id":"hefei","zh":"合肥","py":"Héféi","en":"Hefei","lat":31.82,"lon":117.23,"note":"The capital of Anhui, a city of science and universities.","stops":[["A","包公园","Bāogōng Yuán","Lord Bao Park","A lakeside park in Hefei honoring Judge Bao, the incorruptible official of the Song dynasty who became China's best-loved symbol of fair justice in stories and operas.","",31.86,117.3],["A","三河古镇","Sānhé Gǔzhèn","Sanhe Ancient Town","A water town of narrow stone lanes, arched bridges and Ming and Qing houses, where boats still drift past old shopfronts.","",31.67,117.22],["A","安徽博物院","Ānhuī Bówùyuàn","Anhui Museum","The province's main museum, tracing Anhui from ancient bronzes to the culture of the Hui merchants, with a fine collection of local arts and crafts.","",31.81,117.23],["A","巢湖","Cháohú","Chao Lake","One of China's five great freshwater lakes, a wide blue sheet beside Hefei, ringed with wetlands, fishing villages and lakeside walks.","",31.6,117.6],["D","庐州烤鸭","Lúzhōu kǎoyā","Luzhou roast duck","Hefei's own roast duck, made with a sweet, savory glaze and a crackling skin that locals eat with a bowl of hot rice."],["D","三河米饺","Sānhé mǐjiǎo","Sanhe rice dumplings","Thin, chewy rice-flour dumplings from Sanhe, folded around a juicy filling of pork and vegetables and a classic of the water town."],["D","合肥龙虾","Héféi lóngxiā","Hefei crayfish","In summer, Hefei fills its streets with red crayfish stir-fried in garlic, chili and spices, eaten by hand with a cold beer."],["D","李鸿章杂烩","Lǐhóngzhāng záhuì","Li Hongzhang stew","A hearty hotchpotch of meatballs, egg dumplings and more, named for the Qing statesman Li Hongzhang, who came from the Hefei area."]]},{"id":"huangshan","zh":"黄山","py":"Huángshān","en":"Huangshan","lat":29.71,"lon":118.34,"note":"The city at the foot of the Yellow Mountains.","stops":[["A","黄山风景区","Huángshān Fēngjǐngqū","Huangshan Mountain","Sheer granite peaks, pines clinging to the cliffs and seas of drifting cloud. Huangshan has inspired Chinese ink painters for centuries and is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",30.13,118.17,1],["A","迎客松","Yíngkèsōng","Welcoming Pine","A famous pine reaching out one arm over the cliff as if to welcome visitors, it is one of the best-known trees in China.","",30.13,118.16],["A","光明顶","Guāngmíngdǐng","Brightness Summit","One of the main summits of Huangshan, popular for its wide views over the peaks and for watching the sun rise through the clouds.","",30.13,118.17],["A","莲花峰","Liánhuāfēng","Lotus Peak","The tallest peak of Huangshan, rising above the sea of cloud like the petals of a lotus. The final climb is steep and often crowded.","",30.1,118.15],["A","西递","Xīdì","Xidi","An old village of white walls, dark roofs and carved stone gateways, built by wealthy merchants. Together with Hongcun it is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",29.9,117.99],["A","宏村","Hóngcūn","Hongcun","A village laid out around a moon-shaped pond, with a clever water channel running past every house. Its reflections of white walls and ink-dark roofs look like a painting.","",30.01,117.98,1],["A","屯溪老街","Túnxī Lǎojiē","Tunxi Old Street","A long street of Ming and Qing style shopfronts selling tea, ink stones, brushes and local crafts, a good place to stroll and sample snacks.","",29.71,118.33],["A","徽州古城","Huīzhōu Gǔchéng","Huizhou Ancient City","A walled town in the old Huizhou region, with stone archways, ancestral halls and narrow lanes that tell the story of the powerful Hui merchants.","",29.89,118.43],["D","臭鳜鱼","Chòu guìyú","Stinky mandarin fish","Anhui's most famous dish: mandarin fish cured until it develops a strong smell, then braised or fried into tender, savory flesh. The smell is a warning but the taste is a delight.","",null,null,1],["D","毛豆腐","Máo dòufǔ","Hairy tofu","Tofu left to grow a soft white fuzz of harmless mold, then pan-fried until crisp. Its flavor is savory and much milder than its look suggests."],["D","黄山烧饼","Huángshān shāobǐng","Huangshan sesame cake","A small, crisp, layered baked cake stuffed with preserved vegetables and pork, sold hot from clay ovens and a favorite Huangshan snack."],["D","黄山毛峰","Huángshān máofēng","Huangshan Maofeng tea","A prized green tea picked from the misty slopes of Huangshan, its slender leaves are tipped with white down and brew a fresh, sweet cup."],["D","一品锅","Yīpǐnguō","Yipin pot","A layered stew pot that stacks meatballs, dumplings, ham, tofu and vegetables, traditionally served for family feasts and festivals."],["C","徽派建筑","Huīpài jiànzhù","Huizhou architecture","Hui-style houses have white walls, grey tiled roofs, tall horse-head gables and richly carved wood, stone and brick that show a family's wealth."],["C","徽剧","Huījù","Hui opera","Hui opera is an old regional opera. In the 18th century, Hui troupes came to Beijing, and their style helped shape Peking opera."]]},{"id":"chizhou","zh":"池州","py":"Chízhōu","en":"Chizhou","lat":30.66,"lon":117.49,"note":"A city with a holy Buddhist mountain.","stops":[["A","九华山","Jiǔhuàshān","Jiuhua Mountain","One of the four sacred mountains of Chinese Buddhism, dedicated to the bodhisattva Dizang. Temples dot its misty slopes, and pilgrims climb through incense and pines.","",30.48,117.8,1],["A","肉身殿","Ròushēn Diàn","Flesh Body Hall","A hall at Jiuhua Mountain where the body of a revered monk was preserved. Pilgrims come to pay respect at this quiet, solemn place.","",30.48,117.8],["D","九华素斋","Jiǔhuá sùzhāi","Jiuhua vegetarian food","The mountain's temple kitchens make vegetarian dishes from tofu, mushrooms and local vegetables that are simple, wholesome and surprisingly tasty."],["D","九华黄精","Jiǔhuá huángjīng","Jiuhua Huangjing","Huangjing is a root herb long used in Chinese medicine and food. It is grown on the cool slopes of Jiuhua and often steamed and sweetened."]]},{"id":"wuhu","zh":"芜湖","py":"Wúhú","en":"Wuhu","lat":31.35,"lon":118.43,"note":"A river port with a famous sculpture park.","stops":[["D","芜湖小笼包","Wúhú xiǎolóngbāo","Wuhu small buns","Wuhu's small steamed buns have thin skins and a rich, juicy filling. They are a typical breakfast in this Yangtze river port."],["D","芜湖铁画","Wúhú tiěhuà","Wuhu iron painting","A unique art invented in Wuhu, where blacksmiths forge thin iron strips into landscapes, flowers and birds that look like ink paintings."]]},{"id":"anqing","zh":"安庆","py":"Ānqìng","en":"Anqing","lat":30.54,"lon":117.06,"note":"A river city, the cradle of Huangmei opera.","stops":[["A","振风塔","Zhènfēngtǎ","Zhenfeng Pagoda","A seven-story brick pagoda on the bank of the Yangtze in Anqing, built in the Ming dynasty to bring good fortune to the city.","",30.51,117.05],["A","天柱山","Tiānzhùshān","Tianzhu Mountain","A mountain of tall granite pillars and pines, called one of Anhui's finest. Its name means Heavenly Pillar Mountain.","",30.73,116.46],["A","迎江寺","Yíngjiāngsì","Yingjiang Temple","A Buddhist temple beside the Yangtze in Anqing, with the Zhenfeng Pagoda close by. The two are often visited together.","",30.51,117.05],["D","安庆桂花糕","Ānqìng guìhuā gāo","Anqing osmanthus cake","A soft, sweet cake scented with osmanthus blossoms, a delicate local treat that goes well with a cup of tea."],["C","黄梅戏","Huángméixì","Huangmei opera","One of the best-loved operas in China, with sweet, simple melodies and love stories. It grew from tea-picking songs near Anqing and is still performed across the country.","",null,null,1]]},{"id":"bengbu","zh":"蚌埠","py":"Bèngbù","en":"Bengbu","lat":32.92,"lon":117.39,"note":"A Huai River city.","stops":[["D","蚌埠烧饼","Bèngbù shāobǐng","Bengbu sesame flatbread","A crisp, flaky baked flatbread, often stuffed with meat or preserved vegetables and eaten fresh from the oven."],["D","淮河大鲤鱼","Huáihé dà lǐyú","Huai River carp","Big carp from the Huai River are stewed or braised in a rich, savory sauce. The dish is a staple of riverside meals."]]},{"id":"huainan","zh":"淮南","py":"Huáinán","en":"Huainan","lat":32.63,"lon":116.99,"note":"The home of tofu, as a legend goes.","stops":[["A","八公山","Bā Gōngshān","Bagong Mountain","A gentle hill near Huainan, wrapped in legends. It is best known as the supposed birthplace of tofu and as the site of a famous battle.","",32.63,116.84],["A","寿县古城","Shòuxiàn Gǔchéng","Shouxian Ancient City","A walled town that still has its Song-dynasty city wall, among the best preserved in China. Locals say the wall has kept out floods for centuries.","",32.58,116.78],["D","八公山豆腐","Bā gōngshān dòufǔ","Bagongshan tofu","Soft tofu made in the hills where, according to legend, it was first invented. Tofu here is steamed, fried and simmered in many ways.","A legend says Liu An, a Han-dynasty prince, invented tofu here."],["D","牛肉汤","Niúròutāng","Huainan beef soup","A steaming beef broth that locals drink in the morning with a flatbread, spiced with pepper and coriander."]]},{"id":"maanshan","zh":"马鞍山","py":"Mǎ’ānshān","en":"Ma'anshan","lat":31.69,"lon":118.51,"note":"A steel city on the Yangtze.","stops":[["D","采石矶鱼","Cǎishí jīyú","Caishiji river fish","Fresh fish from the Yangtze at Caishiji, a cliff where the poet Li Bai is said to have died, is steamed or braised with local sauces."]]},{"id":"tongling","zh":"铜陵","py":"Tónglíng","en":"Tongling","lat":30.93,"lon":117.81,"note":"The copper capital of China.","stops":[["D","铜陵白姜","Tónglíng báijiāng","Tongling white ginger","Tongling is known for pale, tender ginger that is pickled or candied, and has been grown here for centuries."]]},{"id":"lu-an","zh":"六安","py":"Lù’ān","en":"Lu'an","lat":31.73,"lon":116.52,"note":"A city of green tea and revolution.","stops":[["A","天堂寨","Tiāntángzhài","Tiantangzhai","A forest park high in the Dabie Mountains, with waterfalls, mossy rocks and cool air. It is a favorite summer escape.","",31.1,115.76],["D","六安瓜片茶","Lù’ān guāpiàn chá","Lu'an melon-seed tea","One of China's famous teas, made from single leaves without stems or buds, rolled flat like melon seeds, with a fresh and mellow taste."],["D","霍山黄芽","Huòshān huángyá","Huoshan Huangya tea","A rare yellow tea from the Huoshan hills. Its leaves are gently piled and slowly dried to give a soft, sweet flavor."]]},{"id":"suzhou-ah","zh":"宿州","py":"Sùzhōu","en":"Suzhou (Anhui)","lat":33.64,"lon":116.96,"note":"A northern city, known for the Grand Canal.","stops":[["D","符离集烧鸡","Fúlí jí shāojī","Fuliji roast chicken","A well-known braised chicken, so tender that the meat falls off the bone. It has been a gift and a snack for travelers for generations."]]},{"id":"fuyang","zh":"阜阳","py":"Fùyáng","en":"Fuyang","lat":32.89,"lon":115.81,"note":"A northern Anhui city.","stops":[["D","格拉条","Gélā tiáo","Gelatiao","A cold noodle dish of thick, chewy strips tossed in garlic, vinegar, chili and sesame sauce, popular in summer in Fuyang."],["D","阜阳卷馍","Fùyáng juǎnmó","Fuyang rolled bread","A soft steamed bread rolled around vegetables, egg or meat, a handy and filling breakfast in northern Anhui."]]},{"id":"xuancheng","zh":"宣城","py":"Xuānchéng","en":"Xuancheng","lat":30.94,"lon":118.76,"note":"The home of Xuan paper and ink brushes.","stops":[["D","宣城板鸭","Xuānchéng bǎnyā","Xuancheng cured duck","Salted, pressed and dried duck, steamed or boiled until tender and savory, a local specialty for the cold months."]]},{"id":"bozhou","zh":"亳州","py":"Bózhōu","en":"Bozhou","lat":33.84,"lon":115.78,"note":"A city of Chinese medicine and liquor.","stops":[["D","古井贡酒","Gǔjǐng gòngjiǔ","Gujing Gong liquor","A famous baijiu made in Bozhou with water from an ancient well. It was said to be offered as a tribute to emperors."],["D","亳州药材","Bózhōu yàocái","Bozhou herbs","Bozhou is one of China's great herb trading centers, where markets stack roots, flowers and seeds used in traditional medicine."]]},{"id":"chuzhou","zh":"滁州","py":"Chúzhōu","en":"Chuzhou","lat":32.3,"lon":118.32,"note":"A hill city with an essay in its name.","stops":[["A","醉翁亭","Zuìwēngtíng","Old Drunkard's Pavilion","A small pavilion in the hills of Chuzhou made famous by Ouyang Xiu's essay, in which a drunken old man finds joy in the mountains, not in wine.","",32.28,118.28],["D","滁州菜","Chúzhōu cài","Chuzhou dishes","Chuzhou's mountain cooking features wild vegetables, bamboo shoots, river fish and simple, hearty stews."]]},{"id":"huaibei","zh":"淮北","py":"Huáiběi","en":"Huaibei","lat":33.97,"lon":116.8,"note":"A coal city in the north.","stops":[["D","淮北烧烤","Huáiběi shāokǎo","Huaibei barbecue","A street barbecue of skewered meat and vegetables, grilled over charcoal, and a lively evening tradition in northern Anhui."]]}],"air":{"zh":"合肥新桥国际机场","py":"Héféi Xīnqiáo Guójì Jīchǎng","en":"Hefei Xinqiao International Airport","code":"HFE","lat":31.99,"lon":116.98,"note":"The main airport of Anhui. Welcome to Anhui."}},{"id":"fujian","zh":"福建","py":"Fújiàn","en":"Fujian","cities":[{"id":"fuzhou","zh":"福州","py":"Fúzhōu","en":"Fuzhou","lat":26.07,"lon":119.3,"note":"The capital of Fujian, known as the Banyan City.","stops":[["A","三坊七巷","Sānfāng Qīxiàng","Three Lanes and Seven Alleys","A walled-in quarter of white-washed lanes in Fuzhou, once home to scholars, officials and writers, with old courtyard houses and carved doorways.","",26.09,119.3],["A","鼓山","Gǔshān","Drum Mountain","A forested mountain above Fuzhou, known for its temple, its stone inscriptions carved into the rock and its views of the city and river.","",26.04,119.41],["A","涌泉寺","Yǒngquánsì","Yongquan Temple","A large Buddhist temple on Drum Mountain, with halls rising up the hillside among tall trees. It has been a center of Chan Buddhism for centuries.","",26.04,119.41],["D","佛跳墙","Fútiàoqiáng","Buddha Jumps Over the Wall","Fuzhou's grandest dish is a slow-cooked soup of abalone, sea cucumber, shark fin substitutes and more. Its name means Buddha Jumps Over the Wall, because even a monk could not resist the smell.","",null,null,1],["D","鱼丸","Yúwán","Fuzhou fish balls","Fuzhou fish balls are springy, with a pocket of seasoned pork in the middle, and are served in a light, clear broth."],["D","肉燕","Ròuyàn","Rouyan","A Fuzhou delicacy, with a wrapper made by pounding lean pork into a thin, silky sheet, wrapped around a savory meat filling and served in soup."],["D","福州线面","Fúzhōu xiànmiàn","Fuzhou thread noodles","Extremely thin, salted wheat noodles dried in long strands. They are eaten on birthdays, as a wish for a long life."],["C","寿山石","Shòushānshí","Shoushan stone","A soft, colorful stone from Shoushan that is carved into seals, animals and tiny landscapes. Fine pieces are treasured by collectors."],["C","闽剧","Mǐnjù","Min opera","The local opera of Fuzhou, sung in the Fuzhou dialect, with lively tunes and a long tradition of folk tales."]]},{"id":"xiamen","zh":"厦门","py":"Xiàmén","en":"Xiamen","lat":24.48,"lon":118.09,"note":"A garden island city by the sea.","stops":[["A","鼓浪屿","Gǔlàngyǔ","Gulangyu","A tiny car-free island off Xiamen, with winding lanes, old foreign-style villas and the sound of pianos drifting from the windows. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",24.45,118.07,1],["A","厦门大学","Xiàmén Dàxué","Xiamen University","A university on the seashore, with a beautiful campus of red-roofed buildings, banyan trees and a beach next to the lecture halls.","",24.44,118.1],["A","南普陀寺","Nánpǔtuó Sì","Nanputuo Temple","A Buddhist temple at the foot of a green hill, next to Xiamen University. Visitors come for its halls, its vegetarian restaurant and its views of the sea.","",24.44,118.1],["A","曾厝垵","Céngcuò’ǎn","Zengcuo'an","A former fishing village in Xiamen that is now a lively lane of cafés, snack stalls and small guesthouses, busy until late in the evening.","",24.43,118.12],["A","日光岩","Rìguāngyán","Sunlight Rock","The highest point of Gulangyu, from where you can look down on red roofs, the harbor and the high-rises of Xiamen across the water.","",24.45,118.07],["D","沙茶面","Shāchá miàn","Satay noodles","Xiamen's signature noodles in a rich, savory broth with a peanut, shrimp and spice paste called shacha, served with seafood and pork."],["D","土笋冻","Tǔsǔn dòng","Tusun jelly","A jelly made from small sea worms, boiled until they set. It is eaten cold with vinegar and garlic and is a bold local snack."],["D","海蛎煎","Hǎilì jiān","Oyster omelet","A crispy street omelet of small oysters, eggs and starch, fried in a pan and eaten with a sweet and spicy sauce."],["D","花生汤","Huāshēng tāng","Peanut soup","A warm sweet soup of soft, tender peanuts, often eaten with a fried dough stick, and a typical comforting snack in Xiamen."],["D","馅饼","Xiànbǐng","Xiamen pies","The Xiamen pie is a flaky, golden pastry with a sweet mung bean and sugar filling, often given as a gift."],["C","高甲戏","Gāojiǎxì","Gaojia opera","A Fujian opera from the Quanzhou and Xiamen region, known for its funny characters, lively acting and humor."]]},{"id":"quanzhou","zh":"泉州","py":"Quánzhōu","en":"Quanzhou","lat":24.87,"lon":118.68,"note":"A medieval port at the start of the Maritime Silk Road.","stops":[["A","开元寺","Kāiyuánsì","Kaiyuan Temple","A large temple in Quanzhou with two tall stone pagodas that stand opposite each other and have survived for about 800 years.","",24.91,118.58],["A","清净寺","Qīngjìngsì","Qingjing Mosque","One of the oldest mosques in China, first built in 1009 when Quanzhou was a great port with Arab merchants. Parts of its stone gate still stand.","",24.9,118.59],["A","洛阳桥","Luòyángqiáo","Luoyang Bridge","A long stone bridge across a tidal river, built in the 11th century. Its builders used oysters to bind the stones together.","",24.94,118.69],["A","天后宫","Tiānhòugōng","Tianhou Temple","A temple to Mazu, the goddess of the sea, who is prayed to for safe voyages. It is one of the oldest Mazu temples.","",24.9,118.6],["A","清源山","Qīngyuánshān","Qingyuan Mountain","A hill north of Quanzhou with temples, rock carvings and a huge stone statue of Laozi, the founder of Daoism, said to date from the Song dynasty.","",24.95,118.6],["A","西街","Xījiē","West Street","A busy old street in Quanzhou, lined with traditional shopfronts, snack stalls and the stone pagodas of Kaiyuan Temple at one end.","",24.91,118.58],["D","面线糊","Miànxiàn hú","Mianxian hu","A thick, savory noodle soup, in which fine noodles are cooked until they melt into a gravy. It is a typical Quanzhou breakfast."],["D","姜母鸭","Jiāng mǔyā","Ginger duck","A duck slowly braised with lots of ginger and rice wine in a clay pot, warm and strong, and eaten in winter."],["D","牛肉羹","Niúròu gēng","Beef thick soup","A thick, savory beef soup, thickened with starch and often topped with herbs and pepper."],["C","提线木偶","Tíxiànmù’ǒu","Quanzhou string puppets","Quanzhou's string puppets are small wooden figures moved with fine strings. They are a highly refined craft in which puppeteers perform stories in a lifelike way."],["C","梨园戏","Líyuánxì","Liyuan opera","An opera of Quanzhou with a history of about 800 years, sung in the Minnan language. Its slow, graceful movements are famous."]]},{"id":"zhangzhou","zh":"漳州","py":"Zhāngzhōu","en":"Zhangzhou","lat":24.51,"lon":117.65,"note":"A city of flowers and fruit.","stops":[["A","南靖土楼","Nánjìng Tǔlóu","Nanjing Tulou","Huge round houses of rammed earth, built by Hakka families who lived together in them. They sit among green hills and rice fields and are a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",24.67,117.4,1],["A","东山岛","Dōngshāndǎo","Dongshan Island","An island off the coast of Zhangzhou with white sandy beaches, rocky shores and fishing villages.","",23.65,117.45],["D","漳州卤面","Zhāngzhōu lǔmiàn","Zhangzhou lu noodles","Noodles braised in a thick, savory sauce with seafood and pork, a hearty dish at weddings and festivals."],["D","水仙花","Shuǐxiānhuā","Zhangzhou narcissus","The narcissus of Zhangzhou is known across China. People grow bulbs in water and carve them, so they bloom for the New Year."],["D","平和蜜柚","Pínghé mìyòu","Pinghe pomelo","The Pinghe honey pomelo is a large, juicy and sweet pomelo, and one of the best-known fruits in Fujian."]]},{"id":"putian","zh":"莆田","py":"Pútián","en":"Putian","lat":25.45,"lon":119.01,"note":"The birthplace of Mazu, the sea goddess.","stops":[["A","湄洲岛","Méizhōudǎo","Meizhou Island","The home island of Mazu, the sea goddess whom people across the coast and Taiwan worship. Pilgrims come to its main temple to pray for safety on the water.","",25.07,119.12,1],["D","莆田卤面","Pútián lǔmiàn","Putian lu noodles","Putian's version of braised noodles is cooked with clams, shrimp, pork and vegetables in a rich broth."],["D","莆田荔枝","Pútián lìzhī","Putian lychee","Lychee from Putian has been famous for a long time. Its fruit is sweet and juicy, and is harvested in early summer."],["D","兴化米粉","Xīnghuà mǐfěn","Xinghua rice noodles","Thin rice noodles, stir-fried with seafood, mushrooms and vegetables, and a popular dish for family gatherings."]]},{"id":"nanping","zh":"南平","py":"Nánpíng","en":"Nanping","lat":26.64,"lon":118.18,"note":"A mountain city of tea, in the Wuyi area.","stops":[["A","武夷山","Wǔyíshān","Wuyi Mountain","A UNESCO World Heritage Site where red cliffs rise above a winding river. It is the home of famous teas, and a favorite place to take a bamboo raft.","A UNESCO World Heritage Site.",27.73,118.03,1],["A","天游峰","Tiānyóufēng","Tianyou Peak","A tall peak in the Wuyi Mountains, reached by a steep stone staircase. The reward is a view of the winding Nine Bend Stream.","",27.72,118.02],["D","岩茶","Yánchá","Wuyi rock tea","A roasted oolong tea grown among the rocky cliffs of Wuyi. Its leaves pick up the minerals of the rock, giving a deep and lasting flavor. Dahongpao is the most famous.","",null,null,1],["D","正山小种","Zhèngshān xiǎozhǒng","Lapsang souchong","The first black tea in the world, born in Wuyi. Its leaves are dried over pine wood fire, which gives the tea a smoky taste."],["D","武夷山笋","Wǔyíshān sǔn","Wuyi bamboo shoots","Fresh bamboo shoots from the Wuyi hills, cut in spring and stir-fried or stewed in soup, with a crisp and sweet taste."],["D","建瓯板鸭","Jiàn’ōu bǎnyā","Jian'ou cured duck","A flat, salted and air-dried duck from Jian'ou, which is steamed or braised. It has a rich, savory flavor and keeps for months."],["C","茶艺","Cháyì","Tea art","The art of preparing oolong tea in Fujian. A small teapot and tiny cups are used for several quick infusions to bring out the changing flavors."]]},{"id":"sanming","zh":"三明","py":"Sānmíng","en":"Sanming","lat":26.26,"lon":117.64,"note":"A forest city of the central mountains.","stops":[["A","泰宁古城","Tàiníng Gǔchéng","Taining Ancient Town","An old town in the hills with Ming-era houses, stone gates and a lake of red cliffs nearby, with few crowds.","",26.9,117.17],["D","沙县小吃","Shāxiàn xiǎochī","Shaxian snacks","Humble snack shops, with simple noodles, dumplings and soups, that can be found in cities all over China. They began in the small town of Shaxian."],["D","清流笋干","Qīngliú sǔngān","Qingliu dried bamboo","Bamboo shoots dried in the sun of Qingliu, which are then rehydrated and stewed with meat in many dishes."]]},{"id":"longyan","zh":"龙岩","py":"Lóngyán","en":"Longyan","lat":25.08,"lon":117.02,"note":"The Hakka heartland with earth buildings.","stops":[["A","永定土楼","Yǒngdìng Tǔlóu","Yongding Tulou","Hakka round earth houses in Yongding, among the largest in Fujian, with several floors, hundreds of rooms and a courtyard in the middle.","A UNESCO World Heritage Site.",24.7,116.8],["A","承启楼","Chéngqǐlóu","Chengqi Tower","Known as the king of tulou, it has four concentric rings of rooms and holds hundreds of people, built over three centuries ago.","",24.62,116.97],["D","客家酿豆腐","Kèjiā niàng dòufǔ","Hakka stuffed tofu","A Hakka comfort dish of tofu stuffed with seasoned minced pork, fried and gently simmered. It is often eaten at the New Year."],["D","永定菜干","Yǒngdìng càigàn","Yongding dried greens","Vegetables dried in the sun in the Hakka region, a staple that could be kept for a long time and used all year in stews."]]},{"id":"ningde","zh":"宁德","py":"Níngdé","en":"Ningde","lat":26.66,"lon":119.55,"note":"A coastal city of tea, bays and a big battery maker.","stops":[["D","福鼎白茶","Fúdǐng báichá","Fuding white tea","A mild white tea from Fuding, made from downy buds that are only withered and dried, and has a light and sweet taste."],["D","大黄鱼","Dàihuángyú","Large yellow croaker","The large yellow croaker is a prized fish in Ningde, with golden skin and tender meat. It is steamed or braised."]]},{"id":"pingtan","zh":"平潭","py":"Píngtán","en":"Pingtan","lat":25.5,"lon":119.79,"note":"An island county closest to Taiwan.","stops":[["D","平潭海鲜","Píngtán hǎixiān","Pingtan seafood","Pingtan is an island county whose restaurants serve just-caught crabs, shellfish and fish with simple seasonings."]]},{"id":"wuyishan","zh":"武夷山市","py":"Wǔyíshān Shì","en":"Wuyishan City","lat":27.76,"lon":118.04,"note":"The tea town at the foot of Wuyi Mountain.","stops":[["D","武夷茶","Wǔyíchá","Wuyi tea","The tea of the Wuyi region, known for centuries and part of its identity. It includes rock teas and black teas."]]}],"air":{"zh":"福州长乐国际机场","py":"Fúzhōu Chánglè Guójì Jīchǎng","en":"Fuzhou Changle International Airport","code":"FOC","lat":25.93,"lon":119.66,"note":"The main airport of Fuzhou, on the coast. Welcome to Fujian."}},{"id":"gansu","zh":"甘肃","py":"Gānsù","en":"Gansu","cities":[{"id":"lanzhou","zh":"兰州","py":"Lánzhōu","en":"Lanzhou","lat":36.06,"lon":103.83,"note":"A long river city on the Yellow River.","stops":[["A","中山桥","Zhōngshān Qiáo","Zhongshan Bridge","Known as the first iron bridge on the Yellow River, it was built in 1909 and is now a walking bridge in the heart of Lanzhou.","",36.06,103.83],["A","白塔山","Báitǎshān","White Pagoda Hill","A hill on the north bank of the Yellow River with a white pagoda on top. Stairs and pavilions lead up to a view over the city and the river.","",36.07,103.83],["A","黄河母亲雕塑","Huánghé Mǔqīn Diāosù","Mother Yellow River Sculpture","A calm stone mother sits by the river with a laughing baby, a symbol of the Yellow River as the mother river of China.","",36.06,103.81],["A","甘肃省博物馆","Gānsùshěng Bówùguǎn","Gansu Provincial Museum","The museum holds the Flying Horse of Gansu, a Han bronze horse with one hoof on a swallow, and many treasures from the Silk Road.","",36.07,103.75],["A","五泉山","Wǔquán Shān","Five Springs Mountain","A park on the slope of a hill south of Lanzhou, with springs, old temples and gardens, a quiet place away from the busy city.","",36.04,103.83],["D","兰州牛肉面","Lánzhōu niúròumiàn","Lanzhou beef noodles","Hand-pulled noodles in clear beef broth with a bright chili oil, green coriander, white radish and yellow noodles. Locals eat it for breakfast and it is a symbol of Lanzhou.","Said to follow the rule of one clear, two white, three red, four green, five yellow.",null,null,1],["D","手抓羊肉","Shǒuzhuā yángròu","Hand-grabbed mutton","Mutton boiled with simple spices until tender, then picked up with the hands and eaten with salt or garlic sauce. It is a classic way to eat in northwest China."],["D","酿皮","Niàngpí","Niangpi","Cool, springy noodles made from wheat or rice starch, tossed with chili oil, vinegar and sesame. Perfect for a hot day."],["D","百合","Bǎihé","Lanzhou lily","Lanzhou lily bulbs are sweet and not bitter, and are famous in China. They are cooked in soups or eaten as a sweet snack."],["D","甜醅","Tiánpēi","Tianpei","A sweet drink made by fermenting oats or barley. Its taste is gently sweet with a touch of wine and cools you on a warm day."],["D","灰豆子","Huī dòuzi","Huidouzi","A warm sweet dessert of pea beans stewed with sugar and spices, a street treat in winter in Lanzhou."]]},{"id":"dunhuang","zh":"敦煌","py":"Dūnhuáng","en":"Dunhuang","lat":40.14,"lon":94.66,"note":"An oasis at the end of the Hexi Corridor, known for Buddhist art.","stops":[["A","莫高窟","Mògāokū","Mogao Caves","Hundreds of cave temples carved into a desert cliff over a thousand years, filled with Buddhist murals and statues. They are a UNESCO World Heritage Site and a treasure of the Silk Road.","A UNESCO World Heritage Site.",40.04,94.8,1],["A","鸣沙山","Míngshāshān","Singing Sand Dunes","Huge golden dunes outside Dunhuang that are said to make a sound when the sand moves. Visitors climb the ridge or ride camels.","",40.09,94.68],["A","月牙泉","Yuèyáquán","Crescent Moon Spring","A crescent-shaped spring that has been surrounded by dunes for thousands of years and has never dried up, a rare green oasis.","",40.09,94.67],["A","玉门关","Yùménguān","Yumen Pass","A Han-dynasty frontier pass at the edge of the desert, once the gateway to the West and sung about in many poems.","",40.36,93.86],["A","阳关","Yángguān","Yang Pass","A pass south of Dunhuang that was another gate to the Silk Road. Travelers crossing it left their homeland and entered the unknown.","",39.88,93.9],["A","藏经洞","Cángjīngdòng","Library Cave","A small hidden cave at Mogao in which more than 50,000 scrolls and documents were found in 1900, a priceless record of life along the Silk Road.","",40.04,94.8],["D","驴肉黄面","Lǘròu huángmiàn","Donkey meat yellow noodles","Yellow noodles, made with alkaline water, served with slices of braised donkey meat, a savory and filling dish in Dunhuang."],["D","杏皮茶","Xìngpí chá","Apricot peel tea","A cold drink of dried apricot peel, sugar and herbs. It is sweet, sour and very refreshing in the dry heat of the desert."],["D","敦煌李广杏","Dūnhuáng lǐguǎng xìng","Dunhuang Li Guang apricot","A sweet apricot grown in Dunhuang's oasis, named after the Han general Li Guang, and ripe in early summer."],["C","敦煌壁画","Dūnhuáng bìhuà","Dunhuang murals","Paintings on the cave walls tell Buddhist tales and show daily life, music and dance. Some of the colors have lasted for more than a thousand years."],["C","飞天","Fēitiān","Flying apsaras","Graceful flying figures in the Mogao murals, with ribbons streaming behind them. They have become a symbol of Dunhuang."],["C","反弹琵琶","Fǎntán pípá","Pipa behind the back","A famous pose from the Dunhuang murals, in which a dancer plays the pipa behind her back while she dances. It is an emblem of Dunhuang art."]]},{"id":"jiayuguan","zh":"嘉峪关","py":"Jiāyùguān","en":"Jiayuguan","lat":39.77,"lon":98.29,"note":"The western end of the Ming Great Wall.","stops":[["A","嘉峪关关城","Jiāyùguān Guānchéng","Jiayuguan Fort","A great Ming fortress at the western end of the Great Wall, with strong gates and towers. In the past it marked the edge of the empire.","",39.8,98.21,1],["A","悬壁长城","Xuánbì Chángchéng","Overhanging Great Wall","A section of the Great Wall that climbs a very steep ridge at an angle near Jiayuguan, and is rebuilt after the Ming dynasty.","",39.84,98.3],["D","烤羊肉","Kǎoyángròu","Roast mutton","Skewered or roasted mutton cooked over fire with cumin and chili is a staple of an evening in the northwest."],["D","嘉峪关烤饼","Jiāyùguān kǎobǐng","Jiayuguan baked bread","A round flatbread baked in an oven until golden and crisp, often eaten with mutton or soup."]]},{"id":"zhangye","zh":"张掖","py":"Zhāngyē","en":"Zhangye","lat":38.93,"lon":100.45,"note":"A city of rainbow mountains and an old temple.","stops":[["A","张掖丹霞","Zhāngyē Dānxiá","Zhangye Danxia","Hills striped in red, orange, yellow and white, like a painted landscape. Colors glow in the light of the evening, and it is part of a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",38.93,100.12,1],["A","七彩丹霞","Qīcǎi Dānxiá","Rainbow Mountains","The popular name for the rainbow-colored hills of Zhangye, where thin layers of different minerals have been shaped by wind and rain.","",38.93,100.12],["A","马蹄寺","Mǎtísì","Mati Temple","A group of cave temples in the Qilian foothills, near a rock where a horse is said to have left a hoofprint.","",38.55,100.5],["D","张掖搓鱼面","Zhāngyē cuō yúmiàn","Zhangye finger noodles","Short noodles rolled by hand into tapered fish shapes and served with a savory sauce, a favorite in Zhangye."],["D","张掖肉夹馍","Zhāngyē ròujiāmó","Zhangye meat bun","Tender braised meat tucked into a baked bun, a northwest classic enjoyed all over Gansu."]]},{"id":"tianshui","zh":"天水","py":"Tiānshuǐ","en":"Tianshui","lat":34.58,"lon":105.72,"note":"The home of the Maijishan Grottoes.","stops":[["A","麦积山石窟","Màijīshān Shíkū","Maijishan Grottoes","Cave temples carved on a lone cliff that looks like a haystack. Hundreds of caves hold clay statues with gentle smiles. It is part of the Silk Road UNESCO site.","A UNESCO World Heritage Site.",34.35,105.87,1],["A","伏羲庙","Fúxīmiào","Fuxi Temple","A temple to Fuxi, a mythical ancestor who taught people to fish and drew the eight trigrams. It is a grand ancient hall in Tianshui.","",34.58,105.72],["D","呱呱","Gūgū","Gua gua","A cold dish of soft buckwheat jelly, served with chili oil, vinegar and garlic, a street snack of Tianshui."],["D","天水荞面","Tiānshuǐ qiáomiàn","Tianshui buckwheat noodles","Noodles made from buckwheat, served in a savory soup or with a spicy sauce. They taste earthy and slightly sweet."]]},{"id":"linxia","zh":"临夏","py":"Línxià","en":"Linxia","lat":35.6,"lon":103.21,"note":"A Hui city, called Little Mecca.","stops":[["A","炳灵寺","Bǐnglíng Sì","Bingling Temple","A cave temple complex on the Yellow River, reached by boat across a reservoir, with a giant Buddha carved into the cliff.","",35.8,103.07],["D","烤包子","Kǎo bāozi","Roasted dumplings","Dumplings baked in a hot oven until the skin is crisp and the mutton filling is juicy, a common treat in Linxia."],["C","砖雕","Zhuāndiāo","Brick carving","Linxia is famous for its carved brick work, with fine flowers and landscapes cut by hand on gateways and screen walls."]]},{"id":"pingliang","zh":"平凉","py":"Píngliáng","en":"Pingliang","lat":35.54,"lon":106.67,"note":"The home of Kongtong Mountain.","stops":[["A","崆峒山","Kōngdòngshān","Kongtong Mountain","A mountain of temples and cliffs that is famous in Taoism and martial arts stories as a place where masters trained.","",35.55,106.5],["D","平凉烧鸡","Píngliáng shāojī","Pingliang braised chicken","A chicken cooked slowly with spices until it falls apart, a well-known local dish."]]},{"id":"jiuquan","zh":"酒泉","py":"Jiǔquán","en":"Jiuquan","lat":39.74,"lon":98.5,"note":"A desert city and the home of a space launch center.","stops":[["A","酒泉卫星发射中心","Jiǔquán Wèixīng Fāshè Zhōngxīn","Jiuquan Satellite Launch Center","China's first space launch center in the Gobi desert, where its crewed spaceflights take off.","",40.96,100.29],["D","酒泉夜光杯","Jiǔquán yèguāngbēi","Jiuquan luminous cups","Thin cups carved from local green jade, said to glow at night. A poem from the Tang dynasty made them famous."],["D","酒泉烤羊肉","Jiǔquán kǎoyángròu","Jiuquan roast lamb","Grilled lamb seasoned with cumin and salt, with a smoky aroma, a typical dish of the desert oasis."]]},{"id":"wuwei","zh":"武威","py":"Wǔwēi","en":"Wuwei","lat":37.93,"lon":102.64,"note":"A city of the Hexi corridor and the Flying Horse.","stops":[]},{"id":"longnan","zh":"陇南","py":"Lǒngnán","en":"Longnan","lat":33.4,"lon":104.92,"note":"A green southern city on the Bailong River.","stops":[["D","陇南橄榄油","Lǒngnán gǎnlǎnyóu","Longnan olive oil","Wudu in Longnan is a rare place in China where olives grow, and its olive oil is a regional specialty."],["D","武都花椒","Wǔdū huājiāo","Wudu Sichuan pepper","A famous Sichuan pepper from Wudu, with a strong fragrance and a tingling taste that fills many Chinese dishes."]]},{"id":"gannan","zh":"甘南","py":"Gānnán","en":"Gannan","lat":34.99,"lon":102.91,"note":"A Tibetan area with grasslands.","stops":[["A","拉卜楞寺","Lāboléng Sì","Labrang Monastery","One of the six great monasteries of the Gelug school of Tibetan Buddhism, with golden roofs, prayer wheels and monks in red.","",35.2,102.51],["A","郎木寺","Lángmùsì","Langmusi","A small town on the Gansu-Sichuan border with two monasteries, a river and green hills. Tibetans, Hui and Han people live here together.","",34.1,102.64],["A","桑科草原","Sāngkē Cǎoyuán","Sangke Grassland","A wide, high grassland where yaks and sheep graze under big skies. Tibetan tents and wildflowers dot the summer pastures.","",35.14,102.45],["D","酸奶","Suānnǎi","Yak yogurt","Thick yogurt made from yak milk, tangy and rich, often eaten with sugar or tsampa on the plateau."],["D","糌粑","Zānbā","Tsampa","Roasted barley flour that is mixed with butter tea into a dough and eaten by hand, a daily staple for Tibetan herders."]]}],"air":{"zh":"兰州中川国际机场","py":"Lánzhōu Zhōngchuān Guójì Jīchǎng","en":"Lanzhou Zhongchuan International Airport","code":"LHW","lat":36.52,"lon":103.62,"note":"The main airport of Gansu, far north of Lanzhou across the hills. Welcome to Gansu."}},{"id":"guangdong","zh":"广东","py":"Guǎngdōng","en":"Guangdong","cities":[{"id":"guangzhou","zh":"广州","py":"Guǎngzhōu","en":"Guangzhou","lat":23.13,"lon":113.26,"note":"The capital of Guangdong, a trading port for two thousand years and the home of dim sum.","stops":[["A","广州塔","Guǎngzhōu Tǎ","Canton Tower","At about 600 meters, the slim, twisting tower on the Pearl River is nicknamed the Small Waist. It glows with colored lights at night and has a high-up observation deck.","",23.11,113.32,1],["A","沙面岛","Shāmiàn Dǎo","Shamian Island","A tiny island of tree-lined streets and 19th-century European-style buildings, once the foreign concession in Guangzhou and now a peaceful place to walk.","",23.11,113.24],["A","陈家祠","Chénjiācí","Chen Clan Ancestral Hall","A grand clan hall built in the 1890s, covered with carved stone, wood, ceramic figures and colored plaster, a showcase of Cantonese craft.","",23.13,113.24],["A","越秀公园","Yuèxiù Gōngyuán","Yuexiu Park","A big hill park in the middle of Guangzhou. Its Five Rams statue recalls the legend that five immortals on rams brought grain to the city.","The Five Rams statue refers to a legend about the city's founding.",23.14,113.26],["A","上下九步行街","Shàngxià Jiǔ Bùxíngjiē","Shangxiajiu Pedestrian Street","An old shopping street of arcaded buildings, packed with snack shops and old brands, a lively place for an evening stroll.","",23.12,113.24],["A","珠江夜游","Zhūjiāng Yèyóu","Pearl River Night Cruise","A boat ride along the Pearl River in the evening, passing glowing skyscrapers, old bridges and the Canton Tower in lights.","",23.11,113.27],["A","白云山","Báiyúnshān","Baiyun Mountain","A green mountain right beside the city, with winding paths, springs and viewpoints, where residents go to hike at the weekend.","",23.18,113.3],["D","早茶","zǎochá","Morning tea (dim sum)","Guangzhou's morning tea is a long, relaxed meal of dim sum, with small steamers, pots of tea and family talk. Some say it is the heart of Cantonese food culture.","",null,null,1],["D","虾饺","Xiājiǎo","Shrimp dumplings","A classic dim sum dumpling in a thin, translucent wrapper, with whole juicy shrimp inside. Making a good one takes real skill."],["D","肠粉","Chángfěn","Rice noodle rolls","Smooth, silky sheets of steamed rice batter rolled around shrimp, beef or pork, then served with a splash of sweet soy sauce."],["D","白切鸡","Báiqiè jī","White-cut chicken","A simple dish that shows off a good chicken. It is gently poached until just cooked, then dipped in ginger and scallion oil."],["D","烧鹅","Shāo’é","Roast goose","Cantonese roast goose has crisp, golden skin and juicy meat, and is often served with plum sauce. It is a treat for celebrations."],["D","煲仔饭","Bāozǎifàn","Clay pot rice","Rice cooked in a clay pot over fire so the bottom turns crisp, topped with cured sausage or chicken, and finished with a splash of sweet soy sauce."],["D","双皮奶","Shuāngpínǎi","Double-skin milk pudding","A silky steamed milk pudding with two thin layers of skin, sweet and smooth, one of the most popular desserts in Guangdong."],["D","艇仔粥","Tǐng zǎizhōu","Boat congee","A silky congee with fish slices, squid, peanuts and crisp fried strips. It was first sold from small boats on the river."],["C","粤剧","Yuèjù","Cantonese opera","Cantonese opera combines singing, acrobatics, martial arts and costumes in the Cantonese language. It is a UNESCO intangible heritage and is loved by Cantonese communities worldwide.","",null,null,1],["C","广彩","Guǎngcǎi","Guangcai porcelain","Porcelain painted in bright colors and gold in Guangzhou, much of it was made for sale to Europe and is now a collectible art."],["C","凉茶","Liángchá","Herbal tea","Bitter herbal drinks that many in southern China drink to cool the body in the hot, humid weather. Shops sell it by the cup."]]},{"id":"shenzhen","zh":"深圳","py":"Shēnzhèn","en":"Shenzhen","lat":22.54,"lon":114.06,"note":"A fishing town that became a giant technology city in a few decades.","fun":"Its population grew from tens of thousands to over ten million within about 40 years.","stops":[["A","世界之窗","Shìjiè Zhī Chuāng","Window of the World","A theme park in Shenzhen with miniature versions of the Eiffel Tower, the Pyramids and other famous sights, so you can see the world in one day.","",22.54,113.97],["A","大芬油画村","Dàfēn Yóuhuà Cūn","Dafen Oil Painting Village","A village in Shenzhen where thousands of painters copy famous artworks and also paint their own creations. It ships paintings all over the world.","",22.6,114.14],["A","华强北","Huáqiángběi","Huaqiangbei","The famous electronics market of Shenzhen, where stalls sell chips, phones, drones and every kind of gadget, and where many ideas begin.","",22.54,114.09],["D","潮汕牛肉火锅","Cháoshàn niúròu huǒguō","Chaoshan beef hotpot","Thin slices of fresh beef are dipped in a light broth for a few seconds, then eaten with a sand tea dip. Different cuts have their own names."],["C","客家围屋","Kèjiā wéiwū","Hakka walled villages","Walled villages of the Hakka people, with strong outer walls and houses around a courtyard, built so that clans could defend themselves.","",22.69,114.21]]},{"id":"foshan","zh":"佛山","py":"Fóshān","en":"Foshan","lat":23.02,"lon":113.12,"note":"A city of kung fu, ceramics and old lanes next to Guangzhou.","stops":[["A","祖庙","Zǔmiào","Ancestral Temple","A temple in Foshan dating from the Song dynasty, with beautiful roof ceramics and a hall for martial arts, linked to Wing Chun and Wong Fei-hung.","",23.03,113.11],["A","黄飞鸿纪念馆","Huángfēihóng Jìniànguǎn","Wong Fei-hung Memorial Hall","A memorial hall for Wong Fei-hung, a martial arts master and doctor of Foshan, whose life inspired many kung fu films.","He is the subject of many Hong Kong kung fu films.",23.03,113.11],["A","南风古灶","Nánfēng Gǔzào","Nanfeng Ancient Kiln","A dragon kiln built on a hillside over 500 years ago that is still fired to make pottery, one of the oldest working kilns in China.","",23.0,113.05],["D","顺德双皮奶","Shùndé shuāngpínǎi","Shunde milk pudding","A milk pudding from Shunde, where the dessert is thought to have been born. Shunde is called the food capital of Guangdong."],["D","均安蒸猪","Jūn’ānzhēng zhū","Steamed pig of Junan","A festive Junan dish of a whole pig steamed or roasted until the skin is crisp and the meat tender, served at celebrations."],["D","鱼生","Yúshēng","Raw fish slices","Thin slices of raw freshwater fish eaten with ginger, peanuts, herbs and sauces. It is a Shunde specialty and a shared dish."],["C","咏春拳","Yǒngchūnquán","Wing Chun","Wing Chun is a close-range kung fu style of quick, direct moves, said to have been developed by a woman. Foshan is one of its homes."],["C","剪纸","Jiǎnzhǐ","Foshan paper cuts","Foshan's cut-paper art uses scissors or knives to make flowers, animals and scenes, often in bright colors and for festivals."]]},{"id":"zhuhai","zh":"珠海","py":"Zhūhǎi","en":"Zhuhai","lat":22.27,"lon":113.58,"note":"A coastal city with islands, cycling paths and a border with Macau.","stops":[["A","圆明新园","Yuánmíng Xīnyuán","New Yuanmingyuan","A theme park in Zhuhai that rebuilds scenes of the old Yuanmingyuan palace gardens in Beijing, which was burned down in 1860.","",22.28,113.52],["D","横山蚝","Héngshān háo","Hengshan oysters","Big plump oysters from Hengshan, grilled with garlic and chili and served hot from the grill, a favorite seafood in Zhuhai."]]},{"id":"dongguan","zh":"东莞","py":"Dōngguǎn","en":"Dongguan","lat":23.02,"lon":113.75,"note":"A factory city that makes a lot of the world's products.","stops":[["A","可园","Kěyuán","Keyuan Garden","A small, elegant garden in Lingnan style, with a winding layout, halls and a tower with a view over the water.","",23.05,113.74],["A","鸦片战争博物馆","Yāpiànzhànzhēng Bówùguǎn","Opium War Museum","A museum at the old forts near Humen, where Lin Zexu burned seized opium in 1839, before the start of the First Opium War.","",22.82,113.62],["D","东莞烧鹅","Dōngguǎn shāo’é","Dongguan roast goose","Crisp roast goose from the Qingxi area of Dongguan, with a juicy, flavorful meat and a famous dipping sauce."],["D","道滘粽","Dàojiàozòng","Daojiao rice dumplings","Large, savory sticky rice dumplings from Daojiao, filled with pork, beans and egg yolk, made for the Dragon Boat Festival."]]},{"id":"shantou","zh":"汕头","py":"Shàntóu","en":"Shantou","lat":23.35,"lon":116.68,"note":"The center of Chaoshan culture on the east coast.","stops":[["D","牛肉丸","Niúròuwán","Beef balls","Hand-pounded beef balls, so springy that they bounce. A Chaoshan specialty and a proud city dish in Shantou."],["D","蚝烙","Háolào","Oyster omelet","A crispy pancake of fresh small oysters in a starchy egg batter, fried until golden and served with fish sauce."],["D","粿条","Guǒtiáo","Flat rice noodles","Flat rice noodles, either in a clear broth with meat and herbs or stir-fried over high heat, popular in the Chaoshan area."],["C","工夫茶","Gōngfuchá","Gongfu tea","Gongfu tea is brewed in tiny cups and a small pot with careful steps. It is the heart of Chaoshan hospitality, and almost every home has a set."]]},{"id":"chaozhou","zh":"潮州","py":"Cháozhōu","en":"Chaozhou","lat":23.66,"lon":116.62,"note":"An old city with a famous stone bridge and a strong food tradition.","stops":[["A","开元寺","Kāiyuánsì","Kaiyuan Temple","A Buddhist temple in Chaozhou founded in the Tang dynasty and known for its old halls, stone pillars and calm courtyards.","",23.66,116.62],["D","潮州牛肉丸","Cháozhōu niúròuwán","Chaozhou beef balls","Chaozhou beef balls are known for their bounce and fresh beefy flavor, and are served in a clear soup."],["D","卤鹅","Lǔ’é","Braised goose","Goose simmered slowly in a spiced master sauce until tender, then sliced and served with garlic vinegar. A famous Chaozhou dish."],["C","潮州木雕","Cháozhōu mùdiāo","Chaozhou wood carving","Chaozhou carvers cut deep and detailed scenes in wood, covered in gold paint. They decorate temples, halls and old family houses."]]},{"id":"zhaoqing","zh":"肇庆","py":"Zhàoqìng","en":"Zhaoqing","lat":23.05,"lon":112.47,"note":"A lakeside city with limestone hills and a Ming-dynasty wall.","stops":[["A","七星岩","Qīxīngyán","Seven Star Crags","Seven limestone peaks that rise from a lake in Zhaoqing, like the stars of the Big Dipper, with caves, bridges and paths.","",23.1,112.48],["A","鼎湖山","Dǐnghúshān","Dinghu Mountain","A nature reserve of ancient forest, streams and waterfalls near Zhaoqing, one of the oldest protected areas in China.","",23.17,112.54],["D","裹蒸粽","Guǒzhēngzòng","Guozheng zongzi","A big pillow-shaped rice dumpling, wrapped in leaves with pork, mung beans and salted egg yolk, steamed for hours."],["C","端砚","Duānyàn","Duan inkstone","Duan inkstones are made from a fine stone quarried near Zhaoqing, and are among the most treasured inkstones in China."]]},{"id":"huizhou","zh":"惠州","py":"Huìzhōu","en":"Huizhou","lat":23.11,"lon":114.42,"note":"A lakeside city with a Su Shi connection and a hot-spring coast.","stops":[["A","西湖","Xīhú","Huizhou West Lake","A pretty lake in Huizhou with causeways and bridges, where the poet Su Shi lived in exile and wrote about its charm.","",23.1,114.4],["A","罗浮山","Luófúshān","Luofu Mountain","A Taoist mountain with temples, waterfalls and herbal gardens, long known in Chinese legends and medicine.","",23.27,114.07],["D","东江盐焗鸡","Dōngjiāng yánjújī","Salt-baked chicken","A Hakka dish of chicken wrapped in paper and baked in hot salt, so that the meat is juicy, savory and fragrant."]]},{"id":"zhongshan","zh":"中山","py":"Zhōngshān","en":"Zhongshan","lat":22.52,"lon":113.39,"note":"The hometown of Sun Yat-sen.","stops":[["A","孙中山故居","Sūnzhōngshān Gùjū","Sun Yat-sen Former Residence","The village house where Sun Yat-sen was born in 1866, with a small museum about the man who helped end imperial rule.","",22.45,113.52],["D","脆肉鲩","Cuìròu huàn","Crispy grass carp","Grass carp fed with broad beans for weeks until the meat turns firm and crunchy, then cooked and served in Zhongshan."],["D","石岐乳鸽","Shíqí rǔgē","Shiqi roast pigeon","A young pigeon, roasted until the skin is thin and crispy and the meat juicy, a famous dish of the Shiqi area."]]},{"id":"jiangmen","zh":"江门","py":"Jiāngmén","en":"Jiangmen","lat":22.58,"lon":113.08,"note":"The land of diaolou, towers built by overseas Chinese families.","stops":[["A","开平碉楼","Kāipíng Diāolóu","Kaiping Diaolou","Tall fortified towers, built by families who had worked abroad, that mix Chinese and Western designs. They rise over the fields and are a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",22.37,112.59,1],["D","新会陈皮","Xīnhuì chénpí","Xinhui aged tangerine peel","Dried tangerine peel from Xinhui, aged for years like a fine wine, and used in tea, soups and sweets for its warm aroma."]]},{"id":"shaoguan","zh":"韶关","py":"Sháoguān","en":"Shaoguan","lat":24.81,"lon":113.6,"note":"A mountain city in the north with red cliffs and a Buddhist temple.","stops":[["A","丹霞山","Dānxiáshān","Danxia Mountain","Red sandstone cliffs and peaks that gave the landform Danxia its name. It is a UNESCO World Heritage Site with fiery colors at sunset.","A UNESCO World Heritage Site.",25.03,113.74,1],["A","南华禅寺","Nánhuá Chánsì","Nanhua Temple","A famous Chan Buddhist temple about 1,500 years old, associated with the Sixth Patriarch Huineng, a key figure in Chinese Buddhism.","",24.66,113.62],["D","韶关红茶","Sháoguān hóngchá","Shaoguan black tea","Black tea grown in the hills of northern Guangdong, with a smooth, sweet taste that is the result of a slow drying process."]]},{"id":"meizhou","zh":"梅州","py":"Méizhōu","en":"Meizhou","lat":24.29,"lon":116.12,"note":"The heart of Hakka culture, with round earth buildings and mountains.","stops":[["D","客家酿豆腐","Kèjiā niàng dòufǔ","Hakka stuffed tofu","Squares of tofu stuffed with minced pork and fish, pan-fried and gently simmered, a Hakka comfort food and festive dish."],["D","盐焗鸡","Yánjújī","Salt-baked chicken (Meizhou)","Chicken baked in hot salt, a Hakka classic with a rich, fragrant, tender result, eaten warm or cold."]]},{"id":"yangjiang","zh":"阳江","py":"Yángjiāng","en":"Yangjiang","lat":21.86,"lon":111.98,"note":"A coastal city of knives, kites and seafood.","stops":[["A","南海一号","Nánhǎi Yīhào","Nanhai No. 1 shipwreck","A merchant ship of the Song dynasty that sank near the coast, and was lifted whole from the sea, still full of porcelain. It is on show in a museum.","",21.58,111.83],["D","阳江豆豉","Yángjiāng dòuchǐ","Yangjiang fermented black beans","Fermented black soybeans from Yangjiang, salty and deep in flavor, used to season steamed fish, pork and vegetables."],["D","海鲜","Hǎixiān","Island seafood","Fresh fish, shrimp and shellfish are on offer at Hailing Island, simply steamed or grilled by the sea."]]},{"id":"zhanjiang","zh":"湛江","py":"Zhànjiāng","en":"Zhanjiang","lat":21.27,"lon":110.36,"note":"A southern port at the tip of the Leizhou Peninsula.","stops":[["D","生蚝","Shēngháo","Fresh oysters","Fat oysters from the Zhanjiang coast are grilled with garlic and chili or steamed, and are served fresh."]]}],"air":{"zh":"广州白云国际机场","py":"Guǎngzhōubáiyún Guójìjīchǎng","en":"Guangzhou Baiyun International Airport","code":"CAN","lat":23.39,"lon":113.3,"note":"One of the busiest airports in China. Welcome to Guangdong."}},{"id":"guangxi","zh":"广西","py":"Guǎngxī","en":"Guangxi","cities":[{"id":"nanning","zh":"南宁","py":"Nánníng","en":"Nanning","lat":22.82,"lon":108.37,"note":"The green capital of the Zhuang Autonomous Region.","stops":[["A","青秀山","Qīngxiùshān","Qingxiu Mountain","A large forested hill park above the Yong River in Nanning, with a pagoda, tropical plants and gardens. It is a green escape from the busy city.","",22.78,108.39],["A","广西民族博物馆","Guǎngxī Mínzú Bówùguǎn","Guangxi Ethnic Museum","A museum that explores the cultures of Guangxi's many peoples, including the Zhuang, with costumes, bronze drums, and festivals.","",22.78,108.3],["A","南湖公园","Nánhú Gōngyuán","South Lake Park","A lake park with bridges, islands and gardens in the middle of Nanning, a favorite place for walks and for people to gather in the evening.","",22.8,108.33],["A","邕江","Yōngjiāng","Yong River","The Yong River winds through Nanning and gives the city its short name, Yong. Riverside parks and bridges light up at night.","",22.8,108.36],["A","德天跨国瀑布","Détiān Kuàguó Pùbù","Detian Waterfall","A wide, many-layered waterfall on the border with Vietnam, among the largest cross-border waterfalls in Asia. Part of it falls in each country.","",22.86,106.72],["D","老友粉","Lǎoyǒu fěn","Laoyou noodles","Hot rice noodles stir-fried with sour bamboo shoots, garlic, chili, pork and fermented black beans, a Nanning favorite. Its name means \"old friend noodles\"."],["D","螺蛳粉","Luósī fěn","Luosifen","Rice noodles in a spicy broth of river snails, pickled bamboo, peanuts and chili. Its smell is very strong, but fans love it. It started in Liuzhou and is now sold across China.","",null,null,1],["D","柠檬鸭","Níngméng yā","Lemon duck","A sweet, sour and savory duck stewed with pickled lemons and ginger, and a typical dish of Nanning's tables."],["D","生榨米粉","Shēngzhà mǐfěn","Fresh-pressed noodles","Rice noodles that are pressed fresh from a machine straight into a bowl of broth, soft and slippery."],["D","芒果","Mángguǒ","Mango","Guangxi's sunny valleys grow plenty of mangoes, and in summer markets in Nanning sell them by the basketful."],["C","壮锦","Zhuàngjǐn","Zhuang brocade","A colorful brocade woven by the Zhuang people, with geometric and flower patterns, used for bags, blankets and clothes."],["C","铜鼓","Tónggǔ","Bronze drum","Bronze drums have been made by southern peoples for over 2,000 years and are used at festivals and as symbols of power."]]},{"id":"guilin","zh":"桂林","py":"Guìlín","en":"Guilin","lat":25.27,"lon":110.29,"note":"The home of the most famous karst landscape in China.","stops":[["A","漓江","Líjiāng","Li River","A river that winds between green karst peaks, so beautiful that its view appears on the 20-yuan banknote. A boat cruise from Guilin to Yangshuo is a classic trip.","",25.07,110.33,1],["A","象鼻山","Xiàngbíshān","Elephant Trunk Hill","A hill by the Li River in Guilin shaped like an elephant dipping its trunk into the water, and the city's best-known landmark.","",25.27,110.3,1],["A","芦笛岩","Lúdíyán","Reed Flute Cave","A big cave near Guilin with colored lights shining on stalactites and stalagmites, which form strange shapes.","",25.31,110.26],["A","独秀峰","Dúxiùfēng","Solitary Beauty Peak","A lone peak rising within the old city of the Ming princes. A staircase leads to the top for a view of the city.","",25.29,110.29],["A","龙脊梯田","Lóngjí Tītián","Longji Rice Terraces","Rice terraces that climb the mountainside in curves like a dragon's spine. The Zhuang and Yao villages here have farmed them for centuries.","",25.75,110.1,1],["A","遇龙河","Yù Lónghé","Yulong River","A quiet, clear river with old bridges and bamboo rafts, among fields and karst hills, calmer than the Li River.","",24.76,110.45],["A","银子岩","Yínzi Yán","Silver Cave","A cave of glittering white rock formations that sparkle like silver under the lights.","",24.65,110.5],["D","桂林米粉","Guìlín mǐfěn","Guilin rice noodles","Round rice noodles served with braised meat, peanuts and a rich spiced broth, eaten for breakfast in Guilin."],["D","啤酒鱼","Píjiǔ yú","Beer fish","A famous Yangshuo dish of river fish cooked in beer with tomatoes and chili in a pot."],["D","荔浦芋头","Lìpǔ yùtou","Lipu taro","Lipu taro is big and starchy, with a purple pattern, and is used for the famous dish of taro cooked with pork."],["D","恭城油茶","Gōngchéng yóuchá","Gongcheng oil tea","A savory tea of fried tea leaves, ginger and garlic, ground and boiled with water, and served with peanuts and crispy snacks."],["D","桂花糕","Guìhuā gāo","Osmanthus cake","A soft sweet cake scented with the flowers of the osmanthus. Guilin means \"Forest of Osmanthus\" and its trees bloom in autumn."],["C","瑶族长发","Yáozú chángfà","Yao long hair","The Red Yao women of Longji grow their hair to remarkable lengths, wash it in rice water and wind it into headdresses."]]},{"id":"yangshuo","zh":"阳朔","py":"Yángshuò","en":"Yangshuo","lat":24.78,"lon":110.49,"note":"A river town surrounded by karst peaks.","stops":[["A","西街","Xījiē","West Street","Yangshuo's lively West Street is a mix of old lanes, cafés, shops and travelers from all over the world.","",24.78,110.49],["A","月亮山","Yuèliàngshān","Moon Hill","A hill with a huge round hole in its top, like a full moon seen from a distance. You can climb up to the arch.","",24.74,110.46],["A","兴坪古镇","Xīngpíng Gǔzhèn","Xingping Ancient Town","An old riverside town with a famous view of rocky peaks and fishermen on bamboo rafts, which appears on the 20-yuan note.","",24.92,110.52],["A","漓江竹筏","Líjiāng Zhúfá","Li River bamboo rafts","Bamboo rafts carry travelers on slow trips down the river past the peaks, steered with a long pole.","",24.92,110.52],["D","阳朔啤酒鱼","Yángshuò píjiǔ yú","Yangshuo beer fish","Yangshuo's own style of beer fish is cooked at the table with local beer and fresh river fish."],["D","田螺酿","Tiánluó niàng","Stuffed river snails","River snails stuffed with minced pork and herbs and then simmered, a Yangshuo treat that is eaten with a toothpick."],["C","刘三姐","Liúsānjiě","Liu Sanjie","A legendary Zhuang singer who defeated rich rivals in song contests. Her story is told in songs, a film and an outdoor show on the Li River.","",null,null,1]]},{"id":"liuzhou","zh":"柳州","py":"Liǔzhōu","en":"Liuzhou","lat":24.33,"lon":109.43,"note":"An industrial city on the Liu River, home of snail noodles.","stops":[["D","柳州螺蛳粉","Liǔzhōu luósī fěn","Liuzhou snail noodles","The original home of the snail noodle soup. In Liuzhou, locals eat it on every street corner."]]},{"id":"beihai","zh":"北海","py":"Běihǎi","en":"Beihai","lat":21.48,"lon":109.12,"note":"A beach city on the Gulf of Tonkin.","stops":[["A","银滩","Yíntān","Silver Beach","A long beach of fine, pale sand on the coast at Beihai, with gentle water, good for walks and for swimming.","",21.42,109.14],["A","涠洲岛","Wéizhōudǎo","Weizhou Island","A volcanic island off Beihai with black rocks, coral, cliffs and sunsets, and a quiet place with fishing villages.","",21.03,109.1],["A","红树林","Hóngshùlín","Mangrove forest","A mangrove reserve on the coast, where tangled roots shelter crabs, fish and many birds in the shallow water.","",21.58,109.3],["D","海鲜","Hǎixiān","Beihai seafood","Beihai's restaurants serve fresh shrimp, crab and fish, cooked simply to bring out the taste of the sea."],["D","沙虫","Shāchóng","Sandworm","Sandworms are a prized seafood in Beihai, cooked in soup, fried or steamed. They are said to be sweet and tender."],["D","合浦珍珠","Hépǔ zhēnzhū","Hepu pearls","Hepu has been a pearl-producing area for over 2,000 years, and its pearls were once sent to the emperor."]]},{"id":"wuzhou","zh":"梧州","py":"Wúzhōu","en":"Wuzhou","lat":23.48,"lon":111.28,"note":"A river city at the border with Guangdong.","stops":[["D","龟苓膏","Guīlínggāo","Turtle jelly","A dark herbal jelly, slightly bitter and eaten with syrup, thought in southern China to cool the body."],["D","梧州纸包鸡","Wúzhōu zhǐbāo jī","Paper-wrapped chicken","Seasoned chicken wrapped in paper and fried in oil, so that the meat stays juicy and fragrant."]]},{"id":"baise","zh":"百色","py":"Bǎisè","en":"Baise","lat":23.9,"lon":106.62,"note":"A red-history city and mountain area.","stops":[["D","百色芒果","Bǎisè mángguǒ","Baise mango","A mango from the sunny valley of the Youjiang river, sweet and rich and a famed fruit."],["D","靖西鸭","Jìngxī yā","Jingxi duck","A local breed of duck from Jingxi, known for its tender meat, and often cooked with herbs."]]},{"id":"chongzuo","zh":"崇左","py":"Chóngzuǒ","en":"Chongzuo","lat":22.38,"lon":107.37,"note":"A border city with rock art.","stops":[["A","花山岩画","Huāshān Yánhuà","Zuojiang Huashan Rock Art","Red paintings of people with raised arms on a cliff above the Zuo River, made over 2,000 years ago by ancestors of the Zhuang. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",22.1,107.35,1],["A","友谊关","Yǒuyìguān","Friendship Pass","The main land crossing between China and Vietnam. This old pass has guarded the border for centuries.","",22.01,106.73],["D","崇左糖","Chóngzuǒ táng","Chongzuo sugar","Chongzuo is China's biggest sugar-cane area, and the fields stretch for miles around the town."]]},{"id":"qinzhou","zh":"钦州","py":"Qīnzhōu","en":"Qinzhou","lat":21.96,"lon":108.65,"note":"A port city and home of pottery.","stops":[["D","钦州猪脚粉","Qīnzhōu zhūjiǎo fěn","Qinzhou pork-foot noodles","Rice noodles in a broth with braised pig's feet, soft and rich, a hearty dish of Qinzhou."],["D","大蚝","Dàháo","Qinzhou oysters","Large, plump oysters from the bay at Qinzhou, grilled with garlic or steamed, are a local pride."]]},{"id":"yulin-gx","zh":"玉林","py":"Yùlín","en":"Yulin","lat":22.65,"lon":110.18,"note":"A city famed for medicinal herbs and cuisine.","stops":[["D","玉林牛巴","Yùlín niúbā","Yulin beef jerky","Cured and spiced beef, cut into strips and dried. It is chewy and flavorful and a favorite snack."],["D","玉林凉茶","Yùlín liángchá","Yulin herbal tea","A herbal drink made in Yulin, brewed from plants and sold in shops to cool the body in the heat."]]},{"id":"hechi","zh":"河池","py":"Héchí","en":"Hechi","lat":24.69,"lon":108.09,"note":"A mountain area of Zhuang and Yao cultures.","stops":[["D","巴马香猪","Bāmǎ xiāngzhū","Bama fragrant pig","A small breed of pig from Bama, known for its tender meat. It is often roasted."],["D","巴马火麻汤","Bāmǎ huǒmátāng","Bama hemp soup","A soup of hemp seeds, a staple in Bama, a place known for its long-lived residents."]]}],"air":{"zh":"南宁吴圩国际机场","py":"Nánníng Wúwéi Guójì Jīchǎng","en":"Nanning Wuxu International Airport","code":"NNG","lat":22.61,"lon":108.17,"note":"The main airport of Guangxi, southwest of Nanning. Welcome to Guangxi."}},{"id":"guizhou","zh":"贵州","py":"Guìzhōu","en":"Guizhou","cities":[{"id":"guiyang","zh":"贵阳","py":"Guìyáng","en":"Guiyang","lat":26.65,"lon":106.63,"note":"A cool mountain capital known for big data.","stops":[["A","甲秀楼","Jiǎxiùlóu","Jiaxiu Tower","A three-story tower on a small island in the Nanming River in Guiyang, built in the Ming dynasty. It is a symbol of the city.","",26.56,106.72],["A","黔灵山公园","Qián Língshān Gōngyuán","Qianling Mountain Park","A hill park in the middle of Guiyang, with forest paths, a lake, a Buddhist temple and a lot of cheeky wild macaques.","",26.6,106.7],["A","青岩古镇","Qīngyán Gǔzhèn","Qingyan Ancient Town","A Ming-era walled town with stone streets, old gates and temples, where Han, Miao and other peoples have lived.","",26.34,106.67],["A","阳明祠","Yángmíng Cí","Yangming Shrine","A shrine to Wang Yangming, the Ming philosopher who developed his famous ideas while living in exile in Guizhou.","",26.84,106.88],["D","酸汤鱼","Suān tāngyú","Sour soup fish","Fish cooked in a tangy red broth of fermented tomatoes and chili. It is a Miao classic and one of Guizhou's best-loved dishes.","",null,null,1],["D","丝娃娃","Sī wáwá","Si wawa","Thin pancakes wrapped around shredded vegetables, peanuts and sauces. They look like little dolls in white silk."],["D","肠旺面","Chángwàngmiàn","Changwang noodles","A Guiyang noodle dish with pork intestines, blood tofu and chili oil in a rich, spicy soup."],["D","豆腐果","Dòufǔ guǒ","Tofu fruit","Little cubes of tofu grilled until they puff up, then filled with chili dip, a favorite street snack in Guiyang."],["D","糯米饭","Nuòmǐfàn","Sticky rice","Sticky rice is a staple of Guizhou's festival tables, eaten with pickles, cured meat and spicy sauces."],["D","贵州辣椒","Guìzhōu làjiāo","Guizhou chili","Guizhou people love chili: fermented, dried, ground and cooked in sauces. It is the soul of the cuisine here."],["C","苗族银饰","Miáozú yínshì","Miao silver","Miao women wear heavy silver headdresses, necklaces and collars at festivals. Each piece is hammered by hand and tells a story."],["C","侗族大歌","Dòngzú dàgē","Dong grand song","The Dong people sing in many-voiced choirs without conductor or instruments, imitating birds, water and wind. It is UNESCO-listed."]]},{"id":"zunyi","zh":"遵义","py":"Zūnyì","en":"Zunyi","lat":27.73,"lon":106.93,"note":"The site of a key meeting during the Long March.","stops":[["A","遵义会议会址","Zūnyì Huìyì Huìzhǐ","Zunyi Conference Site","A building in Zunyi where, in January 1935, Communist leaders held a key meeting during the Long March, a turning point in the party's history.","",27.7,106.93],["A","茅台镇","Máotáizhèn","Maotai Town","A small town by the Chishui River, known for the Moutai distilleries. The air there smells of fermenting sorghum.","",27.86,106.38],["A","赤水丹霞","Chìshuǐ Dānxiá","Chishui Danxia","Red cliffs, waterfalls and bamboo forests in a green valley, part of the UNESCO Danxia landform listing.","A UNESCO World Heritage Site.",28.58,105.7],["A","四渡赤水","Sì Dùchìshuǐ","Four Crossings of the Chishui","A river associated with a famous 1935 maneuver, in which the Red Army crossed the river four times to escape its pursuers.","",28.58,105.7],["D","茅台酒","Máotáijiǔ","Moutai","China's best-known baijiu, made from sorghum and wheat in Maotai and aged for years, with a rich, savory aroma."],["D","遵义羊肉粉","Zūnyì yángròu fěn","Zunyi lamb noodles","Rice noodles in a lamb broth, topped with slices of lamb, herbs and chili, a typical breakfast in Zunyi."],["D","鸭溪窖酒","Yāxī jiàojiǔ","Yaxi liquor","A local baijiu from Yaxi, with a long history, aged in earth cellars."],["C","酒文化","Jiǔ wénhuà","Liquor culture","Baijiu is at the center of toasts and celebrations in Guizhou, and drinking customs are a big part of hospitality."]]},{"id":"anshun","zh":"安顺","py":"Ānshùn","en":"Anshun","lat":26.25,"lon":105.95,"note":"The home of Huangguoshu Waterfall.","stops":[["A","黄果树瀑布","Huángguǒshù Pùbù","Huangguoshu Waterfall","The most famous waterfall in China, about 70 meters high and 100 meters wide. A path leads behind the falls, where you can feel the spray.","",25.99,105.67,1],["A","龙宫","Lónggōng","Dragon Palace","A large cave system with an underground river, lakes and waterfalls, which can be explored by boat.","",26.14,105.96],["D","安顺裹卷","Ānshùn guǒjuǎn","Anshun guojuan","A thin rice-flour wrap filled with vegetables, meat and sauces, a snack from Anshun."],["D","荞凉粉","Qiáo liángfěn","Buckwheat jelly","A cold jelly made from buckwheat, served in a spicy, sour sauce, refreshing in summer."],["C","地戏","Dìxì","Ground opera","Ground opera is a ritual drama where performers in painted wooden masks act out ancient battles, originally brought by soldiers in the Ming dynasty."]]},{"id":"qiandongnan","zh":"黔东南","py":"Qiándōngnán","en":"Southeast Guizhou","lat":26.58,"lon":107.98,"note":"A prefecture of Miao and Dong villages.","stops":[["A","西江千户苗寨","Xījiāng Qiānhù Miáozhài","Xijiang Thousand-Household Miao Village","The largest Miao village in China, with thousands of wooden stilt houses on a hillside. At night the whole slope glows with lights.","",26.5,108.19,1],["A","肇兴侗寨","Zhàoxīng Dòngzhài","Zhaoxing Dong Village","A Dong village with five drum towers, wind-and-rain bridges and wooden houses, in the valley of Southeast Guizhou.","",25.92,109.17],["A","镇远古镇","Zhènyuǎn Gǔzhèn","Zhenyuan Ancient Town","A river town with old streets, stone gates and temples along the Wu River, which has been a transport hub for over 2,000 years.","",27.05,108.43],["D","腌鱼","Yānyú","Dong pickled fish","Fish preserved with salt and sticky rice in jars for months. It is a Dong specialty with a strong, sour flavor."],["C","芦笙","Lúshēng","Lusheng","The lusheng is a reed pipe of several bamboo tubes, played and danced to at Miao and Dong festivals."]]},{"id":"bijie","zh":"毕节","py":"Bìjié","en":"Bijie","lat":27.3,"lon":105.29,"note":"A highland city of azaleas.","stops":[["A","织金洞","Zhījīn Dòng","Zhijin Cave","One of China's largest caves, with huge halls full of stalagmites, columns and crystal-like formations.","",26.67,105.78],["D","毕节汤圆","Bìjié tāngyuán","Bijie tangyuan","Sticky rice balls, filled with sweet or savory fillings and served in a hot broth. A winter favorite."],["D","威宁荞麦","Wēiníng qiáomài","Weining buckwheat","Weining is a high plateau where buckwheat is grown, and its flour is made into noodles, pancakes and cakes."]]},{"id":"tongren","zh":"铜仁","py":"Tóngrén","en":"Tongren","lat":27.72,"lon":109.19,"note":"A city with the Fanjing mountain.","stops":[["A","梵净山","Fànjìngshān","Fanjing Mountain","A sacred Buddhist mountain with a rock tower that stands on its summit. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",27.9,108.69],["D","铜仁米粉","Tóngrén mǐfěn","Tongren rice noodles","Rice noodles with meat and a spicy sauce, a breakfast staple in Tongren."],["D","梵净山茶","Fànjìngshān chá","Fanjing Mountain tea","A tea grown in the cloud-covered Fanjing Mountain, known for a fresh and mellow taste."]]},{"id":"qianxinan","zh":"黔西南","py":"Qiánxīnán","en":"Southwest Guizhou","lat":25.09,"lon":104.9,"note":"A prefecture of karst peaks.","stops":[["A","万峰林","Wàn Fēnglín","Wanfenglin","A grand landscape of thousands of cone-shaped karst peaks that rise from green fields.","",25.0,104.96],["D","兴义鸡肉粉","Xīngyì jīròu fěn","Xingyi chicken noodles","Rice noodles in a rich chicken broth, topped with shredded chicken, a Xingyi specialty."],["D","布依族五色糯米饭","Bùyīzú wǔsè nuòmǐfàn","Buyi five-color rice","Sticky rice dyed with plant juices in five colors, made by the Buyi people for festivals."]]},{"id":"qiannan","zh":"黔南","py":"Qiánnán","en":"South Guizhou","lat":26.25,"lon":107.52,"note":"A prefecture with a giant telescope.","stops":[["A","中国天眼","Zhōngguó Tiānyǎn","FAST Telescope","FAST, the world's largest single-dish radio telescope, sits in a natural karst bowl. It listens to faint signals from deep space.","",25.65,106.86,1],["A","荔波小七孔","Lìbō Xiǎo Qīkǒng","Libo Xiaoqikong","A scenic area of emerald pools, small waterfalls and an old seven-arch bridge, among forests of Libo.","A UNESCO World Heritage Site.",25.28,107.8],["D","都匀毛尖","Dūyún máojiān","Duyun Maojian tea","A famed green tea from Duyun, with slender leaves covered with fine hair and a fresh taste."],["D","荔波鱼","Lìbō yú","Libo fish","Fresh river fish from Libo, cooked in soup or in a tangy sauce."]]},{"id":"liupanshui","zh":"六盘水","py":"Liùpánshuǐ","en":"Liupanshui","lat":26.59,"lon":104.83,"note":"A cool city in western Guizhou, popular in summer.","stops":[["D","六盘水猕猴桃","Liùpánshuǐ míhóutáo","Liupanshui kiwi","Kiwi fruit from the cool highlands of Liupanshui are sweet and sour and are grown on a large scale."]]}],"air":{"zh":"贵阳龙洞堡国际机场","py":"Guìyáng Lóngdòng Bǎo Guójì Jīchǎng","en":"Guiyang Longdongbao International Airport","code":"KWE","lat":26.54,"lon":106.8,"note":"The main airport of Guizhou, east of the city. Welcome to Guizhou."}},{"id":"hainan","zh":"海南","py":"Hǎinán","en":"Hainan","cities":[{"id":"haikou","zh":"海口","py":"Hǎikǒu","en":"Haikou","lat":20.04,"lon":110.2,"note":"The capital of Hainan, a tropical coastal city.","stops":[["A","五公祠","Wǔgōngcí","Five Lords Temple","A temple complex in Haikou for five officials of the Tang and Song dynasties who were exiled to Hainan, with halls and old trees.","",20.01,110.34],["A","海口火山群","Hǎikǒu Huǒshān Qún","Haikou Volcanic Cluster","A park of extinct volcano craters in Haikou, where visitors can walk to the edge of an old crater and through lava tunnels.","",19.9,110.2],["A","假日海滩","Jiàrì Hǎitān","Holiday Beach","A long city beach in Haikou with palm trees, where locals come to swim and fly kites and watch the sun set.","",20.04,110.32],["A","海南省博物馆","Hǎinánshěng Bówùguǎn","Hainan Provincial Museum","A museum of Hainan's history, from the Li and Miao peoples to the island's role in the maritime Silk Road.","",20.02,110.35],["D","海南鸡饭","Hǎinán jīfàn","Hainanese chicken rice","Poached chicken sliced and served with rice cooked in chicken stock, with ginger and chili sauce. It started in Hainan and became a classic across Southeast Asia.","",null,null,1],["D","文昌鸡","Wénchāngjī","Wenchang chicken","A prized chicken breed from Wenchang, known for its thin skin and sweet, tender meat, and often served poached."],["D","加积鸭","Jiājī yā","Jiaji duck","A plump duck from Jiaji in Qionghai, with soft meat and rich fat, usually served with a dipping sauce."],["D","抱罗粉","Bàoluófěn","Baoluo noodles","Rice noodles in a rich broth, topped with beef or pork and peanuts, an island breakfast favorite."],["D","椰子饭","Yēzi fàn","Coconut rice","Sticky rice steamed inside a coconut, so the grains take up the coconut's sweet scent."],["D","清补凉","Qīngbǔliáng","Qingbuliang","A cool dessert soup of beans, coconut milk, fruit and jelly on ice, perfect for a hot day on the island."],["D","老爸茶","Lǎobà chá","Laoba tea","A Hainan teahouse custom, where people spend hours over tea, snacks and chats, and where deals and gossip are shared."],["C","琼剧","Qióngjù","Qiong opera","The local opera of Hainan, sung in the Hainan dialect, whose stories and melodies are loved by Hainanese all over the world."]]},{"id":"sanya","zh":"三亚","py":"Sānyà","en":"Sanya","lat":18.25,"lon":109.51,"note":"A tropical resort city at the southern tip of the island.","stops":[["A","亚龙湾","Yàlóngwān","Yalong Bay","A wide curve of white sand and clear blue water, backed by green hills and resorts, often called the most beautiful beach in Sanya.","",18.22,109.64,1],["A","天涯海角","Tiānyá Hǎijiǎo","End of the Earth","A beach of huge boulders carved with the words for End of the Earth. In the past, exiles were sent here, at the far south of the empire.","",18.3,109.35,1],["A","南山寺","Nánshānsì","Nanshan Temple","A temple by the sea in Sanya with a 108-meter statue of Guanyin standing on the water, a pilgrimage site.","",18.3,109.17],["A","蜈支洲岛","Wúzhīzhōu Dǎo","Wuzhizhou Island","A small island off Sanya with clear water, coral reefs and white sand, popular for diving and snorkeling.","",18.31,109.76],["A","大东海","Dàdōnghǎi","Dadonghai","A crescent-shaped beach right beside Sanya's city center, with calm water and palm trees.","",18.22,109.52],["D","海鲜","Hǎixiān","Sanya seafood","Sanya's markets let you pick live fish, crab and shellfish, and then have them cooked at a nearby restaurant."],["D","椰子鸡","Yēzi jī","Coconut chicken hot pot","Chicken simmered in fresh coconut water at the table, with a sweet and clean broth. It is a popular Hainan hotpot."],["D","芒果","Mángguǒ","Hainan mango","Sweet, golden mangoes ripen in Hainan's warm climate in spring and are sold at stalls across Sanya."],["D","和乐蟹","Hélè xiè","Hele crab","Hele crab from Wanning is one of Hainan's four famous dishes, known for rich, creamy meat and golden roe."],["C","黎锦","Líjǐn","Li brocade","A cloth woven by Li women, with bold patterns of people, animals and nature. With a history of thousands of years, it is a UNESCO-listed craft.","",null,null,1]]},{"id":"wanning","zh":"万宁","py":"Wànníng","en":"Wanning","lat":18.8,"lon":110.39,"note":"A coastal city for surfing.","stops":[["A","日月湾","Rìyuè Wān","Riyue Bay","A bay in Wanning with steady waves, a favorite for surfers, with a laid-back vibe.","",18.67,110.5],["A","东山岭","Dōngshānlǐng","Dongshan Ridge","A hill near Wanning with temples, rocks carved with poems and a good view of the coast.","",18.8,110.4],["D","兴隆咖啡","Xīnglóng kāfēi","Xinglong coffee","A coffee grown in Xinglong, brought by overseas Chinese returning from Southeast Asia. It is roasted dark and often sweetened."]]},{"id":"qionghai","zh":"琼海","py":"Qiónghǎi","en":"Qionghai","lat":19.25,"lon":110.47,"note":"A quiet city on the river.","stops":[["A","博鳌","Bó’áo","Boao","A town at the mouth of the Wanquan River where the Boao Forum for Asia meets, with beaches and quiet lagoons.","",19.15,110.57],["A","万泉河","Wànquánhé","Wanquan River","A clear river that flows through green hills and rubber forests and reaches the sea at Boao.","",19.2,110.47],["D","嘉积鸭","Jiājī yā","Jiaji duck","A well-known Hainan duck with soft meat and rich flavor, named for the town of Jiaji and served with a dipping sauce."]]},{"id":"wenchang","zh":"文昌","py":"Wénchāng","en":"Wenchang","lat":19.54,"lon":110.8,"note":"The home of the space launch center and Wenchang chicken.","stops":[["A","文昌航天发射场","Wénchāng Hángtiān Fāshèchǎng","Wenchang Space Launch Site","A coastal launch site, close to the equator, where China launches its large rockets and space station modules.","",19.61,110.95],["A","宋氏祖居","Sòngshì Zǔjū","Soong Family Home","The old family home of the Soong family in Wenchang, whose descendants include three famous sisters of 20th-century China.","",19.54,110.8],["D","椰子","Yēzi","Coconut","Wenchang is famous for its coconut palms, and you can drink the sweet water directly from the fruit."]]},{"id":"danzhou","zh":"儋州","py":"Dānzhōu","en":"Danzhou","lat":19.52,"lon":109.58,"note":"A western city where the poet Su Dongpo was exiled.","stops":[["A","东坡书院","Dōngpō Shūyuàn","Dongpo Academy","A school begun by the poet Su Dongpo while he was exiled to Hainan, where he taught local students.","",19.57,109.48],["D","儋州米烂","Dānzhōu mǐlàn","Danzhou mi lan","A thick rice porridge cooked until the grains melt, often with seafood or meat, a Danzhou comfort food."],["D","儋州火山荔枝","Dānzhōu huǒshān lìzhī","Danzhou lychee","Lychees grown on the volcanic soil of Danzhou, juicy and sweet, are picked in early summer."]]},{"id":"wuzhishan","zh":"五指山","py":"Wǔzhǐshān","en":"Wuzhishan","lat":18.78,"lon":109.52,"note":"The mountain city at the island's heart.","stops":[["A","五指山","Wǔzhǐshān","Five Finger Mountain","Hainan's highest mountain, with five peaks like fingers, covered with rainforest and home to the Li people.","",18.9,109.67],["D","五指山红茶","Wǔzhǐshān hóngchá","Wuzhishan black tea","A black tea grown in the misty forests of Wuzhishan, with a clean, sweet taste."],["D","山兰酒","Shānlánjiǔ","Shanlan wine","A rice wine made by the Li people from mountain rice, often shared at festivals and family gatherings."],["C","三月三","Sānyuè sān","Li March Third","The Li people's biggest festival, on the third day of the third lunar month, with singing, dancing and courtship."]]},{"id":"ledong","zh":"乐东","py":"Lèdōng","en":"Ledong","lat":18.75,"lon":109.17,"note":"A western county of Li culture.","stops":[["D","乐东芒果","Lèdōng mángguǒ","Ledong mango","Ledong's mangoes are sweet and fragrant, among the first to reach markets each year."]]},{"id":"lingshui","zh":"陵水","py":"Língshuǐ","en":"Lingshui","lat":18.5,"lon":110.03,"note":"An eastern coastal county.","stops":[["A","南湾猴岛","Nánwān Hóudǎo","Monkey Island","A peninsula in Lingshui where hundreds of macaques live, which you can reach by cable car, to see them up close.","",18.76,110.06],["D","陵水酸粉","Língshuǐ suānfěn","Lingshui sour noodles","Rice noodles in a sour, spicy broth, with peanuts, herbs and fried pork skin, a Lingshui breakfast."],["D","陵水海鲜","Língshuǐ hǎixiān","Lingshui seafood","Lingshui's coastal restaurants serve fresh fish, crab and shrimp, often steamed or cooked with local herbs."]]}],"air":{"zh":"海口美兰国际机场","py":"Hǎikǒu Měilán Guójì Jīchǎng","en":"Haikou Meilan International Airport","code":"HAK","lat":19.93,"lon":110.46,"note":"The main airport of Hainan, on the north coast. Welcome to Hainan."}},{"id":"hebei","zh":"河北","py":"Héběi","en":"Hebei","cities":[{"id":"beijing","zh":"北京","py":"Běijīng","en":"Beijing","lat":39.9,"lon":116.4,"note":"The capital of China, with palaces, hutongs and the Great Wall nearby.","stops":[["A","故宫","Gùgōng","The Forbidden City","The palace of the Ming and Qing emperors for almost 500 years, with nearly a thousand buildings behind red walls and a moat. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",39.92,116.4,1],["A","天安门广场","Tiān’ānmén Guǎngchǎng","Tiananmen Square","One of the largest public squares in the world, with the Gate of Heavenly Peace on the north and the Great Hall of the People on the west.","",39.9,116.39],["A","天坛","Tiāntán","Temple of Heaven","Where Ming and Qing emperors prayed for good harvests. Its round, blue-tiled Hall of Prayer stands on a three-tiered white marble terrace.","",39.88,116.41],["A","颐和园","Yíhéyuán","Summer Palace","A lake and a hill garden that served as the Qing court's summer retreat, with a long painted corridor, a marble boat and temples.","",40.0,116.27],["A","北海公园","Běihǎi Gōngyuán","Beihai Park","One of the oldest imperial gardens in China, built around a lake with a white pagoda on an island. You can rent a boat in summer.","",39.93,116.38],["A","景山公园","Jǐngshān Gōngyuán","Jingshan Park","An artificial hill just north of the Forbidden City, and the best place to see the palace roofs spread out in a golden sea.","",39.93,116.4],["A","八达岭长城","Bādálǐng Chángchéng","Badaling Great Wall","The best-known part of the Great Wall, with steep Ming-era stairs and watchtowers that climb the ridge. It is about an hour from Beijing.","",40.36,116.02,1],["A","慕田峪长城","Mùtiányù Chángchéng","Mutianyu Great Wall","A restored stretch of the Great Wall in green hills, quieter than Badaling, with cable cars and even a toboggan ride down.","",40.43,116.56],["A","鸟巢","Niǎocháo","Bird's Nest","The National Stadium, built for the 2008 Olympics. Its steel lattice looks like a bird's nest woven from twigs.","",39.99,116.4],["A","水立方","Shuǐlìfāng","Water Cube","The swimming center of the 2008 Olympics, wrapped in a skin of blue bubbles, which is now also a water park.","",39.99,116.39],["A","雍和宫","Yōnghégōng","Lama Temple","A big Tibetan Buddhist temple that was once a prince's home. Its tallest hall holds a huge Buddha carved from a single tree trunk.","",39.95,116.42],["A","国家博物馆","Guójiā Bówùguǎn","National Museum of China","A vast museum on the east side of Tiananmen Square, telling the story of China's history and displaying thousands of treasures.","",39.9,116.4],["A","南锣鼓巷","Nánluógǔ Xiàng","Nanluoguxiang","An old hutong lane with cafés, souvenir shops and street snacks, always busy with visitors and locals.","",39.94,116.4],["A","什刹海","Shénshāhǎi","Shichahai","A group of lakes with old courtyard houses, willow trees, bars and boats. People skate on it in winter.","",39.94,116.38],["A","圆明园","Yuánmíngyuán","Old Summer Palace","The ruins of a vast imperial garden that was burned by Anglo-French troops in 1860. Broken marble pillars remain among the lakes.","",40.01,116.3],["A","明十三陵","Míngshísān Líng","Ming Tombs","The burial ground of thirteen Ming emperors in a valley north of Beijing, reached along a Sacred Way lined with stone animals.","",40.25,116.22],["A","798艺术区","798 Yìshù Qū","798 Art Zone","A former factory complex, now filled with galleries, studios and cafés, where old industrial buildings meet contemporary art.","",39.99,116.5],["A","天文台","Tiānwéntái","Ancient Observatory","A Ming-era observatory on the old city wall, with large bronze instruments that were used to track the stars and planets.","",39.91,116.43],["D","北京烤鸭","Běijīng kǎoyā","Peking duck","Roast duck with thin, crisp skin, carved at the table and eaten rolled in a pancake with scallions, cucumber and sweet bean sauce. It is Beijing's most famous dish.","",null,null,1],["D","炸酱面","Zhájiàngmiàn","Zhajiangmian","Hand-pulled noodles topped with a thick fried soybean paste and fresh sliced vegetables. This is the everyday noodle of old Beijing."],["D","豆汁","Dòuzhī","Douzhi","A sour, fermented mung bean drink with a strong smell, eaten with pickles. Many visitors find it tough, but it is a true Beijing taste."],["D","驴打滚","Lǘdǎgǔn","Donkey rolling","A sticky rice roll filled with red bean paste and rolled in soybean flour, named for the cloud of flour that flies up like a donkey rolling in the dust."],["D","糖葫芦","Tánghúlú","Tanghulu","Hawthorn berries on a stick, coated in a shiny layer of hard sugar, a winter street snack. The sour fruit meets the sweet candy."],["D","涮羊肉","Shuànyángròu","Instant-boiled mutton","Thin slices of lamb are swished in a pot of simmering water, then dipped in sesame sauce. It is a favorite winter meal in Beijing."],["D","卤煮","Lǔzhǔ","Luzhu","An old Beijing dish of pork offal and fried tofu simmered in a rich broth with flatbread. A taste for the brave."],["D","艾窝窝","Àiwōwō","Aiwowo","A soft, sticky rice ball filled with sweet nuts and sugar, a traditional snack of Beijing that was once eaten at festivals."],["C","京剧","Jīngjù","Peking opera","Peking opera combines singing, speech, acrobatics and martial arts. The actors wear painted faces and rich costumes that show their role in the story.","",null,null,1],["C","相声","Xiàngshēng","Xiangsheng","A comedy talk show for two performers who trade jokes and puns, quick and clever. It is a classic of Beijing and Tianjin."],["C","景泰蓝","Jǐngtàilán","Cloisonné","Cloisonné is a craft in which thin copper wires are filled with colored enamel and fired, to make vases and bowls with a deep blue glow."],["C","北京四合院","Běijīng sìhéyuàn","Siheyuan courtyard house","A traditional home with four buildings arranged around a central courtyard, set along a hutong, the heart of old Beijing family life."]],"muni":"Beijing"},{"id":"tianjin","zh":"天津","py":"Tiānjīn","en":"Tianjin","lat":39.12,"lon":117.19,"note":"A port city by the sea, with old foreign quarters and comic talk.","stops":[["A","天津之眼","Tiānjīn Zhīyǎn","Tianjin Eye","A giant Ferris wheel that rises from a bridge over the Hai River, with a view of the old city and the river from the top.","",39.15,117.18],["A","古文化街","Gǔwénhuà Jiē","Ancient Culture Street","A pedestrian street with old-style shopfronts, selling crafts, calligraphy, clay figures and Tianjin snacks.","",39.15,117.18],["A","意大利风情区","Yìdàlì Fēngqíngqū","Italian Style Town","A neighborhood of Italian-style houses and piazzas from the days when Italy had a concession in Tianjin, now full of cafés.","",39.14,117.2],["A","瓷房子","Cí Fángzi","Porcelain House","A mansion whose outside walls are covered with more than 400 million pieces of old porcelain, glass and jade, and even ancient vases.","",39.12,117.2],["D","狗不理包子","Gǒubùlǐ bāozi","Goubuli buns","Tianjin's most famous steamed buns have a fine pleated top and a juicy pork filling. The name means Dog Doesn't Care, from a nickname of the founder.","",null,null,1],["D","煎饼馃子","Jiānbǐng guǒzi","Jianbing guozi","A thin crepe fried with egg, brushed with sauce and rolled around a crisp fried cracker. It is Tianjin's favorite street breakfast."],["D","麻花","Máhuā","Mahua twists","Twisted fried dough sticks, crisp and sweet, and a famous Tianjin snack that is sold in boxes as a gift."],["D","耳朵眼炸糕","Ěrduǒyǎn zhágāo","Erduoyan fried cake","A sticky rice cake fried until golden and filled with sweet bean paste. It is named after the alley where it was first made."],["D","锅巴菜","Guōbā cài","Guoba cai","A Tianjin breakfast soup of strips of mung bean pancake in a savory sauce with sesame paste and fermented bean curd."],["C","泥人张","Nírénzhāng","Clay Figure Zhang","A family of clay-figure artists whose delicate, lifelike hand-modeled statues have been made in Tianjin for about 180 years."],["C","杨柳青年画","Yángliǔqīng niánhuà","Yangliuqing New Year prints","Brightly colored New Year prints from Yangliuqing, with cheerful scenes of children, fish and good-luck symbols, printed by hand."]],"muni":"Tianjin"},{"id":"shijiazhuang","zh":"石家庄","py":"Shíjiāzhuāng","en":"Shijiazhuang","lat":38.04,"lon":114.51,"note":"The capital of Hebei, a rail hub.","stops":[["A","赵州桥","Zhàozhōuqiáo","Zhaozhou Bridge","The oldest large stone arch bridge in China, built around 600 CE. Its low arch has survived floods and earthquakes for 1,400 years.","",37.74,114.78],["A","正定古城","Zhèngdìng Gǔchéng","Zhengding Ancient City","An old walled town with temples, pagodas and a Buddha statue, once an important northern city.","",38.15,114.57],["A","隆兴寺","Lóngxīngsì","Longxing Temple","A Buddhist temple in Zhengding with a 22-meter bronze statue of the Thousand-Armed Guanyin, which was cast in the Song dynasty.","",38.15,114.57],["D","正定马保定驴肉火烧","Zhèngdìng mǎ bǎodìng lǘròu huǒshāo","Zhengding donkey sandwich","A flatbread stuffed with braised donkey meat, a famed specialty of Zhengding. The sandwich is crisp outside and rich inside."],["D","缸炉烧饼","Gānglú shāobǐng","Ganglu flatbread","A sesame flatbread baked against the wall of a jar-shaped oven, making it crisp and fragrant."]]},{"id":"chengde","zh":"承德","py":"Chéngdé","en":"Chengde","lat":40.97,"lon":117.94,"note":"The Qing emperors' summer capital.","stops":[["A","避暑山庄","Bìshǔ Shānzhuāng","Mountain Resort","A huge imperial garden and palace in the hills of Chengde, where Qing emperors spent the summer and held court. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",40.99,117.94,1],["A","普陀宗乘之庙","Pǔtuó Zōngchéng Zhīmiào","Putuo Zongsheng Temple","A big Tibetan-style temple, modeled on the Potala Palace in Lhasa, built by Emperor Qianlong in the 18th century.","",41.02,117.94],["A","磬锤峰","Qìng Chuífēng","Chime Hammer Rock","A tall rock that looks like a hammer, standing on a hillside above Chengde, a local symbol.","",40.99,117.99],["A","塞罕坝","Sāihǎnbà","Saihanba","A forest and grassland that planters turned from a barren land into a green refuge across decades, a model of ecological work.","",42.4,117.4],["D","承德杏仁露","Chéngdé xìngrénlù","Chengde almond drink","A sweet, milky drink made from almonds, and a popular local drink that is served cold."],["D","驴肉火烧","Lǘròu huǒshāo","Donkey fire-baked bun","A crisp baked bun filled with braised donkey meat, which is a well-loved comfort food in Hebei."]]},{"id":"qinhuangdao","zh":"秦皇岛","py":"Qínhuángdǎo","en":"Qinhuangdao","lat":39.94,"lon":119.6,"note":"A seaside city where the Great Wall reaches the sea.","stops":[["A","山海关","Shānhǎiguān","Shanhaiguan","A strong fortress at a pass where the Great Wall meets the sea, nicknamed the First Pass Under Heaven.","",40.01,119.76],["A","老龙头","Lǎolóngtóu","Old Dragon's Head","The place where the Great Wall meets the Bohai Sea, and its end looks like a dragon's head dipping into the water.","",39.96,119.8],["A","北戴河","Běidàihé","Beidaihe","A seaside resort on the Bohai coast with beaches, villas and sea breezes, a summer escape for many decades.","",39.83,119.48],["D","山海关八大碗","Shānhǎiguān bā dàwǎn","Shanhaiguan eight bowls","A traditional banquet of eight bowls of local dishes, served at festivals and weddings in the Shanhaiguan area."],["D","秦皇岛海鲜","Qínhuángdǎo hǎixiān","Qinhuangdao seafood","Crabs, shrimp and shellfish from the Bohai Sea, cooked fresh in the seaside restaurants of Qinhuangdao."]]},{"id":"baoding","zh":"保定","py":"Bǎodìng","en":"Baoding","lat":38.87,"lon":115.46,"note":"A former provincial capital close to the capital.","stops":[["A","白洋淀","Báiyángdiàn","Baiyangdian Lake","A large wetland of reeds, lotus flowers and little lakes, where you travel by boat through narrow channels.","",38.93,116.0],["A","清西陵","Qīngxīlíng","Western Qing Tombs","A burial ground of four Qing emperors, in a pine forest, with red walls and stone gates.","",39.4,115.37],["D","保定驴肉火烧","Bǎodìng lǘròu huǒshāo","Baoding donkey burger","The classic donkey meat bun from Baoding, with a crisp, golden bread and soft, savory meat."],["D","白洋淀鱼","Báiyángdiàn yú","Baiyangdian fish","Fish from the lake, stewed in a pot with local herbs, a taste of the wetland."]]},{"id":"tangshan","zh":"唐山","py":"Tángshān","en":"Tangshan","lat":39.63,"lon":118.18,"note":"An industrial port city rebuilt after an earthquake.","stops":[["A","清东陵","Qīngdōnglíng","Eastern Qing Tombs","A large tomb complex of Qing emperors, including Qianlong and Empress Dowager Cixi, set in the hills at the foot of Mount Changrui.","",40.18,117.68],["D","唐山棋子烧饼","Tángshān qízi shāobǐng","Tangshan chess flatbread","A small, round flatbread like a chess piece, baked with sesame seeds, a Tangshan favorite."]]},{"id":"handan","zh":"邯郸","py":"Hándān","en":"Handan","lat":36.61,"lon":114.54,"note":"An ancient city of Zhao and many Chinese idioms.","stops":[["D","邯郸武安小米","Hándān wǔ’ān xiǎomǐ","Wu'an millet","Millet from the hills of Wu'an, which cooks into a fragrant, golden porridge."]]},{"id":"zhangjiakou","zh":"张家口","py":"Zhāngjiākǒu","en":"Zhangjiakou","lat":40.82,"lon":114.89,"note":"A northern city that co-hosted the 2022 Winter Olympics.","stops":[["D","莜面","Yóumiàn","Oat noodles","Noodles made from naked oats, rolled and steamed into small cylinders, a staple of the cool highlands in Zhangjiakou."]]},{"id":"langfang","zh":"廊坊","py":"Lángfāng","en":"Langfang","lat":39.52,"lon":116.68,"note":"A city between Beijing and Tianjin.","stops":[["D","大厂香肠","Dàchǎng xiāngcháng","Dachang sausage","A spiced sausage made by the Hui community of Dachang, with a rich, savory taste."]]},{"id":"xingtai","zh":"邢台","py":"Xíngtái","en":"Xingtai","lat":37.07,"lon":114.5,"note":"One of the oldest cities in northern China.","stops":[["D","内丘酥饼","Nèiqiū sūbǐng","Neiqiu pastry","A buttery, flaky pastry from Neiqiu, a sweet treat with a long tradition."]]},{"id":"cangzhou","zh":"沧州","py":"Cāngzhōu","en":"Cangzhou","lat":38.3,"lon":116.84,"note":"A martial arts city by the Bohai Sea.","stops":[["D","金丝小枣","Jīnsī xiǎozǎo","Golden-thread jujubes","Small jujubes that show golden threads of sugar when you break them in half, among the best dates in China."],["D","沧州火锅鸡","Cāngzhōu huǒguō jī","Cangzhou hotpot chicken","Chicken stewed with spices in a pot at the table, a favorite meal in Cangzhou."]]},{"id":"hengshui","zh":"衡水","py":"Héngshuǐ","en":"Hengshui","lat":37.74,"lon":115.67,"note":"A city by a lake, famous for its schools.","stops":[["D","衡水老白干","Héngshuǐ lǎobáigàn","Hengshui Laobaigan","A strong, clear spirit made in Hengshui for centuries, with a sharp and clean taste."]]}],"munis":{"Beijing":"Beijing is a municipality in its own right, directly under the national government, not part of Hebei. It sits in the middle of Hebei, so it is visited here.","Tianjin":"Tianjin is a municipality in its own right, directly under the national government, not part of Hebei. It sits beside Hebei and Beijing, so it is visited here."},"air":{"zh":"北京首都国际机场","py":"Běijīng Shǒudū Guójìjīchǎng","en":"Beijing Capital International Airport","code":"PEK","lat":40.08,"lon":116.58,"note":"The capital's main international airport, northeast of the city. Welcome to Hebei."}},{"id":"heilongjiang","zh":"黑龙江","py":"Hēilóngjiāng","en":"Heilongjiang","cities":[{"id":"harbin","zh":"哈尔滨","py":"Hā’ěrbīn","en":"Harbin","lat":45.8,"lon":126.53,"note":"The Ice City, with Russian architecture and a famous winter festival.","stops":[["A","圣索菲亚教堂","Shèng Suǒfēiyà Jiàotáng","St. Sophia Cathedral","A Russian Orthodox church with a big green onion dome and red brick walls, built in the early 20th century. It is the symbol of Harbin and sits in a lively square.","",45.77,126.62,1],["A","中央大街","Zhōngyāngdà Jiē","Central Street","A cobbled pedestrian street lined with European-style buildings from the early 1900s, full of cafés, shops and street performers.","",45.77,126.62],["A","冰雪大世界","Bīngxuě Dà Shìjiè","Harbin Ice and Snow World","Every winter, workers build a huge park of glowing towers, castles and slides out of blocks of ice cut from the Songhua River. It lights up in rainbow colors at night.","",45.78,126.58,1],["A","太阳岛","Tàiyángdǎo","Sun Island","A leafy island park in the Songhua River, with lawns, lakes and villas. It is a summer escape and a winter snow sculpture show.","",45.8,126.57],["A","松花江","Sōnghuājiāng","Songhua River","Harbin's river, wide and slow in summer and frozen thick enough in winter for skating, sledding and ice sculptures.","",45.77,126.6],["A","东北虎林园","Dōngběi Hǔlínyuán","Siberian Tiger Park","A park that breeds Siberian tigers, the largest big cats, which you can watch from a bus as they roam outside.","",45.84,126.6],["A","731部队遗址","731 Bùduì Yízhǐ","Unit 731 Museum","A museum on the site of a Japanese wartime biological weapons unit, and a solemn reminder of the war's suffering.","",45.6,126.62],["A","哈尔滨极地馆","Hā’ěrbīn Jídìguǎn","Harbin Polar Land","An aquarium and polar park, where you can see polar bears, penguins and beluga whales in the cold north.","",45.78,126.58],["D","锅包肉","Guōbāoròu","Guobaorou","Crispy slices of pork coated in a sweet and sour glaze, said to have been invented in Harbin for Russian guests. It is the signature dish of the northeast.","",null,null,1],["D","红肠","Hóngcháng","Harbin red sausage","Harbin's smoked red sausage has a Russian-style recipe, with a garlicky, smoky flavor, and is sold in shops everywhere."],["D","马迭尔冰棍","Mǎdié’ěr bīnggùn","Modern ice cream bar","A creamy ice cream bar sold on Central Street from a hotel since the 1900s, eaten even in winter in freezing weather."],["D","大列巴","Dà lièbā","Big lieba","A big, round, dense loaf of bread in the Russian style, with a crisp crust, which is often sold at old bakeries in Harbin."],["D","哈尔滨啤酒","Hā’ěrbīn píjiǔ","Harbin beer","One of the oldest beer brands in China, first brewed in Harbin in 1900 by a Czech-Polish entrepreneur."],["D","冻梨","Dònglí","Frozen pear","Pears frozen outside in winter until they turn black, then thawed in cold water, soft, icy and sweet."],["D","杀猪菜","Shāzhū cài","Pig-slaughter dishes","A hearty winter feast of pork, blood sausage, pickled cabbage and potatoes cooked together, traditionally eaten after a pig is slaughtered."],["C","冰雪节","Bīngxuějié","Ice and Snow Festival","Harbin's annual winter festival, with ice sculptures, snow carving contests and winter swimming in the Songhua River."],["C","俄罗斯风情","Éluósī fēngqíng","Russian influence","Many of the city's buildings, foods and customs recall the Russians who came to build the railway and to settle here."],["C","冰灯","Bīngdēng","Ice lanterns","Lanterns carved from ice, with a candle or LED inside, were a folk tradition among the people of the northeast long before the festival."]]},{"id":"qiqihar","zh":"齐齐哈尔","py":"Qíqíhā’ěr","en":"Qiqihar","lat":47.35,"lon":123.97,"note":"A northern city with cranes and a wetland.","stops":[["A","扎龙湿地","Zhālóng Shīdì","Zhalong Wetland","A vast wetland and nature reserve where red-crowned cranes nest every year, one of the best places to see them.","",47.2,124.25],["D","齐齐哈尔烤肉","Qíqíhā’ěr kǎoròu","Qiqihar barbecue","Meat grilled at the table over charcoal, with its own style of dipping sauce, a lively local meal."],["D","扎龙鹤","Zhālóng hè","Zhalong crane","The red-crowned crane is a symbol of long life in China, and Qiqihar is proud to be its home."]]},{"id":"mudanjiang","zh":"牡丹江","py":"Mǔdānjiāng","en":"Mudanjiang","lat":44.55,"lon":129.63,"note":"A lake and forest city, with a snow village.","stops":[["A","镜泊湖","Jìngpōhú","Jingpo Lake","A long mountain lake formed by volcanic lava that blocked a river, with a green bank and a waterfall at the north end.","",43.9,128.9],["A","吊水楼瀑布","Diàoshuǐlóu Pùbù","Diaoshuilou Waterfall","A wide waterfall at the outflow of Jingpo Lake, which pours over a lava rim into a deep pool.","",43.88,128.78],["A","中国雪乡","Zhōngguó Xuěxiāng","China Snow Town","A mountain village famous for its heavy snowfall, with thick, soft caps of snow on the roofs of its wooden houses.","",44.8,128.5],["A","雪乡","Xuěxiāng","Snow Village","A hamlet in the mountains where snow piles up on the roofs and visitors come in winter to see it by lantern light.","",44.8,128.5],["D","牡丹江冷面","Mǔdānjiāng lěngmiàn","Mudanjiang cold noodles","Chewy cold noodles in a tangy, sweet and sour broth with beef and pickled vegetables. They are part of the Korean heritage of the area."],["D","五常大米","Wǔcháng dàmǐ","Wuchang rice","A prized rice grown near Wuchang in rich black soil, known for its fragrance and sticky texture."],["C","朝鲜族风情","Cháoxiǎnzú fēngqíng","Korean culture","Ethnic Koreans have lived here for generations, and their food, dance, clothing and festivals are part of local life."]]},{"id":"jiamusi","zh":"佳木斯","py":"Jiāmùsī","en":"Jiamusi","lat":46.8,"lon":130.32,"note":"A city on the Songhua near the Russian border.","stops":[["D","鱼皮","Yúpí","Fish skin crafts","The Hezhe people of the Amur region traditionally made clothes and crafts from fish skin, a rare skill."],["D","抚远大马哈鱼","Fǔyuǎn dàmǎhāyú","Fuyuan salmon","Salmon swim up the Amur and Ussuri rivers each autumn. Fuyuan is known for its fresh salmon and red roe."]]},{"id":"daqing","zh":"大庆","py":"Dàqìng","en":"Daqing","lat":46.59,"lon":125.1,"note":"An oil city on the plains.","stops":[["D","大庆烤鱼","Dàqìng kǎoyú","Daqing grilled fish","Fish grilled and then simmered in a spicy sauce with vegetables, a popular dish for sharing."],["D","杜蒙羊肉","Dùméng yángròu","Dumeng lamb","Lamb raised on Dumo's grasslands is tender, with little gamey taste, and is cooked in stews and barbecue."]]},{"id":"heihe","zh":"黑河","py":"Hēihé","en":"Heihe","lat":50.25,"lon":127.53,"note":"A border city facing Russia across the Amur.","stops":[["A","黑龙江大桥","Hēilóngjiāng Dàqiáo","Amur River Bridge","A bridge across the Amur River, which marks the border between China and Russia, and connects the cities of Heihe and Blagoveshchensk.","",50.25,127.5],["A","五大连池","Wǔdàlián Chí","Wudalianchi","A park of dormant volcanoes, black lava fields, and five linked lakes. It is a UNESCO Global Geopark.","A UNESCO Global Geopark.",48.7,126.1],["D","五大连池矿泉水","Wǔdàlián chí kuàngquánshuǐ","Wudalianchi mineral water","Mineral water from the volcanic springs is slightly fizzy with a distinctive taste, sold across China."]]},{"id":"mohe","zh":"漠河","py":"Mòhé","en":"Mohe","lat":52.97,"lon":122.54,"note":"The northernmost town of China.","stops":[["A","北极村","Běijícūn","Arctic Village","The northernmost village in China, in Mohe, where summer nights are very short, and in winter it is bitterly cold.","",53.48,122.35],["A","北极光","Běijíguāng","Northern lights","On rare clear nights in summer, green lights can dance in the sky above Mohe, the best place in China to see the aurora.","",53.48,122.35,1],["D","蓝莓","Lánméi","Blueberry","Wild blueberries grow in the northern forests and are picked in summer, often used for jam and wine."],["D","驯鹿","Xùnlù","Reindeer","The Ewenki people raise reindeer in the Greater Khingan forests, and the animals are central to their culture."],["C","鄂伦春族","Èlúnchūn zú","Oroqen people","A small people of the northeast forests who traditionally lived by hunting and wore clothes of skins."]]},{"id":"yichun-hlj","zh":"伊春","py":"Yīchūn","en":"Yichun","lat":47.73,"lon":128.84,"note":"A forest city, a source of timber for decades.","stops":[["A","红松林","Hóngsōnglín","Korean pine forest","A forest of tall Korean pines in Yichun, which provide wood and big pine nuts and are the symbol of the Lesser Khingan range.","",47.73,128.84],["D","松子","Sōngzi","Pine nuts","Pine nuts from Korean pines are large and rich, and are a snack and an ingredient across the northeast."],["D","蓝莓酒","Lánméi jiǔ","Blueberry wine","A sweet, deep purple wine made from wild blueberries of the northern forests."]]},{"id":"shuangyashan","zh":"双鸭山","py":"Shuāngyāshān","en":"Shuangyashan","lat":46.64,"lon":131.16,"note":"A coal city on the Wusuli River.","stops":[["A","乌苏里江","Wūsūlǐ Jiāng","Ussuri River","A river that forms part of the border with Russia and is known for its salmon and for a famous folk song.","",46.64,131.16],["D","双鸭山大米","Shuāngyāshān dàmǐ","Shuangyashan rice","Rice grown on the black soil of the Sanjiang Plain, with a sweet and soft grain."]]},{"id":"suihua","zh":"绥化","py":"Suíhuà","en":"Suihua","lat":46.64,"lon":126.97,"note":"A farming city.","stops":[["A","大兴安岭","Dàxīng’ān Lǐng","Great Khingan","A huge forested range in the far north of China, with larch trees, rivers and wildlife, and cold winters.","",51.0,124.0]]},{"id":"hegang","zh":"鹤岗","py":"Hègǎng","en":"Hegang","lat":47.35,"lon":130.3,"note":"A quiet coal town with very cheap homes.","stops":[]}],"air":{"zh":"哈尔滨太平国际机场","py":"Hā’ěrbīn Tàipíng Guójì Jīchǎng","en":"Harbin Taiping International Airport","code":"HRB","lat":45.62,"lon":126.25,"note":"The main airport of Heilongjiang, in the far northeast. Welcome to Heilongjiang."}},{"id":"henan","zh":"河南","py":"Hénán","en":"Henan","cities":[{"id":"zhengzhou","zh":"郑州","py":"Zhèngzhōu","en":"Zhengzhou","lat":34.75,"lon":113.63,"note":"A rail hub on the Yellow River plain, once a capital of the Shang dynasty.","stops":[["A","河南博物院","Hénán Bówùyuàn","Henan Museum","One of China's oldest museums, it holds Shang bronzes, jade, and the Jiahu bone flutes, among the oldest playable instruments in the world.","",34.77,113.67],["A","商城遗址","Shāngchéng Yízhǐ","Shang City Ruins","The remains of a city wall from the Shang dynasty about 3,500 years ago, beside modern Zhengzhou.","",34.76,113.68],["A","黄河风景名胜区","Huánghé Fēngjǐng Míngshèngqū","Yellow River Scenic Area","A park on the south bank of the Yellow River, with large statues of the legendary emperors Yan and Huang on a mountain slope.","",34.93,113.51],["A","二七纪念塔","Èrqī Jìniàntǎ","Erqi Tower","A twin-towered memorial in the middle of Zhengzhou, honoring a railway workers' strike in 1923.","",34.76,113.66],["A","少林寺","Shàolínsì","Shaolin Temple","The famous Chan Buddhist temple at the foot of Mount Song, where kung fu is said to have begun. Monks still train in its courtyards.","",34.51,112.94,1],["A","嵩山","Sōngshān","Mount Song","One of the Five Sacred Mountains of China, with Shaolin Temple, Zhongyue Temple and old observatory on its slopes.","",34.48,113.03],["A","中岳庙","Zhōngyuè Miào","Zhongyue Temple","A temple for the god of Mount Song, the central sacred mountain, with halls of the Daoist tradition, and giant old cypress trees.","",34.46,113.05],["D","烩面","Huìmiàn","Braised noodles","Wide hand-pulled noodles in a rich mutton broth, with seaweed and tofu, the staple of Zhengzhou. Cooks pull and stretch the dough just before it goes in the pot.","",null,null,1],["D","胡辣汤","Húlàtāng","Hu la soup","A thick, peppery soup of beef or lamb, with wheat gluten and spices, eaten at breakfast with fried dough."],["D","灌汤包","Guàn tāngbāo","Soup dumplings","Large steamed buns filled with a pocket of hot broth, so you must bite carefully and sip the soup first."],["D","河南蒸面条","Hénán zhēng miàntiáo","Steamed noodles","Noodles tossed in flour and steamed with vegetables, then dressed with garlic sauce, a simple home favorite."],["C","少林功夫","Shàolín gōngfu","Shaolin kung fu","The martial arts of Shaolin monks, trained for centuries, include fast fists, staff fighting and strong stances."],["C","豫剧","Yùjù","Henan opera","Henan opera, with strong, high singing, is the most widely performed opera in China, with fans across the country."]]},{"id":"luoyang","zh":"洛阳","py":"Luòyáng","en":"Luoyang","lat":34.62,"lon":112.45,"note":"An ancient capital for thirteen dynasties, famous for peonies.","stops":[["A","龙门石窟","Lóngmén Shíkū","Longmen Grottoes","Thousands of Buddhist carvings line a limestone cliff by the Yi River, including a giant seated Buddha about 17 meters tall. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",34.56,112.47,1],["A","白马寺","Báimǎsì","White Horse Temple","The first Buddhist temple in China, said to have been founded in the first century CE, when white horses carried Buddhist scriptures to Luoyang.","",34.72,112.6],["A","关林","Guānlín","Guanlin Temple","A temple and tomb for the general Guan Yu, whose head is said to be buried here, honored as a god of loyalty.","",34.6,112.46],["A","洛阳博物馆","Luòyáng Bówùguǎn","Luoyang Museum","A museum that tells the long story of Luoyang, a capital for many dynasties, with Tang tomb figures and Luoyang's treasures.","",34.62,112.45],["A","应天门","Yīng Tiānmén","Yingtian Gate","A huge reconstructed gate of the Sui and Tang palace in Luoyang, a sign of the capital's grandeur.","",34.67,112.46],["D","洛阳水席","Luòyáng shuǐxí","Luoyang water banquet","A traditional banquet of about 24 dishes, many of them soups, which are served one after another, each new dish replacing the last."],["D","不翻汤","Bùfān tāng","Bufan soup","A soup of eggs and pork, poached gently so that it does not need to be flipped, served in a bowl, and a Luoyang water-banquet dish."],["D","牡丹饼","Mǔdān bǐng","Peony cake","A sweet pastry made with peony petals, a delicate Luoyang treat that reflects the city's love for its flower."],["C","牡丹花会","Mǔdān huāhuì","Peony Festival","Every spring, Luoyang holds a flower festival when thousands of peonies are in bloom, and crowds fill the city's parks."],["C","唐三彩","Tángsāncǎi","Tang sancai ceramics","Tang sancai are lead-glazed pottery figures of horses, camels and ladies in green, yellow and white glaze, once placed in tombs."]]},{"id":"kaifeng","zh":"开封","py":"Kāifēng","en":"Kaifeng","lat":34.8,"lon":114.31,"note":"The capital of the Northern Song dynasty, with canals and night markets.","stops":[["A","龙亭","Lóngtíng","Dragon Pavilion","A palace hall on a high platform beside a lake in Kaifeng, built where the palace of the Song dynasty stood.","",34.81,114.35],["A","铁塔","Tiětǎ","Iron Pagoda","A tall brown pagoda covered in glazed bricks, built in the Song dynasty. It looks like iron but is made of ceramic.","",34.81,114.36],["A","相国寺","Xiàngguósì","Xiangguo Temple","A major Buddhist temple of the Song era in Kaifeng, once the largest in the capital and home to a busy market.","",34.8,114.35],["D","开封灌汤包","Kāifēng guàn tāngbāo","Kaifeng soup buns","Delicate soup dumplings with thin skin from a famous Kaifeng shop, filled with a rich broth."],["D","黄焖鱼","Huángmèn yú","Braised Yellow River carp","Carp from the Yellow River braised in a rich, savory sauce, a classic Kaifeng dish."],["D","花生糕","Huāshēng gāo","Peanut cake","A sweet, crumbly snack made from peanuts and sugar, sold at the busy night market."],["C","菊花展","Júhuā zhǎn","Chrysanthemum show","Kaifeng's city flower is the chrysanthemum, and every autumn the city holds a show with thousands of blooms."]]},{"id":"anyang","zh":"安阳","py":"Ānyáng","en":"Anyang","lat":36.1,"lon":114.39,"note":"The site of the last Shang capital and the earliest Chinese writing.","stops":[["A","殷墟","Yīnxū","Yin Ruins","The ruins of the last capital of the Shang dynasty, where oracle bone inscriptions were found. It is a UNESCO World Heritage Site and the home of China's earliest writing.","A UNESCO World Heritage Site.",36.13,114.32,1],["A","中国文字博物馆","Zhōngguó Wénzì Bówùguǎn","Chinese Characters Museum","A museum on the history of Chinese writing, from oracle bones to modern characters, in Anyang.","",36.11,114.36],["A","红旗渠","Hóngqíqú","Red Flag Canal","A canal that villagers cut into the cliffs of the Taihang Mountains in the 1960s to bring water to dry land, a symbol of determination.","",36.12,113.84],["D","安阳扁粉菜","Ānyáng biǎnfěn cài","Anyang flat noodle stew","A hearty stew with flat sweet potato noodles, vegetables, and meat, a typical winter dish in Anyang."],["D","道口烧鸡","Dàokǒu shāojī","Daokou roast chicken","A braised chicken from Daokou, so tender that the bones can be pulled out whole. It has been famous for hundreds of years."],["C","甲骨文","Jiǎgǔwén","Oracle bone script","Oracle bone script, the earliest known form of Chinese writing, was carved on turtle shells and bones for divination about 3,000 years ago."]]},{"id":"jiaozuo","zh":"焦作","py":"Jiāozuò","en":"Jiaozuo","lat":35.24,"lon":113.24,"note":"The hometown of tai chi and a mountain of cliffs.","stops":[["A","云台山","Yúntáishān","Yuntai Mountain","A canyon park with waterfalls, cliff paths and clear pools, often called a green gem in northern Henan.","",35.43,113.37],["D","怀山药","Huái shānyào","Huai yam","The Huai yam is a famous Henan product that is used in soups and in traditional medicine, valued for its smooth texture."],["C","太极拳","Tàijíquán","Tai chi","Tai chi is a slow, flowing martial art, born in Chenjiagou village in Henan, and now practiced worldwide for health."]]},{"id":"nanyang","zh":"南阳","py":"Nányáng","en":"Nanyang","lat":33.0,"lon":112.53,"note":"The city of Zhuge Liang and a famed doctor.","stops":[["D","南阳黄牛","Nányáng huángniú","Nanyang beef","Cattle from Nanyang, with tender beef that is braised or grilled, is a local specialty."],["C","玉雕","Yùdiāo","Jade carving","Jade carved in Zhenping and Nanyang is a craft that has been practiced for centuries, from small pendants to large sculptures."]]},{"id":"shangqiu","zh":"商丘","py":"Shāngqiū","en":"Shangqiu","lat":34.41,"lon":115.66,"note":"A city that gave its name to the Shang.","stops":[["D","商丘烧饼","Shāngqiū shāobǐng","Shangqiu sesame flatbread","A crisp, layered sesame flatbread, often filled with meat, baked fresh in Shangqiu."]]},{"id":"xinyang","zh":"信阳","py":"Xìnyáng","en":"Xinyang","lat":32.13,"lon":114.09,"note":"A southern city known for green tea.","stops":[["A","南湾湖","Nánwān Hú","Nanwan Lake","A large lake with green islands and hills near Xinyang, a favorite place for a break.","",32.07,114.0],["D","信阳毛尖","Xìnyáng máojiān","Xinyang Maojian tea","One of China's famous green teas, with slender, curled leaves and a fresh, mellow taste, grown in the hills of Xinyang."],["D","罗山板栗","Luóshān bǎnlì","Luoshan chestnuts","Sweet, soft chestnuts from the Dabie Mountains, roasted in autumn."]]},{"id":"pingdingshan","zh":"平顶山","py":"Píngdǐngshān","en":"Pingdingshan","lat":33.74,"lon":113.19,"note":"A coal city near a famous scenic mountain.","stops":[["D","鲁山花生","Lǔshān huāshēng","Lushan peanuts","A local peanut variety with rich, sweet taste, grown in the hills of Lushan."]]}],"air":{"zh":"郑州新郑国际机场","py":"Zhèngzhōu Xīnzhèng Guójì Jīchǎng","en":"Zhengzhou Xinzheng International Airport","code":"CGO","lat":34.52,"lon":113.84,"note":"A cargo and passenger hub in the Central Plains. Welcome to Henan."}},{"id":"hongkong","zh":"香港","py":"Xiānggǎng","en":"Hong Kong","cities":[{"id":"hongkong-island","zh":"香港岛","py":"Xiānggǎng Dǎo","en":"Hong Kong Island","lat":22.28,"lon":114.16,"note":"The financial heart, with towers, trams and a famous peak.","stops":[["A","太平山顶","Tàipíng Shāndǐng","Victoria Peak","The hill above Hong Kong Island with the classic view of skyscrapers, Victoria Harbour and Kowloon. It is especially magical at dusk, when the lights come on.","",22.27,114.15,1],["A","山顶缆车","Shāndǐng Lǎnchē","Peak Tram","A steep cable railway that has carried passengers up to Victoria Peak since 1888, with a ride that feels almost vertical.","",22.28,114.16],["A","中环","Zhōnghuán","Central","The business heart of Hong Kong, with glass towers, old markets, trams and the bank buildings that line the harbor.","",22.28,114.16],["A","兰桂坊","Lánguìfāng","Lan Kwai Fong","A small, sloping lane in Central packed with bars and restaurants, a hub of nightlife.","",22.28,114.16],["A","文武庙","Wénwǔmiào","Man Mo Temple","A temple for Man, the god of literature, and Mo, the god of war, with large incense coils hanging from the ceiling.","",22.28,114.15],["A","铜锣湾","Tóngluówān","Causeway Bay","A busy shopping district with department stores, street food and bright signs, and the noon gun that is fired each day.","",22.28,114.18],["A","赤柱","Chìzhù","Stanley","A seaside village on the south side of Hong Kong Island with a market, a waterfront promenade and old temples.","",22.22,114.21],["A","浅水湾","Qiǎnshuǐwān","Repulse Bay","One of the most popular beaches on Hong Kong Island, with a curve of golden sand, apartments and a Kwun Yam shrine.","",22.24,114.2],["A","海洋公园","Hǎiyáng Gōngyuán","Ocean Park","A marine theme park built on a hillside, with rides, aquariums, pandas and a cable car above the sea.","",22.25,114.18],["A","中环半山自动扶梯","Zhōnghuán Bànshān Zìdòngfútī","Central-Mid-Levels Escalator","A chain of escalators and walkways about 800 meters long that carries people up the steep hill from Central to the Mid-Levels.","",22.28,114.15],["D","菠萝包","Bōluóbāo","Pineapple bun","A sweet bun with a crusty, cookie-like top that looks like a pineapple, but has no pineapple. It is best eaten warm, with a slab of butter.","The name is said to come from its checked top, like a pineapple skin."],["D","港式奶茶","Gǎngshì nǎichá","Hong Kong milk tea","A strong black tea mixed with evaporated milk and strained through a cloth bag, silky smooth. It is Hong Kong's favorite drink.","",null,null,1],["D","鸡蛋仔","Jīdàn zǎi","Egg waffle","A bubble-shaped waffle with a crisp shell and a soft center, cooked in a special mold, sold hot from street stalls."],["D","烧鹅","Shāo’é","Roast goose","Crisp-skinned roast goose with juicy meat, a Hong Kong favorite that is often served with plum sauce and rice."],["D","云吞面","Yúntūnmiàn","Wonton noodles","Thin, springy egg noodles in a clear broth with shrimp wontons, a Hong Kong classic with a long tradition."],["D","蛋挞","Dàntà","Egg tart","A tart with a flaky or crumbly crust and a smooth, golden custard. It is a staple of bakeries and teahouses."],["D","茶餐厅","Chácāntīng","Cha chaan teng","The Hong Kong-style café that serves toast, noodles, rice dishes and milk tea. It is a fast, noisy and friendly part of the city's life."],["D","烧腊","Shāolà","Siu mei","Roast meats such as char siu, roast pork and goose hang in shop windows, and are served over rice."],["C","粤剧","Yuèjù","Cantonese opera","Cantonese opera, with its glittering costumes and sung stories, is still staged in Hong Kong, in large temporary bamboo theaters at festivals."],["C","港片","Gǎngpiàn","Hong Kong cinema","Hong Kong cinema is famous for kung fu films, crime thrillers and romances, with stars such as Bruce Lee, Jackie Chan and Chow Yun-fat.","",null,null,1],["C","太平清醮","Tàipíng qīngjiào","Cheung Chau Bun Festival","On Cheung Chau, the Bun Festival has towers of sweet buns, parades and lion dances, to ask the gods for peace."],["C","龙舟","Lóngzhōu","Dragon boat races","At the Dragon Boat Festival, teams of paddlers race long, painted boats to the beat of a drum."]]},{"id":"kowloon","zh":"九龙","py":"Jiǔlóng","en":"Kowloon","lat":22.32,"lon":114.17,"note":"The crowded peninsula of markets and neon signs.","stops":[["A","星光大道","Xīngguāng Dàdào","Avenue of Stars","A promenade on the Kowloon waterfront with handprints and statues of film stars, facing the skyline of Hong Kong Island.","",22.29,114.17],["A","尖沙咀","Jiānshājǔ","Tsim Sha Tsui","A bustling harbor district of Kowloon with shops, hotels, museums, and the Clock Tower beside the water.","",22.3,114.17],["A","庙街夜市","Miàojiē Yèshì","Temple Street Night Market","A night market with stalls for clothes, trinkets, fortune tellers and street food, at its liveliest in the evening.","",22.31,114.17],["A","旺角","Wàngjiǎo","Mong Kok","One of the most densely populated areas in the world, with neon signs, crowded streets and endless shops.","",22.32,114.17],["A","女人街","Nǚrénjiē","Ladies' Market","A market street where stalls sell clothes, bags and accessories at low prices, and bargaining is expected.","",22.32,114.17],["A","雀鸟花园","Quèniǎo Huāyuán","Yuen Po Street Bird Garden","A garden market where men hang cages with songbirds and trade them. The air is full of birdsong.","",22.33,114.17],["A","志莲净苑","Zhìlián Jìngyuàn","Chi Lin Nunnery","A Buddhist nunnery in Tang-dynasty style, built of wood without nails, set in a quiet garden of lotus ponds.","",22.34,114.21],["A","南莲园池","Nánliányuán Chí","Nan Lian Garden","A classical Chinese garden with ponds, rocks, wooden pavilions and bonsai, next to the nunnery. It offers calm in the city.","",22.34,114.21],["A","黄大仙祠","Huángdàxiān Cí","Wong Tai Sin Temple","A busy Taoist temple where people shake fortune sticks, and ask for health and luck.","",22.34,114.19],["A","九龙寨城公园","Jiǔlóng Zhàichéng Gōngyuán","Kowloon Walled City Park","A park on the site of the old Kowloon Walled City, once an enclave of dense, tall buildings that was torn down in the 1990s.","",22.33,114.19],["D","鱼蛋","Yúdàn","Curry fish balls","Fish balls on a stick or in a bowl, covered in a spicy curry sauce, a classic Hong Kong street snack."],["D","车仔面","Chēzǎimiàn","Cart noodles","Cart noodles are a bowl of noodles to which you add toppings, such as beef brisket, radish and fish balls, in a rich soup."],["D","点心","Diǎnxīn","Dim sum","Dim sum are bite-sized dishes served in bamboo steamers with tea. Dumplings, buns and rolls are shared by the family around a table.","",null,null,1],["D","糖水","Tángshuǐ","Tong sui","A sweet dessert soup, from red bean to mango with sago, served warm or cold after a meal."],["D","烧卖","Shāomài","Siu mai","A steamed open dumpling filled with pork and shrimp, topped with an orange dot, found at every dim sum meal."],["D","港式炒饭","Gǎngshì chǎofàn","Hong Kong fried rice","A plate of fried rice with egg, char siu or shrimp, stir-fried until each grain is separate and fragrant."],["C","风水","Fēngshuǐ","Feng shui","Feng shui is the art of arranging buildings, doors and water according to the flow of qi, and it shapes many of Hong Kong's skyscrapers."]]},{"id":"new-territories","zh":"新界","py":"Xīnjiè","en":"New Territories","lat":22.42,"lon":114.15,"note":"The green north, with villages, hills and islands.","stops":[["A","大屿山天坛大佛","Dàyǔshān Tiāntán Dàfú","Tian Tan Buddha","A giant bronze Buddha, 34 meters high, sits on a hill on Lantau Island, with 268 steps leading up to it. Monks at the nearby monastery serve vegetarian meals.","",22.25,113.9,1],["A","昂坪360","Ángpíng 360","Ngong Ping 360","A long cable car ride over the sea and mountains of Lantau to Ngong Ping, with views of the airport and the South China Sea.","",22.25,113.91],["A","大澳","Dà’ào","Tai O","A fishing village of stilt houses over the water, where you can take a boat to look for pink dolphins and try shrimp paste.","",22.25,113.86],["A","西贡","Xīgòng","Sai Kung","A seaside town known for its seafood restaurants, country parks, beaches and islands with volcanic rock columns.","",22.38,114.27],["A","香港迪士尼乐园","Xiānggǎng Díshìní Lèyuán","Hong Kong Disneyland","A theme park on Lantau Island, with rides, shows and characters, built in a smaller style than other Disney parks.","",22.31,114.04],["A","沙田","Shātián","Sha Tin","A city in the New Territories with a river, a racecourse, a big shopping mall and a large heritage museum.","",22.38,114.19],["A","万佛寺","Wànfósì","Ten Thousand Buddhas Monastery","A hillside monastery with thousands of small golden Buddha statues along its steps, and a hall with a preserved monk.","",22.38,114.2],["A","长洲","Chángzhōu","Cheung Chau","A small, car-free island with beaches, seafood, and a big bun festival, an easy ferry ride from Central.","",22.21,114.03],["A","南丫岛","Nányādǎo","Lamma Island","A car-free island with hiking trails, seafood restaurants and quiet villages, where life is calm and slow.","",22.21,114.12],["D","大澳虾酱","Dà’ào xiājiàng","Tai O shrimp paste","Tai O is known for its shrimp paste, a salty, strong-smelling paste used in cooking and in sauces."],["D","盆菜","Péncài","Poon choi","A big basin that is layered with meats, seafood, tofu and vegetables, eaten from the top down, a village feast tradition."],["D","西贡海鲜","Xīgòng hǎixiān","Sai Kung seafood","Fresh fish and shellfish are picked from tanks and cooked right away at the waterfront restaurants of Sai Kung."],["D","长洲平安包","Chángzhōu píng’ān bāo","Cheung Chau peace buns","Sweet buns stamped with a red character for peace, piled into towers at the festival and eaten for luck."],["C","客家围村","Kèjiā wéicūn","Walled villages","Walled villages built by clans for protection, with thick walls and gates, some with their own temples and ancestral halls."],["C","疍家","Dànjiā","Tanka people","The Tanka, or boat people, lived their whole lives on boats in the harbor and have their own songs and customs."]]}],"air":{"zh":"香港国际机场","py":"Xiānggǎng Guójì Jīchǎng","en":"Hong Kong International Airport","code":"HKG","lat":22.31,"lon":113.92,"note":"Hong Kong's airport on Chek Lap Kok island. Welcome to Hong Kong."}},{"id":"hubei","zh":"湖北","py":"Húběi","en":"Hubei","cities":[{"id":"wuhan","zh":"武汉","py":"Wǔhàn","en":"Wuhan","lat":30.59,"lon":114.31,"note":"A huge city where the Yangtze meets the Han River.","stops":[["A","黄鹤楼","Huánghèlóu","Yellow Crane Tower","A five-story tower above the Yangtze, made famous by a Tang poem about a yellow crane. It has been rebuilt many times and gives a wide view of Wuhan.","",30.54,114.3,1],["A","东湖","Dōnghú","East Lake","One of the biggest city lakes in China, with long walking paths, cherry and plum gardens and boats on the water.","",30.55,114.38],["A","武汉长江大桥","Wǔhàn Chángjiāng Dàqiáo","Wuhan Yangtze River Bridge","The first bridge to span the Yangtze, opened in 1957, with a road deck above and a railway below.","",30.55,114.29],["A","户部巷","Hùbù Xiàng","Hubu Alley","A lane lined with stalls and shops that sell Wuhan's breakfast and snacks, including hot dry noodles and bean-skin pancakes.","",30.55,114.3],["A","湖北省博物馆","Húběishěng Bówùguǎn","Hubei Provincial Museum","The museum holds the chime bells of Marquis Yi of Zeng, about 2,400 years old, which can still play music.","",30.56,114.36],["A","武汉大学","Wǔhàn Dàxué","Wuhan University","A campus famous for its cherry blossoms in spring and its old buildings with green tiled roofs on a hillside.","",30.54,114.37],["D","热干面","Règànmiàn","Hot dry noodles","Wuhan's favorite breakfast noodles are tossed with sesame paste, soy sauce, pickles and scallions. They are eaten dry, not in soup.","",null,null,1],["D","豆皮","Dòupí","Doupi","A thin pancake of tofu skin wrapped around sticky rice, meat and mushrooms, and pan-fried to a golden crisp."],["D","武昌鱼","Wǔchāngyú","Wuchang fish","A freshwater bream steamed whole and served with ginger and scallions. Mao Zedong praised it in a poem."],["D","藕汤","Ǒutāng","Lotus root soup","A comforting soup of pork ribs simmered for hours with crumbly lotus root, a Hubei home dish."],["D","周黑鸭","Zhōuhēi yā","Zhou Hei Ya duck","Spicy braised duck, sold in boxes across China. It started as a Wuhan street snack with a sweet-and-spicy taste."],["D","糊汤粉","Hútāngfěn","Hutang rice noodles","A creamy fish soup with rice noodles, thickened with fish bones, eaten for breakfast in Hubei."],["C","楚文化","Chǔwénhuà","Chu culture","The ancient kingdom of Chu was known for its lacquerware, bronzes, silk and music, and for the poet Qu Yuan."],["C","汉剧","Hànjù","Han opera","Han opera is an old local style of opera from Hubei, said to be one of the ancestors of Peking opera."]]},{"id":"yichang","zh":"宜昌","py":"Yíchāng","en":"Yichang","lat":30.69,"lon":111.29,"note":"The city at the Gorge that holds the Three Gorges Dam.","stops":[["A","三峡大坝","Sānxiádà Bà","Three Gorges Dam","The largest hydropower station in the world, a 2.3-kilometer-long wall across the Yangtze. Ships go through its giant ship locks.","",30.82,111.0,1],["A","三峡人家","Sānxiá Rénjiā","Three Gorges Family","A scenic area in the Xiling Gorge with villages, waterfalls, and boat trips, showing the culture of the Tujia people.","",30.8,111.0],["A","西陵峡","Xīlíngxiá","Xiling Gorge","The longest of the Three Gorges, with steep cliffs, shoals and a history of dangerous rapids that are now calm.","",30.78,110.95],["A","屈原祠","Qūyuáncí","Qu Yuan Temple","A shrine for the poet Qu Yuan, who lived in the Chu kingdom. The Dragon Boat Festival honors his memory.","",30.97,110.69],["A","清江画廊","Qīngjiāng Huàláng","Qingjiang Gallery","A bright green river that winds between tall limestone cliffs, like a long painted scroll.","",30.32,111.04],["D","宜昌鱼糕","Yíchāng yúgāo","Yichang fish cake","A light, bouncy fish paste, steamed and served in soup, a typical banquet dish in Yichang."],["D","宜昌蜜橘","Yíchāng mìjú","Yichang tangerines","Sweet, thin-skinned tangerines grown along the Yangtze valley, picked in autumn."]]},{"id":"shennongjia","zh":"神农架","py":"Shénnóngjià","en":"Shennongjia","lat":31.74,"lon":110.68,"note":"A forested mountain region with rare animals.","stops":[["A","神农顶","Shénnóngdǐng","Shennong Peak","The highest peak in central China, in the forest reserve of Shennongjia, home to rare plants and legends of a wild man.","",31.45,110.3],["D","神农架腊肉","Shénnóngjià làròu","Shennongjia smoked pork","Pork smoked over a wood fire in the mountain farms, deep in flavor, and cooked with vegetables in winter."]]},{"id":"jingzhou","zh":"荆州","py":"Jīngzhōu","en":"Jingzhou","lat":30.33,"lon":112.24,"note":"An old walled city of the Three Kingdoms.","stops":[["A","荆州古城墙","Jīngzhōu Gǔchéngqiáng","Jingzhou City Wall","A city wall of the Ming and Qing periods that survived for hundreds of years, one of the best preserved in the south.","",30.35,112.19],["A","荆州博物馆","Jīngzhōu Bówùguǎn","Jingzhou Museum","A museum with treasures of the Chu state and a well-preserved body from a Han tomb that still has soft skin.","",30.34,112.19],["A","关公义园","Guāngōng Yìyuán","Guan Yu Memorial Garden","A memorial garden for Guan Yu, the Three Kingdoms general, who guarded Jingzhou and is honored for his loyalty.","",30.36,112.2],["D","鱼糕","Yúgāo","Jingzhou fish cake","A soft, light steamed fish cake that is served at banquets and holidays in Jingzhou."],["D","皮条鳝鱼","Pítiáo shànyú","Eel strips","Eel cut into long strips and braised in a spicy sauce, a Jingzhou specialty."]]},{"id":"xiangyang","zh":"襄阳","py":"Xiāngyáng","en":"Xiangyang","lat":32.04,"lon":112.14,"note":"A walled city that held out in famous sieges.","stops":[["A","襄阳古城墙","Xiāngyáng Gǔchéngqiáng","Xiangyang City Wall","An old wall on the Han River, with a moat, built to guard a strategic city in the Three Kingdoms period.","",32.04,112.15],["D","牛肉面","Niúròumiàn","Xiangyang beef noodles","Noodles in a bold, spicy beef broth, a Xiangyang breakfast favorite served in every corner shop."]]},{"id":"enshi","zh":"恩施","py":"Ēnshī","en":"Enshi","lat":30.27,"lon":109.49,"note":"A mountain prefecture of Tujia and Miao culture.","stops":[["A","恩施大峡谷","Ēnshī Dàxiágǔ","Enshi Grand Canyon","A deep canyon with cliffs and a tall stone pillar that rises from the valley, among the most scenic in central China.","",30.4,109.28],["A","腾龙洞","Ténglóngdòng","Tenglong Cave","One of the longest caves in China, with a huge entrance, an underground river and giant chambers.","",30.3,108.94],["D","恩施土豆","Ēnshī tǔdòu","Enshi potatoes","Small, creamy potatoes from the highlands, roasted or fried with chili and cumin."],["D","硒茶","Xīchá","Selenium tea","Green tea grown in soil rich in selenium, and Enshi is known as the selenium capital of China."]]},{"id":"huangshi","zh":"黄石","py":"Huángshí","en":"Huangshi","lat":30.2,"lon":115.04,"note":"An old mining city on the Yangtze.","stops":[["D","大冶藕","Dàyě ǒu","Daye lotus root","Soft, sweet lotus root from the lakes of Daye, often stewed in soup."]]},{"id":"xianning","zh":"咸宁","py":"Xiánníng","en":"Xianning","lat":29.84,"lon":114.32,"note":"A green city of hot springs and bamboo.","stops":[["D","桂花糕","Guìhuā gāo","Osmanthus cake","A sweet cake scented with osmanthus flowers, a popular treat in Xianning."]]},{"id":"shiyan","zh":"十堰","py":"Shíyàn","en":"Shiyan","lat":32.65,"lon":110.78,"note":"A mountain city and a home of Wudang martial arts.","stops":[["A","武当山","Wǔdāngshān","Wudang Mountain","A Taoist mountain with temples on its peaks, famous for Wudang martial arts and for its blend of architecture and nature. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",32.4,111.0,1],["A","金顶","Jīndǐng","Golden Summit","A bronze hall at the top of Wudang Mountain, covered in gold color, high above the clouds.","",32.4,111.0],["A","丹江口水库","Dānjiāngkǒu Shuǐkù","Danjiangkou Reservoir","A huge reservoir that supplies water to Beijing through the South-to-North Water Diversion Project.","",32.55,111.5],["D","武当道茶","Wǔdāng dàochá","Wudang Taoist tea","A green tea grown on the mountain, linked to the Taoist monks who tended its bushes."]]}],"air":{"zh":"武汉天河国际机场","py":"Wǔhàn Tiānhé Guójì Jīchǎng","en":"Wuhan Tianhe International Airport","code":"WUH","lat":30.78,"lon":114.21,"note":"The main airport of central China. Welcome to Hubei."}},{"id":"hunan","zh":"湖南","py":"Húnán","en":"Hunan","cities":[{"id":"changsha","zh":"长沙","py":"Chángshā","en":"Changsha","lat":28.23,"lon":112.94,"note":"A lively river city known for spicy food, TV and nightlife.","stops":[["A","岳麓山","Yuèlùshān","Yuelu Mountain","A wooded hill on the west bank of the Xiang River, with temples, pavilions, an old academy and walking paths overlooking Changsha.","",28.19,112.94],["A","岳麓书院","Yuèlù Shūyuàn","Yuelu Academy","One of the oldest academies in China, founded in 976 and still a place of study after about a thousand years, with halls and courtyards.","",28.18,112.94],["A","橘子洲","Júzizhōu","Orange Isle","A long island in the Xiang River, with parks and a giant statue of the young Mao Zedong carved in stone, and fireworks in the evening.","",28.2,112.96],["A","湖南省博物馆","Húnánshěng Bówùguǎn","Hunan Provincial Museum","The museum holds the finds from the Han tomb at Mawangdui, including a silk painting and the remarkably preserved body of Lady Dai.","",28.21,112.99],["A","太平老街","Tàipíng Lǎojiē","Taiping Old Street","A stone-paved lane of old shops, tea houses and snack stalls in Changsha, with a flavor of the old city.","",28.19,112.97],["A","天心阁","Tiānxīn Gé","Tianxin Pavilion","A tower on a remnant of the old city wall in the middle of Changsha, with a view of the city's growth.","",28.19,112.97],["D","臭豆腐","Chòudòufǔ","Stinky tofu","Fermented tofu fried until crisp, with a strong smell and a rich flavor, served with a spicy dip. A Changsha street classic."],["D","剁椒鱼头","Duòjiāo yútóu","Fish head with chopped chilies","A steamed fish head under a bright red blanket of chopped chilies. It is spicy, tender and one of Hunan's best-known dishes.","",null,null,1],["D","口味虾","Kǒuwèi xiā","Spicy crayfish","Crayfish stir-fried with chili, garlic and spices, and eaten by hand on summer nights in Changsha."],["D","糖油粑粑","Tángyóu bābā","Sugar-oil glutinous cake","Hot sticky rice cakes fried and dipped in sugar syrup. They are a sweet street snack of Changsha."],["D","长沙米粉","Chángshā mǐfěn","Changsha rice noodles","Rice noodles in a flavorful pork broth, with toppings such as minced meat, and a typical breakfast in Changsha."],["D","毛氏红烧肉","Máoshì hóngshāoròu","Chairman Mao's red-braised pork","Pork belly braised slowly in soy sauce and sugar until it is soft and glossy. A classic of Hunan home cooking."],["C","湘绣","Xiāngxiù","Xiang embroidery","Xiang embroidery uses very fine silk thread in shaded colors to make lifelike tigers, flowers and landscapes, one of the four great styles of Chinese embroidery."]]},{"id":"zhangjiajie","zh":"张家界","py":"Zhāngjiājiè","en":"Zhangjiajie","lat":29.12,"lon":110.48,"note":"A national forest park of tall sandstone pillars.","fun":"The floating Hallelujah Mountains in a famous science fiction film were inspired by these pillars.","stops":[["A","张家界国家森林公园","Zhāngjiājiè Guójiā Sēnlíngōngyuán","Zhangjiajie National Forest Park","Thousands of quartz sandstone pillars rise out of green forest, shrouded in mist. This landscape inspired the floating mountains in a famous film, and it is a UNESCO site.","",29.32,110.43,1],["A","天门山","Tiānménshān","Tianmen Mountain","A mountain with a huge natural arch known as Heaven's Gate, reached by a long cable car and a winding road with 99 bends.","",29.05,110.48],["A","天子山","Tiānzishān","Tianzi Mountain","A high area of the park with dense groups of stone pillars, which offers panoramas over the forest.","",29.34,110.41],["A","百龙天梯","Bǎilóng Tiāntī","Bailong Elevator","A glass elevator on the side of a cliff, taking visitors up almost 330 meters in about a minute.","",29.34,110.43],["A","黄龙洞","Huánglóngdòng","Yellow Dragon Cave","A huge cave system with an underground river, large halls and impressive rock formations.","",29.28,110.47],["A","大峡谷玻璃桥","Dàxiágǔ Bōlí Qiáo","Grand Canyon Glass Bridge","A very long glass-floored bridge that spans a deep gorge, with a view straight down to the bottom.","",29.27,110.53],["D","三下锅","Sān xiàguō","Sanxia guo","A hearty hotpot of meat, tofu and vegetables that is cooked at the table and enjoyed by Tujia families."],["D","土家腊肉","Tǔjiā làròu","Tujia cured pork","Pork cured and smoked over a wood fire by the Tujia people, with a deep, smoky flavor."]]},{"id":"fenghuang","zh":"凤凰","py":"Fènghuáng","en":"Fenghuang","lat":27.95,"lon":109.6,"note":"A river town of stilted houses, famous in Chinese literature.","stops":[["A","凤凰古城","Fènghuáng Gǔchéng","Fenghuang Ancient Town","Wooden houses on stilts line the Tuo River, with old gates and stone streets. At night, lanterns light up the water.","",27.95,109.6,1],["A","沈从文故居","Shěn Cóngwén Gùjū","Shen Congwen Former Residence","The home of Shen Congwen, the writer who described Fenghuang's people and landscape and made the town famous.","",27.95,109.6],["A","虹桥","Hóngqiáo","Rainbow Bridge","A covered bridge with shops and teahouses inside, and a popular place to watch the river.","",27.95,109.6],["D","姜糖","Jiāngtáng","Ginger candy","Ginger candy stretched by hand into long strips, with a spicy sweet taste. A traditional treat in Fenghuang."],["D","血粑鸭","Xuèbā yā","Duck with blood rice cake","A spicy Miao-style duck stir-fried with rice cake, chili and herbs, bold and flavorful."],["C","扎染","Zārǎn","Tie-dye","Fabric tied in knots and dipped in indigo dye, so it forms blue-and-white patterns, a traditional craft of the Miao and Tujia peoples."]]},{"id":"yueyang","zh":"岳阳","py":"Yuèyáng","en":"Yueyang","lat":29.36,"lon":113.13,"note":"A lakeside city with a very famous tower.","stops":[["A","岳阳楼","Yuèyánglóu","Yueyang Tower","A tall wooden tower beside Dongting Lake, one of the Three Great Towers of southern China, praised in a famous essay by the Song statesman Fan Zhongyan.","",29.38,113.09,1],["A","洞庭湖","Dòngtínghú","Dongting Lake","One of the biggest freshwater lakes in China, with broad water, reeds and many birds, flowing into the Yangtze.","",29.3,112.9],["D","君山银针","Jūnshān yínzhēn","Junshan Silver Needle tea","A yellow tea of silvery buds, grown on Junshan island in Dongting Lake. Its leaves stand upright in the glass."],["D","洞庭湖银鱼","Dòngtínghú yínyú","Dongting silver fish","Tiny, clear fish from the lake, cooked with egg or in soup, light and tender."]]},{"id":"shaoshan","zh":"韶山","py":"Sháoshān","en":"Shaoshan","lat":27.92,"lon":112.53,"note":"The village where Mao Zedong was born.","stops":[["A","毛泽东故居","Máozédōng Gùjū","Mao Zedong's Former Residence","A farmhouse in Shaoshan, where Mao Zedong was born in 1893. It is now a museum, with a pond and fields.","",27.92,112.53],["D","红烧肉","Hóngshāoròu","Red-braised pork","Pork belly braised in soy sauce and sugar until it melts in the mouth. It is said to have been a favorite of Mao."]]},{"id":"hengyang","zh":"衡阳","py":"Héngyáng","en":"Hengyang","lat":26.89,"lon":112.57,"note":"A southern city beside one of the Five Sacred Mountains.","stops":[["A","衡山","Héngshān","Mount Heng (South)","Mount Heng in the south is one of the Five Sacred Mountains of China, with temples, old pines and mist.","",27.25,112.69],["A","南岳大庙","Nányuè Dàmiào","Nanyue Great Temple","A large temple complex at the foot of Mount Heng, the biggest on the mountain, with a mix of Taoist and Buddhist halls.","",27.25,112.7],["D","衡阳鱼粉","Héngyáng yúfěn","Hengyang fish noodles","Rice noodles in a rich fish broth with chili, a typical dish of Hengyang."]]},{"id":"xiangxi","zh":"湘西","py":"Xiāngxī","en":"Xiangxi","lat":28.31,"lon":109.74,"note":"A mountain prefecture of Tujia and Miao villages.","stops":[["A","芙蓉镇","Fúróngzhèn","Furong Town","A town in the mountains built beside a waterfall, which became famous from a film of the 1980s.","",28.99,109.87],["D","酸鱼","Suānyú","Sour fish","Fish fermented with rice and salt in jars, and eaten by Miao and Dong people, with a sour taste."],["D","腊肉","Làròu","Smoked bacon","Pork cured with salt and smoked over a fire, hung in kitchens, and cooked with vegetables and chilies."]]},{"id":"shaoyang","zh":"邵阳","py":"Shàoyáng","en":"Shaoyang","lat":27.24,"lon":111.47,"note":"A city in mid-Hunan with an old hill landscape.","stops":[]},{"id":"yongzhou","zh":"永州","py":"Yǒngzhōu","en":"Yongzhou","lat":26.42,"lon":111.61,"note":"A southern city of rivers and a famous essay.","stops":[["D","永州血鸭","Yǒngzhōu xuèyā","Yongzhou blood duck","A duck stir-fried in a pot with chili and its own blood, a spicy, rich dish of Yongzhou."]]},{"id":"changde","zh":"常德","py":"Chángdé","en":"Changde","lat":29.04,"lon":111.7,"note":"A river city with a peach-blossom legend.","stops":[["A","桃花源","Táohuāyuán","Taohuayuan","A garden in Changde said to be the inspiration for Tao Yuanming's story of a hidden paradise among peach blossoms.","",28.91,111.28],["D","常德米粉","Chángdé mǐfěn","Changde rice noodles","A bowl of rice noodles topped with beef or pork in a spicy broth, a Changde breakfast."]]}],"air":{"zh":"长沙黄花国际机场","py":"Chángshā Huánghuā Guójì Jīchǎng","en":"Changsha Huanghua International Airport","code":"CSX","lat":28.19,"lon":113.22,"note":"Hunan's main airport, east of the city. Welcome to Hunan."}},{"id":"jiangsu","zh":"江苏","py":"Jiāngsū","en":"Jiangsu","cities":[{"id":"shanghai","zh":"上海","py":"Shànghǎi","en":"Shanghai","lat":31.23,"lon":121.47,"note":"A giant port city of skyscrapers, old lanes and the Bund.","stops":[["A","外滩","Wàitān","The Bund","A riverside promenade in Shanghai. On one side stand old banks and trading houses in grand European styles, and on the other, the glittering towers of Pudong.","",31.24,121.49,1],["A","东方明珠塔","Dōngfāngmíngzhū Tǎ","Oriental Pearl Tower","A TV tower in Pudong with large pink glass spheres, which became a symbol of modern Shanghai in the 1990s.","",31.24,121.5],["A","上海中心大厦","Shànghǎi Zhōngxīn Dàshà","Shanghai Tower","At 632 meters, one of the tallest buildings in the world, twisting as it rises, with a high observation deck.","",31.23,121.51],["A","豫园","Yùyuán","Yu Garden","A Ming-dynasty garden in old Shanghai, with rockeries, ponds, a zigzag bridge and a busy bazaar around it.","",31.23,121.49],["A","南京路","Nánjīnglù","Nanjing Road","The most famous shopping street in China, with department stores, old brands and a busy walking street.","",31.24,121.48],["A","田子坊","Tiánzifāng","Tianzifang","A maze of old lanes in Shanghai turned into small shops, studios and cafés.","",31.21,121.47],["A","上海博物馆","Shànghǎi Bówùguǎn","Shanghai Museum","A museum of ancient Chinese art, with famous collections of bronzes, ceramics, calligraphy and paintings.","",31.23,121.47],["A","朱家角","Zhūjiājiǎo","Zhujiajiao","A water town with canals, stone bridges and old shops, within the Shanghai area, so it is an easy day trip.","",31.11,121.05],["A","上海迪士尼度假区","Shànghǎi Díshìní Dùjiàqū","Shanghai Disney Resort","A large theme park in Pudong, with a castle and rides, with its own Chinese touches, such as a garden of the zodiac.","",31.14,121.66],["A","静安寺","Jìng’ānsì","Jing'an Temple","A Buddhist temple more than 1,700 years old that now stands among skyscrapers and shopping malls.","",31.22,121.45],["D","小笼包","Xiǎolóngbāo","Xiaolongbao","Small steamed dumplings with thin skins and a pocket of hot, savory soup. Bite a little hole and sip the broth first.","",null,null,1],["D","生煎包","Shēngjiānbāo","Shengjian bao","Pan-fried pork buns with a crisp golden bottom and soup inside, sprinkled with sesame seeds and scallions."],["D","红烧肉","Hóngshāoròu","Shanghai red-braised pork","Shanghai's version of braised pork belly is sweet, rich and glossy with soy sauce and sugar."],["D","葱油拌面","Cōngyóu bànmiàn","Scallion-oil noodles","Simple noodles tossed with fragrant fried scallion oil and soy sauce, a beloved Shanghai comfort food."],["D","本帮菜","Běnbāngcài","Benbang cuisine","The local style of Shanghai cooking, with rich, sweet and savory dishes that use lots of soy sauce and sugar."],["D","大闸蟹","Dàzháxiè","Hairy crab","Hairy crabs, which are in season in the autumn, are steamed and eaten with ginger vinegar and rice wine, with sweet, creamy roe."],["D","糍饭团","Cí fàntuán","Sticky rice roll","A glutinous rice roll with a crisp fried dough stick inside, with pickles, a classic Shanghai breakfast."],["C","海派文化","Hǎipài wénhuà","Haipai culture","Haipai is the blend of Chinese and Western influence that shaped Shanghai's fashion, food and art."],["C","沪剧","Hùjù","Shanghai opera","An opera sung in the Shanghai dialect, telling stories of daily life in the city."],["C","旗袍","Qípáo","Qipao","The qipao is a fitted dress with a high collar and side slit that became fashionable in Shanghai in the 1930s."],["C","石库门","Shíkùmén","Shikumen houses","Lane houses with a stone-framed gate and brick walls, a style that mixes Chinese courtyard homes with Western terraces."]],"muni":"Shanghai"},{"id":"nanjing","zh":"南京","py":"Nánjīng","en":"Nanjing","lat":32.06,"lon":118.8,"note":"The capital of Jiangsu and a former capital of China many times.","stops":[["A","中山陵","Zhōngshānlíng","Sun Yat-sen Mausoleum","The tomb of Sun Yat-sen on Purple Mountain, reached by 392 steps. The blue-tiled hall stands among tall trees.","",32.06,118.85],["A","明孝陵","Míngxiàolíng","Ming Xiaoling Mausoleum","The tomb of the first Ming emperor, with a Sacred Way lined with stone animals and officials, in a forest of Purple Mountain.","",32.06,118.84],["A","夫子庙","Fūzǐmiào","Confucius Temple","A Confucius temple and the busy lantern-lit district around it along the Qinhuai River, with snack stalls, boats and old houses.","",32.02,118.79,1],["A","南京城墙","Nánjīng Chéngqiáng","Nanjing City Wall","The longest surviving city wall in the world, built in the Ming dynasty, with huge brick gates and walkways.","",32.03,118.78],["A","总统府","Zǒngtǒngfǔ","Presidential Palace","A set of old government buildings and gardens, used by the Taiping rebel leader and later by Sun Yat-sen and the Republic.","",32.05,118.8],["A","侵华日军南京大屠杀遇难同胞纪念馆","Qīnhuá Rìjūn Nánjīng Dàtúshā Yùnàn Tóngbāo Jìniànguǎn","Nanjing Massacre Memorial Hall","A memorial museum for the victims of the 1937 Nanjing Massacre, a solemn place for remembrance and peace.","",32.03,118.75],["A","南京博物院","Nánjīng Bówùyuàn","Nanjing Museum","One of the largest museums in China, with jade, bronzes and fine paintings in a big palace-style building.","",32.04,118.83],["D","盐水鸭","Yánshuǐyā","Salted duck","Nanjing's famous cold duck is cured in salt and gently simmered, so its skin is pale and the meat tender and fragrant.","",null,null,1],["D","鸭血粉丝汤","Yāxuè fěnsītāng","Duck blood vermicelli soup","Glass noodles in a hot soup with duck blood, tofu and giblets, a beloved snack in Nanjing."],["D","南京小笼包","Nánjīng xiǎolóngbāo","Nanjing soup dumplings","Small steamed dumplings from Nanjing, thin-skinned and juicy, often eaten with vinegar."],["D","秦淮小吃","Qínhuái xiǎochī","Qinhuai snacks","Small dishes sold along the Qinhuai River, such as duck oil pancakes, sweet rice balls and sesame cakes."],["C","云锦","Yúnjǐn","Yunjin brocade","Yunjin is a rich silk brocade woven with gold thread for the imperial court, and woven on huge looms by two people."],["C","秦淮灯会","Qínhuái dēnghuì","Qinhuai Lantern Festival","A lantern show along the Qinhuai River at New Year, with thousands of lights in animal and legend shapes."]]},{"id":"suzhou","zh":"苏州","py":"Sūzhōu","en":"Suzhou","lat":31.3,"lon":120.59,"note":"A classical garden city with canals and silk.","stops":[["A","拙政园","Zhuōzhèngyuán","Humble Administrator's Garden","The largest of Suzhou's classical gardens, with ponds, pavilions and winding paths, built in the Ming dynasty. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",31.32,120.63,1],["A","留园","Liúyuán","Lingering Garden","A garden of the Ming and Qing periods, with rockeries, halls and long covered walkways, and fine windows.","",31.32,120.59],["A","虎丘","Hǔqiū","Tiger Hill","A hill with a leaning pagoda about a thousand years old, a symbol of Suzhou.","",31.34,120.57],["A","平江路","Píngjiāng Lù","Pingjiang Road","A quiet lane beside a canal with old homes, teahouses and small shops, and a taste of old Suzhou.","",31.32,120.63],["A","周庄","Zhōuzhuāng","Zhouzhuang","A famous water town, with canals, arched stone bridges and old wooden houses, often called the first water town of China.","",31.12,120.85],["A","同里古镇","Tónglǐ Gǔzhèn","Tongli Ancient Town","A quieter canal town, with three bridges that locals once crossed on a wedding day for luck, and old merchant mansions.","",31.16,120.72],["A","寒山寺","Hánshānsì","Hanshan Temple","A temple made famous by a Tang poem about a traveler hearing its bell at night while moored by a bridge.","",31.31,120.57],["D","松鼠鳜鱼","Sōngshǔ guìyú","Squirrel-shaped mandarin fish","A mandarin fish scored and fried so it curls like a squirrel's tail, covered in a sweet and sour sauce."],["D","苏式面","Sūshì miàn","Suzhou noodles","Suzhou noodles are served in a clear, sweet broth, with toppings such as braised pork or shrimp."],["D","糖粥","Tángzhōu","Sugar congee","A sweet sticky rice porridge with brown sugar, sold by street vendors early in the morning."],["D","阳澄湖大闸蟹","Yángchénghú dàzháxiè","Yangcheng Lake hairy crab","The most famous brand of lake crab, from Yangcheng Lake near Suzhou, prized for sweet, rich meat."],["C","苏绣","Sūxiù","Suzhou embroidery","Suzhou embroidery is very fine, with silk threads split thinner than hair, and can show a different picture on each side."],["C","昆曲","Kūnqǔ","Kunqu opera","Kunqu is one of the oldest forms of Chinese opera, with slow, graceful singing and movements. It is a UNESCO-listed heritage."],["C","评弹","Píngtán","Pingtan storytelling","Pingtan is a Suzhou storytelling art, with a performer or two telling tales in song, accompanied by a lute and pipa."]]},{"id":"wuxi","zh":"无锡","py":"Wúxī","en":"Wuxi","lat":31.49,"lon":120.31,"note":"A city on Lake Tai.","stops":[["A","灵山大佛","Língshān Dàfú","Lingshan Grand Buddha","A giant standing bronze Buddha 88 meters tall that looks out over Lake Tai, next to a large temple.","",31.43,120.1],["A","无锡古运河","Wúxī Gǔyùnhé","Wuxi Ancient Canal","A stretch of the Grand Canal with old streets, bridges and boats, where Wuxi's history can be explored.","",31.57,120.3],["D","无锡排骨","Wúxī páigǔ","Wuxi spare ribs","Pork ribs braised in a sweet soy sauce until the meat comes off the bone, a Wuxi classic."],["D","小笼馒头","Xiǎolóng mántou","Wuxi small buns","Wuxi's soup buns are sweeter than those in other regions, with a thin skin and juicy filling."],["D","惠山泥人","Huìshān nírén","Huishan clay figures","Hand-made clay figures from Huishan, painted in bright colors, a folk craft with a long history, such as chubby children and opera characters."]]},{"id":"yangzhou","zh":"扬州","py":"Yángzhōu","en":"Yangzhou","lat":32.39,"lon":119.41,"note":"A canal and salt-merchant city of poets and gardens.","stops":[["A","瘦西湖","Shòuxīhú","Slender West Lake","A narrow, winding lake in Yangzhou with a white pagoda, arched bridges and willows, said to be as graceful as a slender lady.","",32.41,119.42,1],["A","个园","Gèyuán","Ge Garden","A garden famous for its four rockeries, which stand for the four seasons, among bamboo.","",32.39,119.43],["D","扬州炒饭","Yángzhōu chǎofàn","Yangzhou fried rice","The original egg-and-ham fried rice, with shrimp and peas, known all over the world. The grains are separate and fluffy.","",null,null,1],["D","狮子头","Shīzitóu","Lion's head meatball","Big, soft pork meatballs that are simmered in broth with vegetables, said to look like a lion's head with its mane."],["D","三丁包","Sāndīngbāo","Sanding buns","Steamed buns filled with chicken, pork and bamboo shoots, a classic of Yangzhou's tea houses."],["D","淮扬菜","Huáiyángcài","Huaiyang cuisine","One of the four great regional cuisines of China, known for fine knife skills, light flavors and fresh ingredients."],["C","扬州评话","Yángzhōu pínghuà","Yangzhou storytelling","A storytelling tradition in which a single performer tells long stories with a fan and a gavel."]]},{"id":"zhenjiang","zh":"镇江","py":"Zhènjiāng","en":"Zhenjiang","lat":32.19,"lon":119.45,"note":"A Yangtze port known for its black vinegar.","stops":[["A","金山寺","Jīnshānsì","Jinshan Temple","A temple on a hill beside the Yangtze in Zhenjiang, and the setting of the legend of the White Snake.","",32.22,119.4],["D","镇江香醋","Zhènjiāng xiāngcù","Zhenjiang vinegar","A dark, mellow rice vinegar, aged for months, one of the best-known vinegars in China."],["D","锅盖面","Guōgài miàn","Pot-lid noodles","Noodles cooked under a wooden pot lid, with a firm, springy texture, a Zhenjiang specialty."],["D","肴肉","Yáoròu","Yaorou aspic pork","Pork pressed and cured and set in clear jelly, eaten cold with ginger and Zhenjiang vinegar."]]},{"id":"changzhou","zh":"常州","py":"Chángzhōu","en":"Changzhou","lat":31.81,"lon":119.97,"note":"A canal city with a dinosaur park.","stops":[["D","常州萝卜干","Chángzhōu luóbogàn","Changzhou dried radish","Strips of radish salted and dried in the sun, a crunchy pickled side dish."],["D","常州梳篦","Chángzhōu shūbì","Changzhou combs","Handmade wooden combs, a Changzhou craft that was a gift to the imperial court."]]},{"id":"nantong","zh":"南通","py":"Nántōng","en":"Nantong","lat":32.01,"lon":120.86,"note":"A river-mouth city of textiles and a pioneering industrialist.","stops":[["D","南通蓝印花布","Nántōng lán yìnhuābù","Nantong blue calico","Blue-and-white cloth printed with patterns using a resist paste, a Nantong folk craft."],["D","南通海鲜","Nántōng hǎixiān","Nantong seafood","Fresh fish, crabs and shellfish from the Yellow Sea, cooked simply in Nantong's seafood restaurants."]]},{"id":"xuzhou","zh":"徐州","py":"Xúzhōu","en":"Xuzhou","lat":34.26,"lon":117.18,"note":"A northern city with Han-dynasty tombs.","stops":[["D","徐州地锅鸡","Xúzhōu dìguō jī","Xuzhou earthen-pot chicken","Chicken braised in an iron pot over a fire with a flatbread stuck to the side of the pot to soak up the sauce."],["D","把子肉","Bǎzi ròu","Bazi meat","Braised pork served with rice, a local favorite in the Xuzhou area, cooked slowly in soy sauce."]]},{"id":"lianyungang","zh":"连云港","py":"Liányúngǎng","en":"Lianyungang","lat":34.6,"lon":119.22,"note":"A seaside city with the Monkey King's mountain.","stops":[["A","花果山","Huāguǒshān","Flower Fruit Mountain","A mountain said to be the home of the Monkey King in Journey to the West, with caves and waterfalls.","",34.65,119.3],["D","紫菜","Zǐcài","Laver","Laver seaweed from the coast of Lianyungang, dried into sheets and used in soups and snacks."],["D","海州海鲜","Hǎizhōu hǎixiān","Haizhou seafood","Seafood from the Yellow Sea, served fresh in the port city of Lianyungang."]]},{"id":"yancheng","zh":"盐城","py":"Yánchéng","en":"Yancheng","lat":33.35,"lon":120.16,"note":"A coastal city of wetlands and migrating birds.","stops":[["D","盐城河虾","Yánchéng héxiā","Yancheng river shrimp","Fresh small river shrimp, boiled or stir-fried quickly, with a clean sweet taste."]]},{"id":"huaian","zh":"淮安","py":"Huái’ān","en":"Huai'an","lat":33.61,"lon":119.02,"note":"The hometown of Premier Zhou Enlai.","stops":[["D","淮安软兜长鱼","Huái’ān ruǎndōu chángyú","Huai'an soft-pocket eel","A famous Huai'an dish of eel, cooked until it is soft and tender, and served in a savory sauce."],["D","淮安茶馓","Huái’ān chásǎn","Huai'an fried twists","Thin crisp fried dough twists, eaten with tea as a snack in Huai'an."]]},{"id":"suqian","zh":"宿迁","py":"Sùqiān","en":"Suqian","lat":33.96,"lon":118.28,"note":"A city beside Hongze and Luoma Lakes.","stops":[["D","洋河大曲","Yánghé dàqū","Yanghe liquor","A well-known baijiu from Yanghe in Suqian, with a mellow, sweet taste."]]},{"id":"taizhou-js","zh":"泰州","py":"Tàizhōu","en":"Taizhou","lat":32.46,"lon":119.92,"note":"A water city in central Jiangsu.","stops":[["D","泰州早茶","Tàizhōu zǎochá","Taizhou morning tea","A long, slow morning meal of small buns and dim sum with pots of tea, a Jiangnan custom."]]}],"munis":{"Shanghai":"Shanghai is a municipality in its own right, directly under the national government, not part of Jiangsu. It sits at the mouth of the Yangtze next to Jiangsu, so it is visited here."},"air":{"zh":"上海浦东国际机场","py":"Shànghǎipǔdōng Guójìjīchǎng","en":"Shanghai Pudong International Airport","code":"PVG","lat":31.14,"lon":121.81,"note":"Shanghai's main international gateway, on the coast. Welcome to Jiangsu."}},{"id":"jiangxi","zh":"江西","py":"Jiāngxī","en":"Jiangxi","cities":[{"id":"nanchang","zh":"南昌","py":"Nánchāng","en":"Nanchang","lat":28.68,"lon":115.86,"note":"The capital of Jiangxi, on the Gan River.","stops":[["A","滕王阁","Téngwánggé","Tengwang Pavilion","A tall tower on the Gan River in Nanchang, one of the Three Great Towers of southern China, made famous by a Tang poem that every schoolchild learns.","One of the Three Great Towers south of the Yangtze.",28.68,115.87,1],["A","八一起义纪念馆","Bāyīqǐyì Jìniànguǎn","August 1st Uprising Museum","A museum in the former building where, on August 1, 1927, an armed uprising took place in Nanchang, marking the founding of the Red Army.","",28.68,115.89],["A","绳金塔","Shéng Jīntǎ","Shengjin Pagoda","An old pagoda in the middle of Nanchang, built to protect the city from fire. It stands among streets of snack stalls.","",28.66,115.89],["A","八大山人纪念馆","Bādàshānrén Jìniànguǎn","Bada Shanren Museum","A museum for the painter Bada Shanren, or Zhu Da, a Ming prince who became a monk and painted lonely birds and fish.","",28.6,115.9],["A","万寿宫","Wànshòugōng","Wanshou Palace","A Taoist temple tied to the worship of Xu Xun, a local hero said to have tamed floods. Jiangxi people took the cult across China.","",28.67,115.87],["D","南昌拌粉","Nánchāng bànfěn","Nanchang mixed rice noodles","Rice noodles tossed with chili, soy sauce and pickles, and served with a bowl of clear soup. A breakfast classic in Nanchang."],["D","瓦罐汤","Wǎguàn tāng","Clay pot soup","Soup simmered for hours in clay jars over charcoal, with chicken, ribs or other ingredients, a Nanchang comfort food."],["D","藜蒿炒腊肉","Líhāochǎo làròu","Wormwood with bacon","A stir-fry of crisp wormwood stems from the lake shore with smoked pork, a seasonal Jiangxi favorite."],["D","鄱阳湖银鱼","Póyánghú yínyú","Poyang silverfish","Tiny, transparent fish from Poyang Lake, cooked with egg or in soup, light and tender."],["D","南昌炒粉","Nánchāng chǎofěn","Nanchang fried noodles","Rice noodles stir-fried with egg, vegetables and chili, a quick and filling Nanchang favorite."],["C","采茶戏","Cǎicháxì","Tea-picking opera","A folk theater that grew from the songs of tea pickers, with lively humor and acting, popular in Jiangxi's villages."],["C","傩舞","Nuówǔ","Nuo dance","A masked ritual dance performed to drive away evil spirits, with colorful wooden masks, and a very old tradition in Jiangxi."]]},{"id":"jingdezhen","zh":"景德镇","py":"Jǐngdézhèn","en":"Jingdezhen","lat":29.27,"lon":117.18,"note":"The porcelain capital of China for a thousand years.","stops":[["A","景德镇御窑厂","Jǐngdézhèn Yù Yáochǎng","Jingdezhen Imperial Kiln","The site of the imperial kilns where porcelain was made for the Ming and Qing courts, with ruins and a museum.","",29.27,117.19],["A","古窑民俗博览区","Gǔyáo Mínsú Bólǎn Qū","Ancient Kiln Folk Museum","A park of old kilns and workshops where visitors can watch potters throw, paint and fire porcelain by hand.","",29.3,117.2],["A","陶溪川","Táoxīchuān","Taoxichuan","A former porcelain factory area converted into studios, galleries, cafés and a market for young artists.","",29.27,117.21],["A","中国陶瓷博物馆","Zhōngguó Táocí Bówùguǎn","China Ceramics Museum","A museum that follows Chinese ceramics from early pottery through to the high point of Jingdezhen porcelain.","",29.29,117.2],["D","瓷器","Cíqì","Jingdezhen porcelain","Jingdezhen has made fine white porcelain for over a thousand years, known as the porcelain capital of the world."],["D","景德镇冷粉","Jǐngdézhèn lěngfěn","Jingdezhen cold noodles","Cold rice noodles with a spicy sauce, a refreshing local snack in the hot summer."],["D","鱼饼","Yúbǐng","Fish cake","A pan-fried fish cake made from minced fish, with a springy bite, served as a snack or in soup."],["C","青花瓷","Qīnghuācí","Blue and white porcelain","Blue and white porcelain is painted by hand with cobalt blue under the glaze. Jingdezhen's pieces were prized from Persia to Europe.","",null,null,1],["C","粉彩","Fěncǎi","Fencai enamel","Fencai is a porcelain style that uses soft, painted enamels, with delicate pinks and greens, and was loved at the Qing court."]]},{"id":"jiujiang","zh":"九江","py":"Jiǔjiāng","en":"Jiujiang","lat":29.71,"lon":116.0,"note":"A river and lake port with Mount Lu.","stops":[["A","庐山","Lúshān","Mount Lu","A misty mountain of waterfalls, peaks and old villas, a retreat for poets, scholars and officials for centuries. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",29.56,115.98,1],["A","庐山瀑布","Lúshān Pùbù","Lushan Waterfall","A tall waterfall that the Tang poet Li Bai compared to the Milky Way falling from heaven.","",29.57,116.0],["A","白鹿洞书院","Báilùdòng Shūyuàn","White Deer Grotto Academy","One of the four great academies of ancient China, at the foot of Mount Lu, where Zhu Xi taught in the 12th century.","",29.65,116.04],["A","鄱阳湖","Póyánghú","Poyang Lake","China's largest freshwater lake, which shrinks and grows with the seasons. In winter, many cranes and other migratory birds gather here.","",29.1,116.3],["A","东林寺","Dōnglínsì","Donglin Temple","A temple at the foot of Mount Lu, regarded as the birthplace of the Pure Land school of Buddhism.","",29.58,115.9],["D","庐山石鸡","Lúshān shíjī","Lushan stone frog","A kind of mountain frog found in the streams of Lushan, cooked in a savory dish, a local delicacy."],["D","鄱阳湖大闸蟹","Póyánghú dàzháxiè","Poyang crab","Crabs from Poyang Lake are in season in the autumn, steamed and eaten with ginger and vinegar."],["C","陶渊明","Táoyuānmíng","Tao Yuanming","The poet Tao Yuanming gave up an official post to live in the countryside in Jiangxi, and his poems on fields and chrysanthemums are still loved."]]},{"id":"ganzhou","zh":"赣州","py":"Gànzhōu","en":"Ganzhou","lat":25.83,"lon":114.93,"note":"A southern city of Hakka culture and Song-era walls.","stops":[["A","赣州古城墙","Gànzhōu Gǔchéngqiáng","Ganzhou City Wall","A wall dating from the Song dynasty, surrounding old Ganzhou, among the oldest city walls in China that is still standing.","",25.85,114.93],["A","通天岩","Tōngtiān Yán","Tongtianyan","A group of red sandstone cliffs and caves with Buddhist statues carved in the Tang and Song dynasties.","",25.77,114.88],["D","赣南脐橙","Gànnán qíchéng","Gannan navel oranges","Sweet navel oranges from southern Jiangxi, famed across China, and harvested in winter."],["D","赣州小炒鱼","Gànzhōu xiǎochǎo yú","Ganzhou fried fish","A fiery stir-fry of freshwater fish with chili, garlic and herbs, a staple of southern Jiangxi."],["D","客家酿豆腐","Kèjiā niàng dòufǔ","Hakka stuffed tofu","Tofu stuffed with minced pork and simmered, a Hakka comfort dish in southern Jiangxi."]]},{"id":"shangrao","zh":"上饶","py":"Shàngráo","en":"Shangrao","lat":28.45,"lon":117.94,"note":"A northeast city with Mount Sanqing.","stops":[["A","三清山","Sānqīngshān","Mount Sanqing","A mountain of strange granite pillars and peaks that look like people and animals, wrapped in mist. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",28.91,118.06,1],["A","婺源","Wùyuán","Wuyuan","A county of villages with white walls and black roofs, among tea fields and fields of golden rapeseed flowers in spring, called the most beautiful countryside in China.","",29.25,117.86,1],["A","龙虎山","Lónghǔshān","Dragon-Tiger Mountain","The home of the Celestial Masters of Taoism, a landscape of red cliffs and a clear river, with cliff tombs.","",28.1,117.02],["D","婺源糕点","Wùyuán gāodiǎn","Wuyuan cakes","Sweet pastries and rice cakes made in Wuyuan's villages, a snack for tourists and a gift."],["D","弋阳年糕","Yìyáng niángāo","Yiyang rice cake","A chewy rice cake made in Yiyang, eaten with sauce or fried, a New Year tradition."],["D","婺源绿茶","Wùyuán lǜchá","Wuyuan green tea","A fragrant green tea from the misty hills of Wuyuan, with a fresh and lasting taste."]]},{"id":"yichun","zh":"宜春","py":"Yíchūn","en":"Yichun","lat":27.81,"lon":114.42,"note":"A green city with a hot spring and Mount Mingyue.","stops":[["D","宜春富硒米","Yíchūn fùxīmǐ","Yichun selenium rice","Rice grown in selenium-rich soil near Yichun, marketed as a healthy and flavorful rice."],["D","宜春富硒茶","Yíchūn fùxīchá","Yichun selenium tea","A tea grown in the selenium-rich soil of Yichun, with a gentle flavor."]]},{"id":"jian","zh":"吉安","py":"Jí’ān","en":"Ji'an","lat":27.11,"lon":114.99,"note":"A revolutionary mountain city.","stops":[["A","井冈山","Jǐnggāngshān","Jinggangshan","A forested mountain range where Mao Zedong and Zhu De set up the first rural base of the Chinese Communist revolution in 1927.","",26.58,114.17],["A","白鹭洲书院","Báilùzhōu Shūyuàn","Bailuzhou Academy","An old academy on an island in the Gan River, founded in the Song dynasty, which produced many officials.","",27.11,114.99],["A","青原山","Qīngyuán Shān","Qingyuan Mountain","A mountain in Ji'an with an old temple, where a major school of Chan Buddhism developed.","",27.05,115.07],["D","井冈山红米饭","Jǐnggāngshān hóng mǐfàn","Red rice and pumpkin soup","A simple meal of red rice and pumpkin soup that recalls the plain food of the Red Army in the 1920s."]]},{"id":"fuzhou-jx","zh":"抚州","py":"Fǔzhōu","en":"Fuzhou","lat":27.95,"lon":116.36,"note":"A city of Tang Xianzu, a great playwright.","stops":[["D","抚州建昌帮","Fǔzhōu jiànchāng bāng","Jianchang pharmacy","Jianchang is a school of traditional herbal medicine, known for its way of preparing herbs."],["D","南丰蜜桔","Nánfēng mìjú","Nanfeng mandarin","A tiny, sweet mandarin grown in Nanfeng for over a thousand years and once sent as a tribute to the emperor."]]},{"id":"yingtan","zh":"鹰潭","py":"Yīngtán","en":"Yingtan","lat":28.24,"lon":117.03,"note":"The home of Taoist Celestial Masters.","stops":[["A","天师府","Tiānshī Fǔ","Celestial Master's Mansion","The home of the Taoist Celestial Masters for about 60 generations, in Yingtan, the center of the Zhengyi school.","",28.11,117.0],["D","龙虎山茶","Lónghǔshān chá","Dragon-Tiger tea","A tea grown on the slopes of Dragon-Tiger Mountain, with a fresh, floral aroma."]]},{"id":"pingxiang","zh":"萍乡","py":"Píngxiāng","en":"Pingxiang","lat":27.62,"lon":113.85,"note":"A coal city near Wugong Mountain.","stops":[["A","武功山","Wǔgōngshān","Wugong Mountain","A mountain with a high alpine meadow, where visitors camp to watch the sun rise above a sea of clouds.","",27.47,114.18],["D","萍乡炒粉","Píngxiāng chǎofěn","Pingxiang fried rice noodles","Pingxiang's fried rice noodles are chewy and spicy, stir-fried with pork, and are the signature dish of the town."]]},{"id":"xinyu","zh":"新余","py":"Xīnyú","en":"Xinyu","lat":27.82,"lon":114.92,"note":"A city of lakes and solar panels.","stops":[["D","新余蜜橘","Xīnyú mìjú","Xinyu tangerines","Sweet, juicy tangerines that Xinyu has grown for a long time, picked in late autumn."]]}],"air":{"zh":"南昌昌北国际机场","py":"Nánchāng Chāngběi Guójì Jīchǎng","en":"Nanchang Changbei International Airport","code":"KHN","lat":28.86,"lon":115.9,"note":"The main airport of Jiangxi, north of Nanchang. Welcome to Jiangxi."}},{"id":"jilin","zh":"吉林","py":"Jílín","en":"Jilin","cities":[{"id":"changchun","zh":"长春","py":"Chángchūn","en":"Changchun","lat":43.82,"lon":125.32,"note":"The capital of Jilin, a car and film city.","stops":[["A","伪满皇宫博物院","Wěimǎn Huánggōng Bówùyuàn","Puppet Emperor's Palace","The former palace of Puyi, the last Qing emperor, who lived here as the ruler of the Japanese-controlled state of Manchukuo. It is now a museum.","",43.9,125.34],["A","长影旧址博物馆","Chángyǐng Jiùzhǐ Bówùguǎn","Changchun Film Studio Museum","A museum in the old Changchun Film Studio, China's first state film studio, with sets and equipment of old movies.","",43.88,125.36],["A","净月潭","Jìngyuètán","Jingyuetan","A forested lake park outside Changchun, with pine woods, trails and a lake, popular for winter sports.","",43.78,125.45],["A","吉林省博物院","Jílínshěng Bówùyuàn","Jilin Provincial Museum","A museum of Jilin's history and culture, with relics of the northeast, such as dinosaur fossils and local peoples' crafts.","",43.88,125.33],["D","锅包肉","Guōbāoròu","Guobaorou","Slices of pork fried until crisp and coated in a sweet and sour glaze, a favorite dish of the northeast."],["D","酸菜白肉","Suāncài báiròu","Sauerkraut and white pork","A winter stew of pickled cabbage and pork slices, simmered until tender, warming and tangy."],["D","烤冷面","Kǎo lěngmiàn","Grilled cold noodles","A street snack of cold noodle sheets grilled on a hot plate with egg, sauce and sausage, popular with students."],["D","冻梨","Dònglí","Frozen pear","A pear frozen outside in the winter, which thaws into a cold and juicy, sweet treat."],["D","杀猪菜","Shāzhū cài","Pig slaughter stew","A winter feast stew of pork, blood sausage and pickled cabbage, traditionally enjoyed by families when a pig is butchered."],["D","打糕","Dǎgāo","Rice cake","A Korean rice cake that is pounded with a wooden mallet until soft and chewy, then coated with bean powder."],["C","二人转","Èrrénzhuàn","Errenzhuan","A comic song-and-dance duet from the northeast, with quick wit, bright costumes and a lot of humor."],["C","东北大秧歌","Dōngběi dàyānggē","Northeast yangge","A folk dance of the northeast, danced in groups with handkerchiefs and fans, popular at New Year."]]},{"id":"jilin-city","zh":"吉林市","py":"Jílín Shì","en":"Jilin City","lat":43.84,"lon":126.55,"note":"A river city famous for rime ice.","stops":[["A","雾凇岛","Wùsōng Dǎo","Rime Island","An island in the Songhua River where, on cold winter mornings, frost covers every branch of the trees and turns the island into a white fairyland.","",44.0,126.65,1],["A","松花湖","Sōnghuāhú","Songhua Lake","A large lake made by a dam on the Songhua River, a green summer resort, and an icy playground in winter.","",43.6,126.78],["A","北大湖滑雪场","Běidà Hú Huáxuěchǎng","Beidahu Ski Resort","A large ski resort in the mountains near Jilin, with long runs and a heavy snowfall, used for national and international competitions.","",43.5,126.6],["A","龙潭山","Lóngtánshān","Longtan Mountain","A hill park in Jilin City with the ruins of an ancient fort of the Goguryeo kingdom.","",43.87,126.58],["D","大锅炖鱼","Dàguō dùnyú","Pot-stewed fish","A big stew pot of fish simmered with vegetables and soy sauce, with flatbreads stuck on the edge of the pot."],["C","雾凇","Wùsōng","Rime ice","Rime ice is frost that coats trees in winter, and it is one of the four great natural sights of China."]]},{"id":"yanbian","zh":"延边","py":"Yánbiān","en":"Yanbian","lat":42.89,"lon":129.51,"note":"A Korean autonomous prefecture on the border.","stops":[["A","长白山","Chángbáishān","Changbai Mountain","A volcano on the border with North Korea, with forests that change with the altitude, hot springs and a huge crater lake.","",42.0,128.06],["A","长白山天池","Chángbáishān Tiānchí","Heaven Lake","Heaven Lake fills the crater at the top of Changbai Mountain, a deep blue lake ringed by peaks, which is frozen for most of the year.","",42.01,128.06,1],["A","长白山瀑布","Chángbáishān Pùbù","Changbai Waterfall","A tall waterfall that drops from the lake, known as the source of the Songhua River, and steam rises from the hot springs below.","",42.02,128.07],["A","图们江","Túmenjiāng","Tumen River","A river that forms part of the border between China, North Korea and Russia, and flows into the Sea of Japan.","",42.96,129.84],["A","敦化六鼎山","Dūnhuà Liùdǐngshān","Liuding Mountain","A hill with a Buddhist temple, a huge Buddha statue and the tombs of the rulers of the Bohai kingdom.","",43.37,128.2],["D","冷面","Lěngmiàn","Korean cold noodles","Chewy buckwheat noodles in an icy, sweet and sour broth, topped with beef, egg, pear and kimchi. It is the pride of the Korean community in Yanbian.","",null,null,1],["D","烤肉","Kǎoròu","Korean barbecue","Korean-style barbecue, with meat grilled at the table and wrapped in lettuce leaves with garlic and sauce."],["D","石锅拌饭","Shíguō bànfàn","Bibimbap","Rice, vegetables, egg and chili paste served in a hot stone bowl, where the rice at the bottom turns crisp."],["D","辣白菜","Làbáicài","Kimchi","Spicy fermented cabbage, or kimchi, made with chili, garlic and ginger, a staple on every Korean table."]]},{"id":"siping","zh":"四平","py":"Sìpíng","en":"Siping","lat":43.17,"lon":124.35,"note":"A city on a rail line, site of battles.","stops":[["A","四平战役纪念馆","Sìpíng Zhànyì Jìniànguǎn","Siping Campaign Memorial","A museum of the battles of Siping in 1946, which were a major episode of the Chinese Civil War.","",43.17,124.35],["D","四平烧烤","Sìpíng shāokǎo","Siping barbecue","Grilled meat skewers and other barbecue on the streets of Siping, a lively evening tradition."]]},{"id":"songyuan","zh":"松原","py":"Sōngyuán","en":"Songyuan","lat":45.14,"lon":124.82,"note":"A city of lakes and oil.","stops":[["A","查干湖","Chágànhú","Chagan Lake","A big lake, where every winter fishermen cut holes in the ice and pull huge nets through, in a traditional winter fishing festival.","",45.2,124.2],["D","查干湖鱼","Chágàn Hú yú","Chagan Lake fish","Fish from the lake, caught in the winter fishing festival and cooked fresh in stews."]]},{"id":"tonghua","zh":"通化","py":"Tōnghuà","en":"Tonghua","lat":41.73,"lon":125.94,"note":"A mountain city known for wine and herbs.","stops":[["A","好太王碑","Hǎotài Wángbēi","Gwanggaeto Stele","A huge stone stele from the fifth century CE, with thousands of carved characters about the Goguryeo kingdom and its king.","",41.13,126.19],["D","通化人参","Tōnghuà rénshēn","Tonghua ginseng","Ginseng grown in the forests of the Tonghua hills, used in tonic soups and in traditional medicine."],["D","通化山葡萄酒","Tōnghuà shān pútáojiǔ","Mountain grape wine","A sweet wine from wild mountain grapes, produced in Tonghua, one of the first wine regions of China."]]},{"id":"baicheng","zh":"白城","py":"Báichéng","en":"Baicheng","lat":45.62,"lon":122.84,"note":"A western city of grasslands.","stops":[]},{"id":"liaoyuan","zh":"辽源","py":"Liáoyuán","en":"Liaoyuan","lat":42.89,"lon":125.14,"note":"A small coal city.","stops":[]},{"id":"baishan","zh":"白山","py":"Báishān","en":"Baishan","lat":41.94,"lon":126.42,"note":"A forest city at the foot of Changbai.","stops":[["A","鸭绿江","Yālùjiāng","Yalu River","A border river between China and North Korea that flows to the Yellow Sea, with bridges that connect the two countries.","",41.6,126.5],["D","长白山人参","Chángbáishān rénshēn","Changbai ginseng","Ginseng from Changbai Mountain has been valued for centuries as a restorative herb, and is grown in the forest under shade."],["D","林蛙","Línwā","Forest frog","The forest frog of the northeast is a regional delicacy, cooked in soups and stews, and is also used in tonics."]]}],"air":{"zh":"长春龙嘉国际机场","py":"Chángchūn Lóngjiā Guójì Jīchǎng","en":"Changchun Longjia International Airport","code":"CGQ","lat":43.99,"lon":125.68,"note":"The main airport of Jilin. Welcome to Jilin."}},{"id":"liaoning","zh":"辽宁","py":"Liáoníng","en":"Liaoning","cities":[{"id":"shenyang","zh":"沈阳","py":"Shěnyáng","en":"Shenyang","lat":41.8,"lon":123.43,"note":"The capital of Liaoning and a Qing-era capital.","stops":[["A","沈阳故宫","Shěnyáng Gùgōng","Shenyang Imperial Palace","The early palace of the Qing emperors before they moved to Beijing, with a mix of Manchu, Han and Mongol styles, and it is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",41.8,123.45,1],["A","张氏帅府","Zhāngshì Shuàifǔ","Marshal Zhang's Mansion","The mansion of the warlord Zhang Zuolin and his son Zhang Xueliang, a grand compound with Chinese and Western buildings.","",41.8,123.46],["A","北陵公园","Běilíng Gōngyuán","Beiling Park","A large park with the tomb of Hong Taiji, the second Qing emperor, among old pines and a lake.","",41.84,123.42],["A","中街","Zhōngjiē","Zhongjie Street","The oldest pedestrian shopping street in China, with old shops, department stores, and snack stalls in Shenyang.","",41.8,123.46],["A","东陵","Dōnglíng","Fuling Tomb","Fuling is the tomb of Nurhaci, the founder of the Qing, in a forested park on a hill outside Shenyang.","",41.85,123.58],["A","辽宁省博物馆","Liáoníngshěng Bówùguǎn","Liaoning Provincial Museum","A museum with famous scrolls and paintings, as well as the treasures of the Liao dynasty and local archaeology.","",41.77,123.43],["D","老边饺子","Lǎobiān jiǎozi","Laobian dumplings","A dumpling house with a history of nearly 200 years in Shenyang, known for its dumplings, which are fried first and then steamed.","",null,null,1],["D","锅包肉","Guōbāoròu","Guobaorou","Crispy slices of pork coated in a sweet and sour sauce, a signature dish of the northeast."],["D","酸菜炖粉条","Suāncài dùn fěntiáo","Sauerkraut and glass noodles","A winter stew of sauerkraut, glass noodles and pork, hot and tangy and a cold-weather comfort dish."],["D","沈阳烤串","Shěnyáng kǎochuàn","Shenyang skewers","Skewers of lamb, beef and vegetables grilled over charcoal, a Shenyang summer night staple."],["D","马家烧麦","Mǎjiā shāomài","Majia shaomai","A halal shaomai, with a thin wrapper and juicy beef or lamb filling, a Shenyang specialty for over a century."],["D","鸡架","Jījià","Roasted chicken frames","Roasted chicken frames are a street snack of Shenyang, crisp outside, and eaten with beer."],["C","二人转","Èrrénzhuàn","Errenzhuan","A comic song-and-dance duet from the northeast, with humor, bright costumes and a lot of improvisation."],["C","评剧","Píngjù","Pingju opera","An opera that began in northern China in the early 20th century, with simple, accessible tunes and stories of ordinary life."],["C","秧歌","Yānggē","Northeast yangge","A folk dance of the northeast, performed in groups in bright costumes with fans and handkerchiefs."]]},{"id":"dalian","zh":"大连","py":"Dàlián","en":"Dalian","lat":38.91,"lon":121.61,"note":"A seaside port city.","stops":[["A","星海广场","Xīnghǎi Guǎngchǎng","Xinghai Square","One of the largest city squares in the world, by the sea in Dalian, with a huge compass pattern in the paving.","",38.88,121.58],["A","老虎滩海洋公园","Lǎohǔtān Hǎiyáng Gōngyuán","Tiger Beach Ocean Park","A seaside park with aquariums, polar animals and a cable car, on the coast of Dalian.","",38.87,121.68],["A","金石滩","Jīnshítān","Golden Pebble Beach","A long coastline of strange rocks, cliffs and beaches shaped by the sea, near Dalian.","",39.09,121.98],["A","旅顺口","Lǚshùnkǒu","Lüshun","A historic naval port at the tip of the Liaodong Peninsula, with old forts and a role in the wars of the early 20th century.","",38.81,121.26],["A","大连港","Dàliángǎng","Dalian Port","A major port on the Yellow Sea, one of the busiest in northern China.","",38.93,121.65],["A","滨海路","Bīnhǎi Lù","Binhai Road","A scenic road along the coast of Dalian, with sea views, cliffs and parks.","",38.87,121.58],["D","大连海鲜","Dàlián hǎixiān","Dalian seafood","Dalian's restaurants serve sea cucumber, scallops, prawns and abalone fresh from the Yellow Sea, with simple steaming or stir-frying.","",null,null,1],["D","焖子","Mènzi","Menzi","A jelly made from sweet potato starch, fried and served with garlic sauce. It is a classic Dalian snack."],["D","海鲜饺子","Hǎixiān jiǎozi","Seafood dumplings","Dumplings with a filling of shrimp, fish and vegetables, a popular choice in Dalian."],["D","大连烧烤","Dàlián shāokǎo","Dalian barbecue","Seafood and meat grilled over charcoal on Dalian's streets, with a strong taste of the sea."]]},{"id":"anshan","zh":"鞍山","py":"Ānshān","en":"Anshan","lat":41.11,"lon":122.99,"note":"A steel city with a big jade Buddha.","stops":[["A","玉佛苑","Yùfó Yuàn","Jade Buddha Garden","A garden with a huge Buddha carved from a single piece of jade from nearby Xiuyan.","",41.0,123.1],["A","千山","Qiānshān","Qianshan Mountain","A mountain of granite peaks, temples and Buddhist monasteries, known as the Pearl of the Northeast.","",41.05,123.12],["D","海城馅饼","Hǎichéng xiànbǐng","Haicheng pies","Round pies, pan-fried until golden, with a juicy meat filling, from Haicheng."],["D","岫岩玉","Xiùyán yù","Xiuyan jade","A green jade from Xiuyan, carved into pendants, bowls and Buddha statues."]]},{"id":"fushun","zh":"抚顺","py":"Fǔshùn","en":"Fushun","lat":41.88,"lon":123.96,"note":"A coal town and a Manchu homeland.","stops":[["A","雷锋纪念馆","Léifēng Jìniànguǎn","Lei Feng Memorial","A memorial museum to Lei Feng, a soldier who became a symbol of selfless service, with displays of his life and diary.","",41.88,123.96],["D","抚顺煤精雕刻","Fǔshùn méijīng diāokè","Fushun coal carving","A craft that carves a shiny black stone, coal amber, into small animals and ornaments."]]},{"id":"dandong","zh":"丹东","py":"Dāndōng","en":"Dandong","lat":40.12,"lon":124.35,"note":"A border city beside North Korea.","stops":[["A","鸭绿江断桥","Yālùjiāng Duànqiáo","Yalu River Broken Bridge","A bridge across the Yalu River that was bombed during the Korean War, half of it still stands.","",40.12,124.39],["A","虎山长城","Hǔshān Chángchéng","Hushan Great Wall","The eastern end of the Ming Great Wall, which climbs a hill beside the Yalu River, facing North Korea.","",40.2,124.45],["D","丹东草莓","Dāndōng cǎoméi","Dandong strawberries","Dandong is known for sweet, large strawberries, picked in spring and often given as gifts."],["D","黄蚬子","Huángxiǎnzi","Yellow clams","A yellow clam from the Yellow Sea, steamed or stir-fried, a fresh and sweet seafood of Dandong."]]},{"id":"jinzhou","zh":"锦州","py":"Jǐnzhōu","en":"Jinzhou","lat":41.1,"lon":121.13,"note":"A coastal city on the corridor to the northeast.","stops":[["D","锦州烧烤","Jǐnzhōu shāokǎo","Jinzhou barbecue","Grilled meat skewers served with a special dip, and a popular dinner tradition in Jinzhou."],["D","锦州小菜","Jǐnzhōu xiǎocài","Jinzhou pickles","Crunchy pickled vegetables from Jinzhou, served as a side dish or a snack."]]},{"id":"yingkou","zh":"营口","py":"Yíngkǒu","en":"Yingkou","lat":40.67,"lon":122.24,"note":"A port city on the Liao River.","stops":[["D","营口大饼","Yíngkǒu dàbǐng","Yingkou big cake","A large, savory flatbread from Yingkou, baked until golden and eaten with soup or meat."]]},{"id":"fuxin","zh":"阜新","py":"Fùxīn","en":"Fuxin","lat":42.02,"lon":121.67,"note":"A coal town with a jade culture.","stops":[["D","阜新玛瑙","Fùxīn mǎnǎo","Fuxin agate","Fuxin is known for its agate, carved into small ornaments and sold as a local craft."]]},{"id":"liaoyang","zh":"辽阳","py":"Liáoyáng","en":"Liaoyang","lat":41.27,"lon":123.24,"note":"One of the oldest cities in the northeast.","stops":[["A","白塔","Báitǎ","Liaoyang White Pagoda","An octagonal pagoda from the Liao dynasty, standing tall in Liaoyang, with carved Buddha figures on each level.","",41.27,123.24]]},{"id":"panjin","zh":"盘锦","py":"Pánjǐn","en":"Panjin","lat":41.12,"lon":122.07,"note":"A wetland city with red beach.","stops":[["A","红海滩","Hóng Hǎitān","Red Beach","In autumn, a vast tidal flat on the coast turns bright red with sea-blite plants. A boardwalk lets you walk over the red carpet.","",40.9,121.9,1],["D","盘锦河蟹","Pánjǐn héxiè","Panjin crab","River crabs from the rice paddies of Panjin, which are famous for their sweet meat and are in season in autumn."]]},{"id":"tieling","zh":"铁岭","py":"Tiělǐng","en":"Tieling","lat":42.29,"lon":123.84,"note":"The hometown of the northeast comedy.","stops":[["A","莲花湖","Liánhuā Hú","Lotus Lake","A wetland with lotus flowers, reed beds and birds, a quiet place near Tieling.","",42.35,123.85],["D","铁岭榛子","Tiělǐng zhēnzi","Tieling hazelnuts","Hazelnuts from the hills near Tieling, a popular snack with a sweet and rich taste."]]},{"id":"chaoyang","zh":"朝阳","py":"Cháoyáng","en":"Chaoyang","lat":41.57,"lon":120.45,"note":"An ancient fossil city.","stops":[["A","凤凰山","Fènghuángshān","Fenghuang Mountain","A hill in Chaoyang with temples and old pagodas, and a long history of worship.","",41.57,120.45]]},{"id":"huludao","zh":"葫芦岛","py":"Húlúdǎo","en":"Huludao","lat":40.71,"lon":120.84,"note":"A coastal city and its fortress.","stops":[["A","兴城古城","Xīngchéng Gǔchéng","Xingcheng Ancient City","A Ming-dynasty walled town on the coast, with intact walls and gates, and a rare example of a fully walled old town.","",40.61,120.73],["D","兴城海鲜","Xīngchéng hǎixiān","Xingcheng seafood","Seafood from the Bohai Sea, simply cooked in the seaside restaurants of Xingcheng."],["D","葫芦岛海蜇","Húlúdǎo hǎizhē","Huludao jellyfish","Jellyfish from the Bohai Sea, cut into strips and served as a cold dish with vinegar and sesame oil."]]},{"id":"benxi","zh":"本溪","py":"Běnxī","en":"Benxi","lat":41.29,"lon":123.77,"note":"A cave city.","stops":[["A","本溪水洞","Běnxī Shuǐdòng","Benxi Water Cave","One of the largest water caves in the world, where you float by boat through a long underground river among glowing stalactites.","",41.2,124.05,1],["A","关门山","Guānmén Shān","Guanmenshan","A scenic mountain with maple forests that blaze red in autumn, and a river valley with cliffs.","",41.3,124.2],["D","本溪山葡萄","Běnxī shān pútáo","Benxi wild grape","A small wild mountain grape, sour and sweet, used for juice and wine."]]}],"air":{"zh":"沈阳桃仙国际机场","py":"Shěnyáng Táoxiān Guójì Jīchǎng","en":"Shenyang Taoxian International Airport","code":"SHE","lat":41.64,"lon":123.48,"note":"The main airport of Liaoning. Welcome to Liaoning."}},{"id":"macau","zh":"澳门","py":"Àomén","en":"Macau","cities":[{"id":"macau-peninsula","zh":"澳门半岛","py":"Àomén Bàndǎo","en":"Macau Peninsula","lat":22.2,"lon":113.54,"note":"The old city with Portuguese squares and temples.","stops":[["A","大三巴牌坊","Dàsānbāpái Fāng","Ruins of St. Paul's","The grand stone front of a Jesuit church that burned down in 1835, carved with saints, dragons and a Chinese inscription. It is the symbol of Macau and part of a UNESCO site.","A UNESCO World Heritage Site.",22.2,113.54,1],["A","议事亭前地","Yìshì Tíngqiándì","Senado Square","A plaza with a wave-patterned pavement and pastel colonial buildings, at the heart of the historic center of Macau.","",22.19,113.54,1],["A","妈阁庙","Māgémiào","A-Ma Temple","A temple for Mazu, the sea goddess, which the Portuguese heard locals call A-Ma-Gao, giving Macau its name. Incense coils hang over its courtyard.","",22.19,113.53,1],["A","澳门博物馆","Àomén Bówùguǎn","Macau Museum","A museum inside the old fortress, which tells the story of Macau from fishing village to a meeting place of China and Europe.","",22.2,113.54],["A","大炮台","Dà Pàotái","Mount Fortress","A hilltop fortress built by the Portuguese in the 17th century, with cannons and a view over the old city.","",22.2,113.54],["A","民政总署","Mínzhèng Zǒngshǔ","Leal Senado","The Leal Senado is a Portuguese-style civic building with blue-and-white tiles and a courtyard, in the central square.","",22.19,113.54],["A","玫瑰堂","Méiguī Táng","St. Dominic's Church","A yellow Baroque church with a white trim and green shutters, dating from the 16th century, one of the oldest in Macau.","",22.19,113.54],["A","观音堂","Guānyīntáng","Kun Iam Temple","A temple where, in 1844, China and the United States signed the first treaty between the two countries.","",22.2,113.55],["A","澳门塔","Àomén Tǎ","Macau Tower","A 338-meter tower, with a glass-floored viewing deck, a skywalk around the outside and the world's highest commercial bungee jump.","",22.18,113.54],["A","西望洋山","Xī Wàngyáng Shān","Penha Hill","A hill with a small chapel and a pousada, with a quiet view over the harbor and the old city.","",22.19,113.53],["A","郑家大屋","Zhèngjiā Dàwū","Mandarin's House","The home of the writer and thinker Zheng Guanying, a big complex of Chinese and Western styles beside the old city.","",22.19,113.53],["A","卢家大屋","Lújiā Dàwū","Lou Kau Mansion","A grand 19th-century merchant's mansion in the Chinese style with Western details, inside the historic center.","",22.2,113.54],["D","葡式蛋挞","Púshì dàntà","Portuguese egg tart","A flaky pastry shell with creamy custard and a caramelized top. The Macau version was developed from Portuguese pastéis de nata.","",null,null,1],["D","猪扒包","Zhūbā bāo","Pork chop bun","A juicy pork chop in a crisp bun, a simple, cheap and tasty Macau snack that locals love."],["D","杏仁饼","Xìngrén bǐng","Almond cookie","A crisp, crumbly cookie made with almonds or mung bean flour, sold in the shops along the old streets."],["D","猪肉脯","Zhūròufǔ","Dried pork slices","Thin slices of pork dried and grilled with sugar and soy, chewy and sweet, a famous Macau gift."],["D","姜撞奶","Jiāngzhuàngnǎi","Ginger milk curd","A warm milk pudding that sets when hot milk meets ginger juice, a simple dessert with a spicy kick."],["D","木糠布丁","Mùkāng bùdīng","Sawdust pudding","A dessert of layers of whipped cream and crumbled biscuits that look like sawdust, hence the name."],["D","马介休","Mǎ jièxiū","Bacalhau","Salted cod from Portugal soaked and cooked in a variety of ways, a staple of Macanese kitchens."],["D","葡国鸡","Púguó jī","Macanese chicken","A Macanese chicken dish baked with coconut milk, potatoes and curry spices, which blends Portuguese and Asian flavors."],["D","非洲鸡","Fēizhōu jī","African chicken","Grilled chicken in a spicy sauce of chili, garlic and peanut, a Macanese dish with a connection to Portugal's African colonies."],["C","澳门土生葡人","Àomén tǔshēng púrén","Macanese people","The Macanese are people of mixed Portuguese and Chinese ancestry, who developed their own language, food and customs."],["C","葡语","Púyǔ","Portuguese language","Portuguese is an official language of Macau beside Chinese, so you can see it on street signs and tiles."],["C","澳门博彩","Àomén bócǎi","Macau gaming","Gaming resorts are a major industry in Macau, and the city's casinos draw visitors from all over the world."],["C","妈祖诞","Māzǔ dàn","Mazu birthday","Every year on the 23rd of the third lunar month, devotees celebrate the sea goddess Mazu's birthday with parades and offerings."]]},{"id":"taipa","zh":"氹仔","py":"Dàngzǎi","en":"Taipa","lat":22.15,"lon":113.56,"note":"A pastel island of old village streets and new resorts.","stops":[["A","官也街","Guānyějiē","Rua do Cunha","A narrow lane in Taipa lined with shops and snack stalls, selling almond cookies, pork jerky and egg rolls.","",22.15,113.56],["A","龙环葡韵","Lónghuán Púyùn","Taipa Houses","Five green colonial houses beside a lake in Taipa, which now serve as a museum of Macanese life.","",22.15,113.56],["A","嘉模圣母堂","Jiāmó Shèngmǔ Táng","Our Lady of Carmo Church","A small church in the old village of Taipa, with a white and yellow front and a quiet garden.","",22.15,113.56],["A","威尼斯人","Wēinísī Rén","The Venetian","A giant resort modeled on Venice, with an indoor canal, gondolas and painted skies.","",22.15,113.57],["A","大潭山","Dàtán Shān","Taipa Grande hill","A hill in Taipa with walking paths and a tower, which gives wide views over the islands.","",22.15,113.56],["D","咖喱蟹","Gālí xiè","Curry crab","Crab cooked in a rich, creamy curry with coconut and spices, a favorite seafood dish."]]},{"id":"coloane","zh":"路环","py":"Lùhuán","en":"Coloane","lat":22.12,"lon":113.56,"note":"A quiet island with beaches and a chapel.","stops":[["A","路环村","Lùhuán Cūn","Coloane Village","A quiet village of pastel houses, small plazas, and old shops, which feels like old Macau.","",22.12,113.55],["A","圣方济各教堂","Shèng Fāngjìgè Jiàotáng","St. Francis Xavier Chapel","A small yellow chapel in Coloane that honors St. Francis Xavier, with a peaceful plaza in front.","",22.12,113.56],["A","黑沙海滩","Hēishā Hǎitān","Hac Sa Beach","A beach of dark sand on Coloane, with a park and a long, calm shore.","",22.11,113.6],["A","天后宫","Tiānhòugōng","Tin Hau Temple","A small temple for Tin Hau, the sea goddess, tucked beside the fishing village of Coloane.","",22.12,113.55],["D","安德鲁蛋挞","Āndélǔ dàntà","Lord Stow's egg tart","The famous egg tart from Lord Stow's bakery in Coloane, created by the English baker Andrew Stow in 1989.","The Macau egg tart is said to have been created here in 1989."],["C","路环渔村","Lùhuán yúcūn","Coloane fishing village","A village where dried fish are hung up in the sun and old boats rest by the shore, a reminder of Coloane's fishing past."]]}],"air":{"zh":"澳门国际机场","py":"Àomén Guójìjīchǎng","en":"Macau International Airport","code":"MFM","lat":22.15,"lon":113.59,"note":"Macau's airport, built on reclaimed land beside Taipa. Welcome to Macau."}},{"id":"neimenggu","zh":"内蒙古","py":"Nèi Měnggǔ","en":"Inner Mongolia","cities":[{"id":"hohhot","zh":"呼和浩特","py":"Hūhéhàotè","en":"Hohhot","lat":40.84,"lon":111.75,"note":"The Blue City, the capital of Inner Mongolia.","stops":[["A","大召寺","Dàzhào Sì","Dazhao Temple","A Tibetan Buddhist temple built in the 16th century in Hohhot, with a silver Buddha and richly painted halls. It was the first major lamasery here.","",40.8,111.66],["A","昭君墓","Zhāojūn Mù","Zhaojun Tomb","The grave mound of Wang Zhaojun, a Han court lady who married a Xiongnu chief to bring peace. A green hill rises from the plain.","",40.72,111.67],["A","内蒙古博物院","Nèi Měnggǔ Bówùyuàn","Inner Mongolia Museum","A museum with dinosaur skeletons, Mongolian costumes and relics of the steppe peoples, with a striking modern building.","",40.82,111.77],["A","席力图召","Xí Lìtú Zhào","Xilitu Temple","A temple of the Yellow Hat sect of Tibetan Buddhism in Hohhot, with an old hall of Ming-era design.","",40.8,111.66],["A","五塔寺","Wǔtǎsì","Five Pagoda Temple","A temple with a base topped by five small pagodas, covered in thousands of tiny Buddha carvings and a Mongolian star chart.","",40.79,111.66],["A","大青山","Dàqīngshān","Daqing Mountain","A mountain range north of Hohhot, with forests and meadows, a green backdrop for the city.","",40.9,111.7],["D","烧麦","Shāomài","Hohhot shaomai","Steamed dumplings stuffed with lamb, with thin, frilly wrappers, a Hohhot classic, often eaten with milk tea."],["D","手把肉","Shǒubǎ ròu","Hand-held meat","Mutton boiled with only salt and eaten by hand, cut off the bone with a knife. This is the classic way to eat on the Mongolian steppe.","",null,null,1],["D","奶茶","Nǎichá","Milk tea","Salty milk tea is made with brick tea and milk, often with millet and fried snacks, and is the Mongolian welcome drink."],["D","奶豆腐","Nǎidòufǔ","Milk tofu","A dried cheese made from milk that is sweet and sour, a staple snack that herders carry on the grasslands."],["D","莜面","Yóumiàn","Oat noodles","Noodles made from oat flour, which are rolled into thin tubes and steamed, a hearty staple of the cool northern plateau."],["D","马奶酒","Mǎnǎijiǔ","Mare's milk wine","A mildly alcoholic drink made by fermenting mare's milk, an old Mongolian tradition, and served at festivals."],["C","那达慕","Nàdámù","Naadam","The big summer festival of wrestling, archery and horse racing, held on the grasslands for centuries. Families gather in colorful dress.","",null,null,1],["C","马头琴","Mǎtóuqín","Morin khuur","The morin khuur is a two-stringed fiddle with a carved horse head, whose deep, soft voice is the sound of the steppe.","",null,null,1],["C","呼麦","Hūmài","Khoomei","Khoomei, or throat singing, is a technique in which one singer makes two notes at the same time, a low drone and high whistling melody."],["C","蒙古包","Měnggǔbāo","Yurt","A round tent covered with felt over a wooden frame that can be taken down and moved, the traditional home of herders."]]},{"id":"baotou","zh":"包头","py":"Bāotóu","en":"Baotou","lat":40.66,"lon":109.84,"note":"A steel city and the Bayan Obo mines.","stops":[["A","五当召","Wǔdāng Zhào","Wudang Lamasery","The largest Tibetan Buddhist monastery in Inner Mongolia, with white buildings that climb a hillside in a mountain valley.","",40.7,110.2],["A","成吉思汗陵","Chéngjísīhán Líng","Genghis Khan Mausoleum","A memorial hall for Genghis Khan, in the Ordos grassland. It holds no body but is a place of worship for Mongols.","",39.27,109.8],["D","包头羊肉","Bāotóu yángròu","Baotou lamb","Baotou's lamb comes from grassland sheep, with a mild taste, and is boiled, roasted or served in hotpot."],["D","包头烧麦","Bāotóu shāomài","Baotou shaomai","Steamed lamb dumplings from Baotou with a juicy filling, a staple breakfast food."]]},{"id":"ordos","zh":"鄂尔多斯","py":"È’ěrduōsī","en":"Ordos","lat":39.61,"lon":109.78,"note":"A coal city on a high plateau, home of Genghis Khan's mausoleum.","stops":[["A","响沙湾","Xiǎng Shāwān","Singing Sand Bay","A tall dune in the Kubuqi Desert that makes a low humming sound when sand slides down. Visitors can ride camels or slide on sleds.","",40.3,109.9],["A","成吉思汗陵园","Chéngjísīhán Língyuán","Genghis Khan Mausoleum","A grand memorial complex in Mongolian style, with domed halls and a great statue, where rituals have been held for centuries.","",39.27,109.8],["D","鄂尔多斯羊肉","È’ěrduōsī yángròu","Ordos lamb","Lamb from the Ordos steppe, with tender, clean-tasting meat, is a regional pride."],["D","手把羊肉","Shǒubǎ yángròu","Ordos hand-held mutton","Mutton boiled and eaten by hand, cut off the bone, with salt and perhaps a dip of chives."]]},{"id":"hulunbuir","zh":"呼伦贝尔","py":"Hūlúnbèi’ěr","en":"Hulunbuir","lat":49.21,"lon":119.77,"note":"A huge grassland in the far northeast.","stops":[["A","呼伦贝尔大草原","Hūlúnbèi’ěr Dà Cǎoyuán","Hulunbuir Grassland","One of the best grasslands in the world, with rolling green hills, herds of horses and sheep, and big skies, and wildflowers bloom in summer.","",49.2,119.7,1],["A","满洲里","Mǎnzhōulǐ","Manzhouli","A border town facing Russia, with a bright gate, Russian-style buildings and shops with nesting dolls.","",49.58,117.43],["A","阿尔山","Ā’ěrshān","Arxan","A forested area with hot springs, volcanic lakes and mountain views, a gentle summer escape.","",47.18,119.95],["A","呼伦湖","Hūlúnhú","Hulun Lake","A large lake on the Hulunbuir grassland, one of the biggest in northern China, rich in fish and home to many birds.","",48.9,117.3],["D","烤全羊","Kǎoquányáng","Roast whole lamb","A whole lamb roasted until the skin is crisp, then carved at the table, a feast for guests and celebrations."],["D","俄式面包","Éshì miànbāo","Russian bread","Round loaves of Russian-style bread are baked in the border town, thanks to the Russian settlers' influence."],["C","鄂温克族","Èwēnkè zú","Ewenki people","A people of herders and hunters in the Hulunbuir area, known for their reindeer and for their traditions."],["C","敖包","Áobāo","Ovoo","A heap of stones, branches and prayer flags built on a hill as a shrine, where people walk around three times to ask for blessings."]]},{"id":"chifeng","zh":"赤峰","py":"Chìfēng","en":"Chifeng","lat":42.26,"lon":118.89,"note":"A city of ancient culture and the Hongshan jade dragon.","stops":[["A","克什克腾","Kèshén Kèténg","Hexigten Geopark","A geopark with granite rock forests, volcanic landforms and grasslands, a varied landscape in Chifeng.","",43.25,117.55],["A","达里诺尔湖","Dálǐnuò’ěr Hú","Dalinor Lake","A big salt lake on the steppe where swans, cranes and other birds rest on their migration.","",43.3,116.5],["D","赤峰烤肉","Chìfēng kǎoròu","Chifeng barbecue","Meat grilled over charcoal on the table, an Inner Mongolian barbecue tradition, with a dipping sauce."],["D","赤峰莜面","Chìfēng yóumiàn","Chifeng oat noodles","Oat noodles steamed in rolls or tubes, and eaten with a savory sauce, a staple of the dry north."]]},{"id":"wuhai","zh":"乌海","py":"Wūhǎi","en":"Wuhai","lat":39.67,"lon":106.8,"note":"A coal city by the Yellow River.","stops":[["D","乌海葡萄","Wūhǎi pútáo","Wuhai grapes","Sweet grapes grown in the dry climate near the Yellow River, ripe in autumn."],["D","乌海牛肉","Wūhǎi niúròu","Wuhai beef","Beef raised on dry grassland in Wuhai, lean and tasty, often dried or braised."]]},{"id":"bayannur","zh":"巴彦淖尔","py":"Bāyànnào’ěr","en":"Bayannur","lat":40.75,"lon":107.39,"note":"The Hetao plain, a granary by the Yellow River.","stops":[["D","河套蜜瓜","Hétào mìguā","Hetao melon","A sweet, fragrant melon grown on the Hetao Plain by the Yellow River, where long hours of sun make it extra sweet."],["D","河套羊肉","Hétào yángròu","Hetao lamb","Lamb from the Hetao Plain, known for its tender meat that has little gamey smell."]]},{"id":"alxa","zh":"阿拉善","py":"Ālāshàn","en":"Alxa","lat":38.85,"lon":105.73,"note":"A desert league with the Badain Jaran.","stops":[["A","巴丹吉林沙漠","Bādānjílín Shāmò","Badain Jaran Desert","A desert with the tallest stationary dunes in the world, some almost 500 meters high, with small lakes between them.","",39.5,102.5],["A","黑城遗址","Hēichéng Yízhǐ","Khara-Khoto","The ruins of a fortress city of the Western Xia and Yuan dynasties, which was abandoned in the 14th century and left in the desert.","",41.8,101.1],["D","阿拉善肉苁蓉","Ālāshàn ròucōngróng","Alxa cistanche","Cistanche is a desert herb that grows on the roots of saxaul trees, which is used in tonics and is known as desert ginseng."],["D","骆驼奶","Luòtuó nǎi","Camel milk","Milk from Bactrian camels, which is thick and slightly salty, a traditional drink in the Gobi."]]},{"id":"xilingol","zh":"锡林郭勒","py":"Xīlín Guōlè","en":"Xilingol","lat":43.95,"lon":116.09,"note":"A grassland league.","stops":[["A","贡格尔草原","Gònggé’ěr Cǎoyuán","Gonggor Grassland","A wide grassland with rivers and herds of horses, a quiet area with big skies.","",43.7,117.2],["D","锡林郭勒羊肉","Xīlín Guōlè yángròu","Xilingol lamb","Lamb raised on the Xilingol grassland, known for tender meat and no strong smell, and one of the best in China."]]},{"id":"tongliao","zh":"通辽","py":"Tōngliáo","en":"Tongliao","lat":43.62,"lon":122.24,"note":"A city of Horqin grassland.","stops":[["A","科尔沁草原","Kē’ěrqìn Cǎoyuán","Horqin Grassland","A grassland in eastern Inner Mongolia, with a long Mongolian tradition and wrestling, and in summer, it is bright green.","",43.8,122.3],["D","通辽黄米","Tōngliáo huángmǐ","Tongliao millet","Yellow millet from Tongliao, which cooks into a sticky, sweet porridge or cake."]]},{"id":"ulanqab","zh":"乌兰察布","py":"Wūlánchábù","en":"Ulanqab","lat":41.03,"lon":113.13,"note":"A highland city of dinosaurs and wind farms.","stops":[["D","乌兰察布土豆","Wūlánchábù tǔdòu","Ulanqab potato","Potatoes grown on the cool plateau, with a rich, floury texture. Ulanqab is a major potato-growing region."]]},{"id":"hinggan","zh":"兴安盟","py":"Xīng’ān Méng","en":"Hinggan League","lat":46.08,"lon":122.04,"note":"A northeast league of forests.","stops":[["D","兴安盟大米","Xīng’ān Méng dàmǐ","Hinggan rice","Rice grown on the plains of the Hinggan League, where short summers and cold nights give it a sweet taste."]]}],"air":{"zh":"呼和浩特白塔国际机场","py":"Hūhéhàotè Báitǎ Guójì Jīchǎng","en":"Hohhot Baita International Airport","code":"HET","lat":40.85,"lon":111.82,"note":"The main airport of Inner Mongolia. Welcome to Inner Mongolia."}},{"id":"ningxia","zh":"宁夏","py":"Níngxià","en":"Ningxia","cities":[{"id":"yinchuan","zh":"银川","py":"Yínchuān","en":"Yinchuan","lat":38.49,"lon":106.23,"note":"The capital of the Hui Autonomous Region.","stops":[["A","西夏王陵","Xī Xiàwánglíng","Western Xia Imperial Tombs","The tombs of the emperors of the Western Xia, a lost kingdom of the 11th to 13th centuries, with earthen mounds rising from the desert plain at the foot of the Helan Mountains.","",38.48,105.98,1],["A","镇北堡西部影城","Zhènběibǎo Xībù Yǐngchéng","Zhenbeibu Western Film Studio","A ruined fort turned into a film set for Chinese movies, with mud walls that look like the Wild West.","",38.62,106.01],["A","贺兰山岩画","Hèlánshān Yánhuà","Helan Mountain Rock Art","Thousands of ancient carvings of animals, hunters and faces on the rocks of the Helan Mountains, some of them thousands of years old.","",38.62,105.94],["A","海宝塔","Hǎi Bǎotǎ","Haibao Pagoda","A square pagoda in the north of Yinchuan, with a long history, built about 1,600 years ago, and rebuilt many times.","",38.52,106.23],["A","沙湖","Shāhú","Shahu Lake","A lake beside a desert near Yinchuan, with golden dunes on one side and reeds and water birds on the other.","",38.84,106.36],["A","南关清真寺","Nánguān Qīngzhēnsì","Nanguan Mosque","A mosque in the city center of Yinchuan with a green dome and a minaret, a place of prayer for the Hui community.","",38.47,106.27],["D","手抓羊肉","Shǒuzhuā yángròu","Hand-grabbed mutton","Mutton boiled on the bone and eaten by hand with salt, simple and rich, a classic of the northwest."],["D","宁夏枸杞","Níngxià gǒuqǐ","Ningxia goji berries","Ningxia's goji berries are the best known in China, red, sweet and slightly sour, and are used in soups, teas and traditional medicine.","",null,null,1],["D","贺兰山葡萄酒","Hèlánshān pútáojiǔ","Helan Mountain wine","Wine from vineyards on the eastern slope of the Helan Mountains, where dry, sunny weather helps grapes ripen, and has won international prizes."],["D","羊杂碎","Yángzásuì","Lamb offal soup","A hot, spicy soup of lamb organs, and is eaten at breakfast with flatbread."],["D","八宝茶","Bābǎo chá","Eight-treasure tea","A tea of eight treasures, including goji, jujube, rock sugar and dried fruit, brewed in a lidded cup, a Hui welcome."],["D","黄渠桥羊羔肉","Huángqúqiáo yánggāoròu","Huangqiaoqiao lamb","Tender lamb from the Huangqu Bridge area, known for its mild flavor and soft texture."],["C","花儿","Huā’ér","Hua'er folk songs","Hua'er are folk songs of the northwest, sung outdoors with high, free voices about love and the landscape."],["C","回族婚礼","Huízú hūnlǐ","Hui wedding","A traditional Hui wedding with prayers, feasting and special foods, where families gather to celebrate."]]},{"id":"zhongwei","zh":"中卫","py":"Zhōngwèi","en":"Zhongwei","lat":37.5,"lon":105.19,"note":"A desert city on the Yellow River.","stops":[["A","沙坡头","Shāpōtóu","Shapotou","A desert park where a huge sand slope meets the Yellow River, with sand sliding, camel rides and a famous sand-control railway line.","",37.46,104.95,1],["A","黄河大拐弯","Huánghé Dà Guǎiwān","Yellow River Bend","A great bend of the Yellow River near Zhongwei, where the river turns and runs among green fields and desert.","",37.5,105.19],["A","腾格里沙漠","Ténggélǐ Shāmò","Tengger Desert","A big desert with high dunes, small lakes and oases, one of the largest deserts in China.","",37.6,105.1],["A","高庙","Gāomiào","Gao Temple","A temple in Zhongwei that combines Buddhist, Taoist and Confucian halls under one roof.","",37.51,105.19],["D","中卫苹果","Zhōngwèi píngguǒ","Zhongwei apples","Crisp, sweet apples grown in the sunny, dry climate of Zhongwei, with bright red skin."],["D","中卫硒砂瓜","Zhōngwèi xī shāguā","Zhongwei sand melon","Melons grown in a gravel field that keeps the soil warm and moist, with a sweet and crisp flesh."]]},{"id":"shizuishan","zh":"石嘴山","py":"Shízuǐshān","en":"Shizuishan","lat":39.01,"lon":106.38,"note":"A coal and wetland city in the north.","stops":[["A","星海湖","Xīnghǎi Hú","Xinghai Lake","A wetland park in Shizuishan, with reeds, lakes and many water birds in a desert landscape.","",39.02,106.38],["D","石嘴山羊肉","Shízuǐshān yángròu","Shizuishan lamb","Lamb raised on the dry grasslands near Shizuishan, which is simply boiled or roasted."]]},{"id":"wuzhong","zh":"吴忠","py":"Wúzhōng","en":"Wuzhong","lat":37.99,"lon":106.2,"note":"A river city of Hui culture.","stops":[["A","青铜峡一百零八塔","Qīngtóngxiá Yìbǎilíngbā Tǎ","108 Dagobas at Qingtongxia","A set of 108 white pagodas arranged in a triangle on a hillside above the Yellow River, with a mysterious history.","",37.93,105.99],["A","黄河大峡谷","Huánghé Dàxiágǔ","Yellow River Gorge","A gorge where the Yellow River runs through red cliffs, a place for boat trips.","",37.93,105.99],["D","吴忠手抓羊肉","Wúzhōngshǒu zhuā yángròu","Wuzhong mutton","Boiled mutton on the bone from Wuzhong, a rich local dish."],["D","盐池滩羊","Yánchí tānyáng","Yanchi Tan sheep","Tan sheep from Yanchi, prized for its fine, tender lamb with no gamey taste, thanks to salty grass."]]},{"id":"guyuan","zh":"固原","py":"Gùyuán","en":"Guyuan","lat":36.0,"lon":106.28,"note":"A southern mountain city on the Silk Road.","stops":[["A","须弥山石窟","Xūmíshān Shíkū","Xumishan Grottoes","Cave temples carved into a red sandstone cliff, with a giant seated Buddha about 20 meters high, from the Northern Wei to Tang dynasties.","",36.2,106.4],["A","六盘山","Liùpánshān","Liupan Mountain","The last big mountain crossed by the Red Army on the Long March in 1935, with green forests and a memorial park.","",35.67,106.2],["D","固原荞面","Gùyuán qiáomiàn","Guyuan buckwheat","Buckwheat noodles from Guyuan, a high, cool area where buckwheat grows well."]]}],"air":{"zh":"银川河东国际机场","py":"Yínchuān Hédōng Guójì Jīchǎng","en":"Yinchuan Hedong International Airport","code":"INC","lat":38.32,"lon":106.39,"note":"The main airport of Ningxia. Welcome to Ningxia."}},{"id":"qinghai","zh":"青海","py":"Qīnghǎi","en":"Qinghai","cities":[{"id":"xining","zh":"西宁","py":"Xīníng","en":"Xining","lat":36.62,"lon":101.78,"note":"The capital of Qinghai, a high-plateau city.","stops":[["A","塔尔寺","Tǎ’ěrsì","Kumbum Monastery","One of the six great monasteries of the Gelug school of Tibetan Buddhism and the birthplace of its founder, Tsongkhapa. It is known for its butter sculptures, murals and appliqué art.","",36.49,101.57,1],["A","东关清真大寺","Dōngguān Qīngzhēn Dàsì","Dongguan Mosque","One of the largest mosques in northwest China, in Xining, with a grand hall that holds thousands of worshippers.","",36.63,101.79],["A","青海省博物馆","Qīnghǎishěng Bówùguǎn","Qinghai Provincial Museum","A museum of the plateau, with Tibetan art, ancient pottery and displays about the wildlife and peoples of Qinghai.","",36.64,101.76],["A","水井巷","Shuǐ Jǐngxiàng","Shuijing Lane","A busy food lane in Xining, with stalls of noodles, yogurt, mutton and sweets, where locals shop and eat.","",36.62,101.78],["D","手抓羊肉","Shǒuzhuā yángròu","Hand-grabbed mutton","Plain boiled mutton on the bone, eaten with salt or a chili dip, a hearty staple of the plateau."],["D","酿皮","Niàngpí","Niangpi","A cool, springy noodle dish with chili oil, vinegar and sesame, which is especially refreshing in summer."],["D","青稞酒","Qīngkējiǔ","Highland barley wine","A wine made from highland barley, a drink at Tibetan festivals and gatherings, light and slightly sweet."],["D","酸奶","Suānnǎi","Yak yogurt","Thick yogurt made from yak or cow milk, tangy and rich, eaten with sugar on the plateau."],["D","糌粑","Zānbā","Tsampa","Roasted barley flour mixed with butter tea and kneaded by hand, a staple for Tibetan herders on the high plateau."],["D","狗浇尿","Gǒujiāoniào","Goujiaoniao bread","A flaky pancake whose odd name makes visitors laugh. It is a popular local bread, which is fried until golden and soft."],["D","牦牛肉","Máoniúròu","Yak meat","Yak meat is lean and rich, and is boiled, stewed or dried into jerky, a staple of the high plateau."],["C","花儿","Huā’ér","Hua'er songs","Hua'er are folk songs sung in the open air by Han, Hui, Tu and other peoples, with free, high-pitched voices."],["C","热贡艺术","Règòng yìshù","Regong art","Regong art is a tradition of Tibetan Buddhist painting and sculpture, with thangka paintings made by artists in the area of Tongren."]]},{"id":"haibei","zh":"海北","py":"Hǎiběi","en":"Haibei","lat":36.96,"lon":100.9,"note":"A prefecture with the great lake and rapeseed fields.","stops":[["A","青海湖","Qīnghǎihú","Qinghai Lake","China's largest lake, a vast, deep-blue salt lake high on the plateau. Fields of yellow rapeseed flowers bloom around it in summer, and many birds gather here.","",36.9,100.2,1],["A","祁连山","Qíliánshān","Qilian Mountains","A long range with snow peaks, glaciers and meadows on the edge of the plateau, with herds of yaks and sheep.","",38.18,100.25],["A","卓尔山","Zhuó’ěrshān","Zhuoer Mountain","A hill of red rock in the Qilian foothills, which offers views over the green valley and the river below.","",38.2,100.25],["D","青海湖裸鲤","Qīnghǎihú luǒlǐ","Qinghai Lake naked carp","A scaleless carp that lives in Qinghai Lake and swims up rivers to spawn, a slow-growing fish that is now protected."],["D","门源蜂蜜","Ményuán fēngmì","Menyuan honey","Honey from the bees that gather nectar from the vast fields of rapeseed flowers in Menyuan."],["C","环湖赛","Huánhúsài","Qinghai Lake Cycling Race","An international road cycling race around Qinghai Lake, held each summer, that draws riders from many countries."]]},{"id":"haidong","zh":"海东","py":"Hǎidōng","en":"Haidong","lat":36.5,"lon":102.1,"note":"An eastern city of Tu and Hui culture.","stops":[["A","瞿昙寺","Qútánsì","Qutan Temple","A Ming-era temple with fine murals and a palace-like hall, sometimes called the Little Forbidden City of Qinghai.","",36.5,102.62],["A","喇家遗址","Lǎjiā Yízhǐ","Lajia Site","A Neolithic site where a disaster, perhaps a flood and earthquake, froze a village in time. A bowl of 4,000-year-old noodles was found here.","",35.82,102.58],["D","土族盘绣","Tǔzú pánxiù","Tu coiled embroidery","A coiled embroidery of the Tu people, in which the threads are twisted and coiled into bright patterns on cloth."]]},{"id":"haixi","zh":"海西","py":"Hǎixī","en":"Haixi","lat":37.37,"lon":97.37,"note":"A prefecture of salt lakes and deserts.","stops":[["A","茶卡盐湖","Chákǎ Yánhú","Chaka Salt Lake","A shallow salt lake that mirrors the sky like a giant mirror. When the water is still, the clouds seem to float below your feet.","",36.79,99.08,1],["A","青海翡翠湖","Qīnghǎi Fěicuì Hú","Emerald Lake","A lake of salt crystals in the Qaidam Basin, where mineral colors turn the water green and blue.","",36.88,95.97],["D","柴达木枸杞","Cháidámù gǒuqǐ","Qaidam goji berries","Goji berries from the Qaidam Basin, grown in salty soil under strong sun, are dark red and sweet."],["D","察尔汗盐","Chá’ěrhàn yán","Qarhan salt","Salt harvested from the vast Qarhan Salt Lake, which is so hard that a road and a railway are built on it."]]},{"id":"yushu","zh":"玉树","py":"Yùshù","en":"Yushu","lat":33.0,"lon":97.01,"note":"The source region of three great rivers.","stops":[["A","结古寺","Jié Gǔsì","Jyekundo Monastery","A monastery in Yushu with prayer flags and mani stones, an important center for Tibetan Buddhism.","",33.0,97.01],["D","虫草","Chóngcǎo","Caterpillar fungus","Caterpillar fungus is gathered in the high meadows in spring and is prized in traditional medicine."],["D","玉树赛马节","Yùshù sàimǎjié","Yushu horse festival","A summer festival where horse riders race and show their skills while families camp in tents on the grassland."]]},{"id":"huangnan","zh":"黄南","py":"Huángnán","en":"Huangnan","lat":35.52,"lon":102.02,"note":"The home of Regong painting.","stops":[["A","隆务寺","Lóngwùsì","Rongwo Monastery","A large monastery in Tongren with fine paintings, sculptures and a long tradition of Tibetan art.","",35.52,102.01],["D","黄南酥油花","Huángnán sūyóuhuā","Butter flowers","Sculptures made of colored butter, shaped into flowers and figures for festivals, which melt away after the show."]]},{"id":"guoluo","zh":"果洛","py":"Guǒluò","en":"Golog","lat":34.47,"lon":100.24,"note":"A high grassland prefecture.","stops":[["A","阿尼玛卿雪山","Ānímǎqīng Xuěshān","Amne Machin","A sacred snow range that Tibetans believe is home to a powerful mountain god, and which pilgrims circle on foot.","",34.7,99.4]]},{"id":"hainan-qh","zh":"海南州","py":"Hǎinán Zhōu","en":"Hainan Prefecture","lat":36.28,"lon":100.62,"note":"A prefecture near the lake.","stops":[["D","贵德梨","Guìdé lí","Guide pear","A sweet pear grown in the warm Yellow River valley at Guide, among the best fruits of the Qinghai plateau."]]}],"air":{"zh":"西宁曹家堡国际机场","py":"Xīníng Cáojiābǎo Guójì Jīchǎng","en":"Xining Caojiabao International Airport","code":"XNN","lat":36.53,"lon":102.04,"note":"The main airport of Qinghai, at high altitude. Welcome to Qinghai."}},{"id":"shaanxi","zh":"陕西","py":"Shǎnxī","en":"Shaanxi","cities":[{"id":"xian","zh":"西安","py":"Xī’ān","en":"Xi'an","lat":34.34,"lon":108.94,"note":"An ancient capital and the start of the Silk Road.","stops":[["A","兵马俑","Bīngmǎyǒng","Terracotta Army","Thousands of life-size clay soldiers, horses and chariots stand guard at the tomb of Qin Shi Huang, the first emperor. Each soldier has a different face. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",34.38,109.27,1],["A","西安城墙","Xī’ān Chéngqiáng","Xi'an City Wall","A Ming-dynasty wall, about 14 kilometers around, that is among the best preserved in China. You can walk or cycle along the top, on a wide road.","",34.26,108.94,1],["A","大雁塔","Dàyàntǎ","Giant Wild Goose Pagoda","A Tang-dynasty pagoda built in 652 to store the Buddhist scriptures that the monk Xuanzang brought back from India.","",34.22,108.96],["A","小雁塔","Xiǎo Yàntǎ","Small Wild Goose Pagoda","A slimmer Tang pagoda in the city, famous for its fine shape, and known for a deep crack that once closed after an earthquake.","",34.24,108.94],["A","钟楼","Zhōnglóu","Bell Tower","A Ming-dynasty tower at the center of the old city, where a big bell was rung to mark the morning.","",34.26,108.94],["A","鼓楼","Gǔlóu","Drum Tower","A tower that stands near the Bell Tower, where a huge drum was beaten at dusk to tell the time.","",34.26,108.94],["A","回民街","Huímín Jiē","Muslim Quarter","A busy lane of snack stalls and shops in the old Muslim neighborhood, with mutton skewers, sweets and the smell of spices.","",34.26,108.94],["A","华清池","Huáqīngchí","Huaqing Pool","A hot spring palace at the foot of Mount Li, tied to Emperor Xuanzong and his favorite, Yang Guifei, as described in a famous poem.","",34.36,109.21],["A","陕西历史博物馆","Shǎnxīlìshǐ Bówùguǎn","Shaanxi History Museum","A grand museum with treasures such as Tang gold and silver, murals and ancient bronzes, which shows the story of Shaanxi and China.","",34.22,108.95],["A","碑林博物馆","Bēilín Bówùguǎn","Beilin Museum","A forest of stone steles with calligraphy by the greatest masters, and the Confucian classics, carved in stone over a thousand years.","",34.25,108.95],["A","华山","Huàshān","Mount Hua","One of the Five Sacred Mountains, with sheer granite cliffs. A path of planks hangs over the abyss, one of the most thrilling hikes in China.","",34.48,110.08,1],["D","肉夹馍","Ròujiāmó","Roujiamo","Braised, chopped meat tucked in a crisp, chewy flatbread, often called a Chinese hamburger, a staple of Xi'an street food.","",null,null,1],["D","凉皮","Liángpí","Liangpi","Cool, slippery noodles made from wheat or rice starch, tossed with chili oil, vinegar, cucumber and sesame paste."],["D","羊肉泡馍","Yángròu pàomó","Yangrou paomo","A bowl of lamb soup in which you tear a flatbread into small pieces, and which is then cooked into a rich meal. A Xi'an classic."],["D","油泼面","Yóupōmiàn","Oil-splashed noodles","Wide, hand-pulled noodles topped with chili flakes, garlic and scallions, then splashed with sizzling hot oil.","Biangbiang noodles, the same kind of dish, have a name character said to have more than 50 strokes."],["D","柿子饼","Shìzi bǐng","Persimmon cake","A sweet fried cake made from persimmons, a Xi'an treat with a soft center and crisp shell."],["D","臊子面","Sàozi miàn","Saozi noodles","Noodles in a sour and spicy sauce with diced meat and vegetables, a Shaanxi classic, often served at weddings and festivals."],["C","秦腔","Qínqiāng","Qin opera","Qin opera is a loud, powerful local opera, one of the oldest in China, sung with strong, high voices."],["C","皮影戏","Píyǐngxì","Shadow puppetry","A theater of leather puppets with a lamp behind a screen, and a skilled team of artists make them move and sing."],["C","西安鼓乐","Xī’ān gǔyuè","Xi'an drum music","An old style of ensemble music with drums and wind instruments, which has links to the Tang court."]]},{"id":"xianyang","zh":"咸阳","py":"Xiányáng","en":"Xianyang","lat":34.33,"lon":108.71,"note":"The capital of the Qin dynasty before the empire.","stops":[["A","汉阳陵","Hànyánglíng","Hanyangling Mausoleum","A Han-dynasty tomb complex with thousands of small clay figures buried in pits, and a museum below the ground.","",34.45,108.98],["A","乾陵","Qiánlíng","Qianling Mausoleum","The shared tomb of Emperor Gaozong and Empress Wu Zetian, with a Sacred Way lined with giant stone figures.","",34.58,108.22],["D","咸阳烙面","Xiányáng làomiàn","Xianyang lao mian","Thin noodles cooked on a pan and served with a savory, fragrant sauce, a Xianyang specialty."]]},{"id":"baoji","zh":"宝鸡","py":"Bǎojī","en":"Baoji","lat":34.36,"lon":107.24,"note":"The cradle of Zhou culture and bronzes.","stops":[["A","法门寺","Fǎménsì","Famen Temple","A temple that houses a finger-bone relic of the Buddha, found in an underground vault with Tang treasures.","",34.45,107.89],["A","太白山","Tàibáishān","Taibai Mountain","The highest peak in the Qinling Mountains, with a range of climates from forest to snowy rocks and a sea of cloud.","",34.0,107.76],["D","岐山臊子面","Qíshān sàozi miàn","Qishan saozi noodles","The classic Qishan version of saozi noodles, with a thin, springy noodle in a hot, sour, savory soup."],["D","宝鸡擀面皮","Bǎojī gǎn miànpí","Baoji rolled noodles","Cool noodles made from rolled dough, tossed in chili oil, vinegar and sauce, a street snack from Baoji."]]},{"id":"yanan","zh":"延安","py":"Yán’ān","en":"Yan'an","lat":36.6,"lon":109.49,"note":"The base of the Communist Party in the 1930s and 40s.","stops":[["A","壶口瀑布","Húkǒu Pùbù","Hukou Waterfall","The Yellow River squeezes into a narrow gorge and falls into it with a roar, like water pouring from a teapot.","",36.14,110.43],["D","洋芋擦擦","Yángyù cācā","Potato shreds","Shredded potato tossed with flour, steamed and then mixed with chili and garlic, a simple dish from northern Shaanxi."],["D","延安黄馍馍","Yán’ān huáng mómó","Yellow millet bun","A sweet steamed cake of yellow millet, a staple of the Loess Plateau."]]},{"id":"hanzhong","zh":"汉中","py":"Hànzhōng","en":"Hanzhong","lat":33.07,"lon":107.02,"note":"A southern basin city, the base of the Han dynasty.","stops":[["A","武侯墓","Wǔhóu Mù","Wuhou Tomb","The tomb of Zhuge Liang, the brilliant strategist of the Three Kingdoms, who is a symbol of loyalty and wisdom.","",33.14,106.78],["D","汉中热米皮","Hànzhōng rèmǐ pí","Hanzhong hot rice skin","Steamed rice noodles served warm with a spicy sauce, a Hanzhong breakfast."],["D","汉中菜豆腐","Hànzhōng cài dòufǔ","Hanzhong vegetable tofu","A soft tofu made with the leaves of local vegetables, a Hanzhong specialty with a unique flavor."]]},{"id":"yulin","zh":"榆林","py":"Yúlín","en":"Yulin","lat":38.29,"lon":109.73,"note":"A northern city on the edge of the desert.","stops":[["A","红碱淖","Hóngjiǎn Nào","Hongjiannao Lake","The largest desert lake in China, a wide lake with water birds beside the Mu Us sandy land.","",39.07,109.87],["A","榆林古城","Yúlín Gǔchéng","Yulin Old City","A Ming and Qing walled city on the edge of the desert, once a frontier garrison, with watchtowers and old streets.","",38.29,109.74],["D","羊肉面","Yángròu miàn","Yulin lamb noodles","Noodles in a hot lamb broth, a staple of northern Shaanxi's cold winters."],["D","榆林豆腐","Yúlín dòufǔ","Yulin tofu","Tofu made with local water, firm and fine, a specialty that is cooked in a variety of ways."]]},{"id":"weinan","zh":"渭南","py":"Wèinán","en":"Weinan","lat":34.5,"lon":109.51,"note":"An eastern city near the Yellow River.","stops":[["D","蒲城酥饼","Púchéng sūbǐng","Pucheng pastry","A flaky pastry with a sweet filling, made in Pucheng for generations."],["D","大荔冬枣","Dàlì dōngzǎo","Dali winter jujube","Crisp and sweet winter jujubes that ripen late in the year in Dali, a juicy fruit that is popular as a snack."]]},{"id":"shangluo","zh":"商洛","py":"Shāngluò","en":"Shangluo","lat":33.87,"lon":109.94,"note":"A mountain area in the Qinling range.","stops":[["D","商洛核桃","Shāngluò hétáo","Shangluo walnuts","Walnuts grown on the mountain slopes of Shangluo, rich and oily and used in snacks and cooking."]]},{"id":"ankang","zh":"安康","py":"Ānkāng","en":"Ankang","lat":32.69,"lon":109.03,"note":"A southern city rich in tea and selenium.","stops":[["D","安康蒸面","Ānkāng zhēngmiàn","Ankang steamed noodles","Noodles steamed on a rack and then dressed with a spicy sauce, a favorite in Ankang."],["D","紫阳富硒茶","Zǐyáng fùxīchá","Ziyang selenium tea","A tea from Ziyang, grown in selenium-rich soil, a green tea with a clear, mellow taste."]]}],"air":{"zh":"西安咸阳国际机场","py":"Xī’ān Xiányáng Guójì Jīchǎng","en":"Xi'an Xianyang International Airport","code":"XIY","lat":34.45,"lon":108.75,"note":"The main airport of Shaanxi, northwest of Xi'an. Welcome to Shaanxi."}},{"id":"shandong","zh":"山东","py":"Shāndōng","en":"Shandong","cities":[{"id":"qingdao","zh":"青岛","py":"Qīngdǎo","en":"Qingdao","lat":36.07,"lon":120.38,"note":"A seaside city of German-era buildings and beer.","stops":[["A","栈桥","Zhànqiáo","Zhanqiao Pier","A pier that reaches about 440 meters out into Qingdao Bay, with a small pavilion at its end, and a symbol of the city.","",36.06,120.32],["A","青岛啤酒博物馆","Qīngdǎo Píjiǔ Bówùguǎn","Tsingtao Beer Museum","A museum in the old brewery founded in 1903, which shows how beer is made and lets you taste it fresh.","",36.08,120.37],["A","崂山","Láoshān","Laoshan Mountain","A coastal mountain where cliffs meet the sea, with Taoist temples and springs, known for its clear spring water.","",36.19,120.62],["A","八大关","Bādàguān","Badaguan","A leafy district of villas in many European styles, along quiet, tree-lined streets near the sea.","",36.05,120.35],["A","天主教堂","Tiānzhǔ Jiàotáng","St. Michael's Cathedral","A twin-spired Catholic church from the German era in Qingdao, a Gothic-style landmark on a hill.","",36.06,120.32],["A","五四广场","Wǔsì Guǎngchǎng","May Fourth Square","A seafront square with a big red sculpture called May Wind, with Olympic sailing nearby.","",36.06,120.39],["A","小青岛","Xiǎoqīngdǎo","Little Qingdao Island","A small island with a white lighthouse, connected by a path, and a quiet, pretty spot by the bay.","",36.05,120.32],["A","金沙滩","Jīnshātān","Golden Sands Beach","A long beach of fine golden sand on the east coast of Qingdao, a place for swimming and festivals.","",35.93,120.19],["D","青岛啤酒","Qīngdǎo píjiǔ","Tsingtao beer","China's best-known beer, born in Qingdao, and in summer you can even drink it fresh from a plastic bag.","",null,null,1],["D","海鲜","Hǎixiān","Qingdao seafood","Clams, shrimp, crab and fish from the Yellow Sea are fresh and simply cooked in Qingdao's restaurants."],["D","辣炒蛤蜊","Làchǎo gélí","Spicy stir-fried clams","A beachside favorite of clams stir-fried in chili and garlic, which goes very well with cold beer."],["D","鲅鱼水饺","Bàyú shuǐjiǎo","Mackerel dumplings","Dumplings filled with Spanish mackerel and chives, a Shandong coastal specialty, with a fresh, sweet flavor."],["C","啤酒节","Píjiǔjié","Qingdao Beer Festival","Every summer, Qingdao holds a beer festival with huge tents, live music and thousands of visitors."]]},{"id":"jinan","zh":"济南","py":"Jǐnán","en":"Jinan","lat":36.67,"lon":117.0,"note":"The City of Springs and the capital of Shandong.","stops":[["A","趵突泉","Bàotūquán","Baotu Spring","A spring that bubbles up from the ground in three jets, the most famous of Jinan's many springs, which is why Jinan is called the City of Springs.","",36.66,117.01,1],["A","大明湖","Dàmínghú","Daming Lake","A lake in the city center with lotus flowers, willows and old pavilions, fed by the springs of Jinan.","",36.68,117.02],["A","千佛山","Qiānfóshān","Thousand Buddha Mountain","A hill with Buddhist carvings above the city of Jinan, with a temple and a view over the city.","",36.64,117.03],["A","黑虎泉","Hēihǔquán","Black Tiger Spring","A spring that gushes through stone tiger heads into a moat, where locals come to fill their bottles with spring water.","",36.66,117.03],["A","芙蓉街","Fúróng Jiē","Furong Street","A street of snacks near the springs, with old shops and stalls, where you can try local treats such as fried milk.","",36.67,117.02],["A","灵岩寺","Língyánsì","Lingyan Temple","An old temple south of Jinan, with a forest of pagodas and rare Song-dynasty statues of monks.","",36.34,117.15],["D","九转大肠","Jiǔzhuǎn dàcháng","Nine-turn large intestine","Pork intestine braised in a sweet-sour sauce, repeated several times, a Shandong classic with a rich flavor."],["D","把子肉","Bǎzi ròu","Bazi pork","Braised pork served over rice, a simple and filling local meal in Jinan."],["D","油旋","Yóuxuán","Youxuan","A flaky, layered bread with scallion, rolled in a spiral and baked until golden."],["D","甜沫","Tiánmò","Tianmo","A savory millet porridge with peanuts, vermicelli and vegetables, a traditional breakfast in Jinan."],["C","吕剧","Lǚjù","Lü opera","The local opera of Shandong, with simple tunes and stories about village life."]]},{"id":"qufu","zh":"曲阜","py":"Qūfù","en":"Qufu","lat":35.58,"lon":116.99,"note":"The hometown of Confucius.","stops":[["A","孔庙","Kǒngmiào","Confucius Temple","A vast temple complex for Confucius in his hometown, with many halls and ancient cypress trees. It is part of a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",35.6,116.99,1],["A","孔府","Kǒngfǔ","Kong Family Mansion","The mansion of the Confucius family, with over 400 rooms, where the descendants of Confucius lived for centuries.","",35.6,116.99],["A","孔林","Kǒnglín","Confucius Forest","A large forest cemetery for Confucius and his descendants, with thousands of stone steles and old trees.","",35.61,117.0],["D","孔府菜","Kǒngfǔ cài","Kong family cuisine","A banquet cuisine of the Confucius family, with elegant dishes that were served to officials and emperors."],["D","曲阜烧饼","Qūfù shāobǐng","Qufu flatbread","A crisp sesame flatbread from Qufu, baked in a clay oven and eaten fresh."],["C","祭孔大典","Jì Kǒng Dàdiǎn","Confucius Ceremony","A ceremony in Qufu to honor Confucius with music, dance and offerings, held every year in autumn."],["C","儒家思想","Rújiā sīxiǎng","Confucianism","The teaching system that grew from Confucius's ideas of virtue, learning and family, which shaped China and East Asia."]]},{"id":"taian","zh":"泰安","py":"Tài’ān","en":"Tai'an","lat":36.2,"lon":117.09,"note":"The home of the Mount Tai pilgrimage.","stops":[["A","泰山","Tàishān","Mount Tai","The most honored of the Five Sacred Mountains. Emperors made offerings here, and pilgrims climb 6,000 stone steps to see the sunrise from the top. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",36.26,117.1,1],["A","岱庙","Dàimiào","Dai Temple","A temple at the foot of Mount Tai where emperors made offerings, with big halls and old cypresses.","",36.19,117.12],["A","玉皇顶","Yùhuángdǐng","Jade Emperor Peak","The highest point of Mount Tai, with a small temple and a view of the clouds.","",36.27,117.11],["D","泰安豆腐宴","Tài’ān dòufǔ yàn","Tai'an tofu banquet","A feast made from tofu in many forms, with water from the mountain springs."],["D","泰山赤鳞鱼","Tàishān chìlínyú","Mount Tai red-scale fish","A fish from the cold streams of Mount Tai, steamed or fried, with sweet and tender meat."]]},{"id":"yantai","zh":"烟台","py":"Yāntái","en":"Yantai","lat":37.46,"lon":121.45,"note":"A port city of wine, apples and beaches.","stops":[["A","蓬莱阁","Péngláigé","Penglai Pavilion","A cliff pavilion in Penglai, linked to the legend of the Eight Immortals crossing the sea, and said to show visions of mirages.","",37.82,120.76],["D","烟台苹果","Yāntái píngguǒ","Yantai apples","Sweet, crisp red apples from the orchards of Yantai, one of the best-known apple regions in China."],["D","烟台海参","Yāntái hǎishēn","Yantai sea cucumber","Sea cucumber from the cold Bohai Sea is a highly valued seafood, cooked in rich sauces."],["D","福山拉面","Fúshān lāmiàn","Fushan hand-pulled noodles","Hand-pulled noodles from Fushan, served with a rich meat topping, a famous Yantai dish."],["D","张裕葡萄酒","Zhāngyù pútáojiǔ","Changyu wine","Changyu is one of China's oldest wine brands, founded in 1892 in Yantai, with a wine museum in an old cellar."]]},{"id":"weihai","zh":"威海","py":"Wēihǎi","en":"Weihai","lat":37.51,"lon":122.12,"note":"A clean seaside city at the tip of the peninsula.","stops":[["D","威海海参","Wēihǎi hǎishēn","Weihai sea cucumber","Sea cucumber from the clean waters of Weihai, a prized local seafood, usually braised or in soup."],["D","烤鱿鱼","Kǎo yóuyú","Grilled squid","A common street snack of squid grilled on a stick, brushed with a spicy sauce."]]},{"id":"weifang","zh":"潍坊","py":"Wéifāng","en":"Weifang","lat":36.71,"lon":119.16,"note":"The kite capital of the world.","stops":[["A","潍坊风筝博物馆","Wéifāng Fēngzhēng Bówùguǎn","Weifang Kite Museum","A museum of Weifang's kites, a craft that has been practiced for centuries, in the city that hosts a kite festival.","",36.71,119.16],["D","潍坊朝天锅","Wéifāng cháotiān guō","Weifang chaotian pot","A pot of pork and offal stewed all day, served with flatbread, a Weifang tradition."],["D","潍县萝卜","Wéixiàn luóbo","Weixian radish","A crisp, juicy radish that is eaten like a fruit, a Weifang specialty."]]},{"id":"zibo","zh":"淄博","py":"Zībó","en":"Zibo","lat":36.81,"lon":118.05,"note":"A city of ancient Qi and barbecue fame.","stops":[["D","淄博烧烤","Zībó shāokǎo","Zibo barbecue","Grilled meat that you wrap in small flatbreads with scallions and a sauce, which became a viral hit in 2023."],["D","周村烧饼","Zhōucūn shāobǐng","Zhoucun flatbread","A thin, crisp sesame flatbread from Zhoucun, so thin that it breaks at a touch."],["C","琉璃","Liúlí","Zibo colored glaze","Colored glass art made in Boshan, where craftsmen have made glass for centuries, in bright colors."]]},{"id":"jining","zh":"济宁","py":"Jǐníng","en":"Jining","lat":35.41,"lon":116.59,"note":"A canal city next to Qufu.","stops":[["A","孟庙","Mèngmiào","Mencius Temple","A temple to Mencius, the second sage of Confucianism, in his hometown Zoucheng.","",35.4,117.04],["D","济宁辣子鸡","Jǐníng làzijī","Jining spicy chicken","A fried chicken dish tossed with dried chilies, a local favorite in Jining."]]},{"id":"linyi","zh":"临沂","py":"Línyí","en":"Linyi","lat":35.1,"lon":118.36,"note":"A commercial city in the Yimeng hills.","stops":[["A","沂蒙山","Yíméngshān","Yimeng Mountain","A hill area of Shandong with a revolutionary history, with villages that supported the army in the 1940s.","",35.53,118.0],["D","沂蒙煎饼","Yíméng jiānbǐng","Yimeng jianbing","A thin, crepe-like bread cooked on a griddle, and rolled with scallions and sauce, a Shandong staple."],["D","临沂炒鸡","Línyí chǎojī","Linyi stir-fried chicken","Chicken stir-fried with spices and served in a pot, a Linyi favorite."]]},{"id":"rizhao","zh":"日照","py":"Rìzhào","en":"Rizhao","lat":35.42,"lon":119.53,"note":"A sunny coastal city and a green tea region.","stops":[["D","日照绿茶","Rìzhào lǜchá","Rizhao green tea","A green tea grown in the north, where cool weather and sea air give it a strong, fresh flavor."],["D","日照海鲜","Rìzhào hǎixiān","Rizhao seafood","Fresh catches from the Yellow Sea, served simply by the shore."]]},{"id":"dongying","zh":"东营","py":"Dōngyíng","en":"Dongying","lat":37.43,"lon":118.67,"note":"The city of the Yellow River Delta and oil.","stops":[["A","黄河入海口","Huánghé Rùhǎikǒu","Yellow River Mouth","The place where the Yellow River reaches the sea, with a wide delta of wetlands and many migratory birds.","",37.77,119.15],["D","黄河口大闸蟹","Huánghékǒu dàzháxiè","Yellow River crab","Crabs from the Yellow River delta, in autumn, with rich, creamy roe."]]},{"id":"dezhou","zh":"德州","py":"Dézhōu","en":"Dezhou","lat":37.44,"lon":116.36,"note":"A city famous for braised chicken.","stops":[["D","德州扒鸡","Dézhōu pájī","Dezhou braised chicken","A famous braised chicken, cooked so long that the meat falls off the bone. Its shape, with the legs crossed, is easy to spot.","",null,null,1]]},{"id":"liaocheng","zh":"聊城","py":"Liáochéng","en":"Liaocheng","lat":36.46,"lon":115.99,"note":"A canal city of old towers.","stops":[["D","聊城火烧","Liáochéng huǒshāo","Liaocheng baked bun","A layered, baked flatbread that is often filled with meat or eaten on its own, a Liaocheng specialty."]]},{"id":"binzhou","zh":"滨州","py":"Bīnzhōu","en":"Binzhou","lat":37.38,"lon":117.97,"note":"A city on the Yellow River.","stops":[["A","魏氏庄园","Wèishì Zhuāngyuán","Wei Family Manor","A rural mansion of the late Qing, with walled courtyards and halls, the home of a wealthy local family.","",37.55,117.77],["D","滨州锅子","Bīnzhōu guōzi","Binzhou pot","A pot dish of meat and vegetables simmered at the table, a tradition for family gatherings."]]},{"id":"zaozhuang","zh":"枣庄","py":"Zǎozhuāng","en":"Zaozhuang","lat":34.81,"lon":117.32,"note":"A coal city on the Grand Canal.","stops":[["D","枣庄辣子鸡","Zǎozhuāng làzijī","Zaozhuang spicy chicken","A spicy fried chicken dish, with chilies and a lot of garlic, a Zaozhuang favorite."]]},{"id":"heze","zh":"菏泽","py":"Hézé","en":"Heze","lat":35.23,"lon":115.48,"note":"The city of peonies.","stops":[["D","菏泽牡丹","Hézé mǔdān","Heze peonies","Heze is the main place in China that grows peonies, with huge fields blooming in spring."],["D","单县羊肉汤","Shànxiàn yángròutāng","Shanxian lamb soup","A white, milky lamb soup that is simmered for hours, popular for breakfast in Shanxian."]]},{"id":"laiwu","zh":"莱芜","py":"Láiwú","en":"Laiwu","lat":36.21,"lon":117.68,"note":"A hilly city, now a district of Jinan.","stops":[["D","莱芜生姜","Láiwú shēngjiāng","Laiwu ginger","Laiwu's ginger is famous for its large, juicy roots and strong aroma."]]}],"air":{"zh":"青岛胶东国际机场","py":"Qīngdǎo Jiāodōng Guójì Jīchǎng","en":"Qingdao Jiaodong International Airport","code":"TAO","lat":36.36,"lon":120.09,"note":"The newer airport of Qingdao, opened in 2021. Welcome to Shandong."}},{"id":"shanxi","zh":"山西","py":"Shānxī","en":"Shanxi","cities":[{"id":"taiyuan","zh":"太原","py":"Tàiyuán","en":"Taiyuan","lat":37.87,"lon":112.55,"note":"The capital of Shanxi, a coal and heritage city.","stops":[["A","晋祠","Jìncí","Jinci Temple","A temple complex of the Song dynasty near Taiyuan, built around a spring and shaded by ancient cypress trees, with beautiful clay statues of maids.","",37.71,112.44],["A","山西博物院","Shānxī Bówùyuàn","Shanxi Museum","A museum of Shanxi's long history, with Jin-state bronzes, Buddhist sculptures and relics of the merchants who made the province rich.","",37.84,112.53],["A","双塔寺","Shuāngtǎsì","Twin Pagodas Temple","Two Ming pagodas that rise side by side above the roofs of Taiyuan, a symbol of the city.","",37.85,112.59],["D","刀削面","Dāoxiāomiàn","Knife-cut noodles","Noodles shaved with a curved knife from a lump of dough straight into boiling water, each strip thick in the middle and thin at the edges, topped with a savory sauce.","",null,null,1],["D","头脑","Tóunǎo","Toune","A winter dish of lamb, yam, lotus root and a splash of wine, served hot as a breakfast tonic. It is a Taiyuan tradition."],["D","太原老陈醋","Tàiyuán lǎochéncù","Shanxi aged vinegar","A dark, mellow vinegar aged for years, a symbol of Shanxi, where cooks add it to everything from noodles to dumplings."],["D","莜面栲栳栳","Yóumiàn kǎolǎo lǎo","Oat noodle rolls","Rolls of oat noodle dough shaped into little baskets and steamed, then eaten with a savory sauce."],["D","过油肉","Guòyóuròu","Guoyou rou","Slices of pork quickly fried in oil, then stir-fried with vegetables and vinegar, a Taiyuan classic."],["D","平遥牛肉","Píngyáo niúròu","Pingyao beef","Beef that is cured, simmered and pressed in Pingyao, with a tender texture and a rich flavor, and sold in the old town."],["D","汾酒","Fénjiǔ","Fenjiu","A famous clear baijiu from Shanxi that has been made for about 1,500 years, with a light and clean taste."],["C","晋剧","Jìnjù","Jin opera","The local opera of Shanxi, sung in the local dialect, with strong voices and lively music."],["C","面塑","Miànsù","Dough sculpting","Figures made of colored dough, from animals to opera heroes, a folk craft that is also used for festivals."],["C","晋商","Jìnshāng","Shanxi merchants","Shanxi merchants ran trading houses and early banks across China in the Ming and Qing dynasties, which made the province wealthy."]]},{"id":"datong","zh":"大同","py":"Dàtóng","en":"Datong","lat":40.09,"lon":113.3,"note":"A northern city known for caves and a hanging temple.","stops":[["A","云冈石窟","Yúngāng Shíkū","Yungang Grottoes","Giant Buddhist carvings from the fifth century, cut into a sandstone cliff near Datong. Some of the Buddhas are 17 meters high. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",40.11,113.13,1],["A","悬空寺","Xuánkōngsì","Hanging Temple","A temple stuck to a cliff face, held up by wooden posts, and it seems to hang in the air. It is about 1,500 years old and blends Buddhism, Taoism and Confucianism.","",39.67,113.7,1],["A","华严寺","Huáyánsì","Huayan Temple","One of the biggest wooden temples in China, built in the Liao and Jin dynasties, with huge halls and painted clay statues.","",40.09,113.29],["A","九龙壁","Jiǔlóngbì","Nine Dragon Wall","A glazed wall in Datong with nine colorful dragons, built in the Ming dynasty and bigger than the one in Beijing.","",40.09,113.3],["A","应县木塔","Yīngxiàn Mùtǎ","Yingxian Wooden Pagoda","The oldest and tallest wooden pagoda in China, 67 meters high, built in 1056 with no nails.","",39.56,113.18],["A","恒山","Héngshān","Mount Heng (North)","One of the Five Sacred Mountains of China, in the north, with temples built into the cliffs.","",39.68,113.72],["D","浑源凉粉","Húnyuán liángfěn","Hunyuan jelly","A cool jelly made from starch, served with chili, vinegar and herbs, a favorite summer snack."],["D","大同铜火锅","Dàtóng tóng huǒguō","Datong copper hot pot","A copper hotpot with a chimney in the center, heated with charcoal, an old Datong way to enjoy a meal in winter."],["D","黄花菜","Huánghuācài","Daylily","Daylily buds are dried and used in soups and stir-fries, a Datong specialty with a mild and sweet taste."]]},{"id":"pingyao","zh":"平遥","py":"Píngyáo","en":"Pingyao","lat":37.2,"lon":112.18,"note":"A walled town that was a banking center.","stops":[["A","平遥古城","Píngyáo Gǔchéng","Pingyao Ancient City","A Ming walled town with about 3,000 old buildings, courtyard houses and lanes. It was a center of banking in the Qing dynasty, and is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",37.2,112.18,1],["A","平遥城墙","Píngyáo Chéngqiáng","Pingyao City Wall","A Ming wall, about six kilometers around, that you can walk on, with watchtowers at regular intervals.","",37.2,112.18],["A","双林寺","Shuānglínsì","Shuanglin Temple","A temple with about 2,000 painted clay statues, some of the finest Buddhist sculpture in China.","",37.19,112.14],["A","镇国寺","Zhènguósì","Zhenguo Temple","A temple with a wooden hall built in the 10th century, one of the oldest in China.","",37.25,112.19],["D","平遥碗托","Píngyáo wǎntuō","Pingyao wantuo","A cool jelly made from buckwheat, sliced and served with garlic, vinegar and chili, a common Pingyao snack."],["D","平遥推光漆器","Píngyáo tuīguāng qīqì","Pingyao pushed-light lacquer","Lacquerware that is polished by hand until it shines like a mirror, with painted gold designs, a Pingyao craft."],["C","票号","Piàohào","Piaohao banks","Piaohao were private banks of Pingyao in the Qing dynasty, which moved money across China by drafts."]]},{"id":"jinzhong","zh":"晋中","py":"Jìnzhōng","en":"Jinzhong","lat":37.69,"lon":112.75,"note":"A home of great merchant mansions.","stops":[["A","乔家大院","Qiáojiādà Yuàn","Qiao Family Compound","A big courtyard mansion of a merchant family, with 313 rooms and many courtyards. A famous film made it known worldwide.","",37.43,112.52],["A","王家大院","Wángjiā Dàyuàn","Wang Family Compound","A huge Qing complex of courtyards and carved gates, home of the Wang family, nicknamed the Forbidden City of the Loess Plateau.","",37.65,112.2],["A","常家庄园","Chángjiā Zhuāngyuán","Chang Family Manor","A merchant manor with gardens and halls that show how wealthy Shanxi merchants lived.","",37.62,112.78],["D","太谷饼","Tàigǔ bǐng","Taigu cake","A round, sweet cake with a crisp, flaky crust and sesame, a Taigu specialty that is carried as a gift."]]},{"id":"linfen","zh":"临汾","py":"Línfén","en":"Linfen","lat":36.09,"lon":111.52,"note":"A cradle of Chinese civilization along the Fen River.","stops":[["A","壶口瀑布","Húkǒu Pùbù","Hukou Waterfall","A waterfall where the Yellow River squeezes into a narrow gorge and plunges. This side belongs to Shanxi.","",36.14,110.43],["A","广胜寺","Guǎngshèngsì","Guangsheng Temple","A temple of the Yuan period with a fine glazed pagoda and old wall paintings.","",36.48,111.75],["D","临汾羊杂","Línfén yángzá","Linfen lamb offal","A hot, peppery soup of lamb organs, eaten with flatbread, a Linfen breakfast."]]},{"id":"yuncheng","zh":"运城","py":"Yùnchéng","en":"Yuncheng","lat":35.03,"lon":111.0,"note":"The hometown of the general Guan Yu.","stops":[["A","鹳雀楼","Guànquèlóu","Stork Tower","A tower on the bank of the Yellow River, made famous by a Tang poem that every Chinese child learns.","",34.82,110.28],["A","永乐宫","Yǒnglè Gōng","Yongle Palace","A Taoist temple with huge, remarkable Yuan-dynasty wall paintings of hundreds of immortals.","",34.62,110.6],["A","运城盐湖","Yùnchéng Yánhú","Yuncheng Salt Lake","A salt lake that turns pink in summer, due to algae and minerals, and has been a source of salt for thousands of years.","",35.0,111.0],["D","运城羊肉泡馍","Yùnchéng yángròu pàomó","Yuncheng lamb bun soup","A lamb soup with torn bread, much like the one in Xi'an, in a local style."],["D","稷山麻花","Jìshān máhuā","Jishan twists","Fried dough twists from Jishan, crisp and sweet, sold as snacks and gifts."]]},{"id":"changzhi","zh":"长治","py":"Chángzhì","en":"Changzhi","lat":36.2,"lon":113.12,"note":"A highland city on the Taihang range.","stops":[["A","太行山大峡谷","Tàihángshān Dàxiágǔ","Taihang Grand Canyon","Deep gorges in the Taihang Mountains, with red cliffs, waterfalls and paths that cling to the rock.","",36.3,113.9],["D","潞酒","Lùjiǔ","Lu liquor","A local liquor of Changzhi with a history of centuries."]]},{"id":"jincheng","zh":"晋城","py":"Jìnchéng","en":"Jincheng","lat":35.49,"lon":112.85,"note":"A coal city with old stone houses.","stops":[["A","皇城相府","Huángchéng Xiāngfǔ","Huangcheng Xiangfu","A walled mansion of a Qing official with many courtyards and watchtowers, a showpiece of old Shanxi architecture.","",35.57,112.45],["D","陵川黑猪肉","Língchuān hēi zhūròu","Lingchuan black pork","A local breed of black pig, known for its tender meat and rich flavor."]]},{"id":"lvliang","zh":"吕梁","py":"Lǚliáng","en":"Lüliang","lat":37.52,"lon":111.14,"note":"A mountain city on the Yellow River.","stops":[["D","吕梁红枣","Lǚliáng hóngzǎo","Lüliang red jujube","Sweet red dates grown along the Yellow River in Lüliang, eaten fresh or dried."],["D","柳林碗托","Liǔlín wǎntuō","Liulin wantuo","A cool jelly made from starch, topped with a spicy sauce, a local version of the snack."]]},{"id":"xinzhou","zh":"忻州","py":"Xīnzhōu","en":"Xinzhou","lat":38.42,"lon":112.73,"note":"A north Shanxi city beside the Wutai holy mountain.","stops":[["A","五台山","Wǔtáishān","Mount Wutai","One of the four sacred Buddhist mountains, dedicated to Manjushri, with dozens of temples among its five flat peaks. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",39.02,113.58],["A","南禅寺","Nánchánsì","Nanchan Temple","A small Tang-dynasty hall, from 782 CE, the oldest surviving wooden building in China.","Said to date to 782 CE.",38.82,112.97],["A","雁门关","Yànménguān","Yanmen Pass","A frontier pass on the Great Wall, set in the hills and a gate to the north, with strong walls.","",39.2,112.9],["D","忻州瓦酥","Xīnzhōu wǎsū","Xinzhou wasu pastry","A flaky pastry shaped like roof tiles, which are crisp and sweet."],["D","原平锅盔","Yuánpíng guōkuī","Yuanping guokui","A big baked flatbread, thick and crunchy, that was a travelers' food, and is still liked as a snack."]]}],"air":{"zh":"太原武宿国际机场","py":"Tàiyuán Wǔsù Guójì Jīchǎng","en":"Taiyuan Wusu International Airport","code":"TYN","lat":37.75,"lon":112.63,"note":"The main airport of Shanxi. Welcome to Shanxi."}},{"id":"sichuan","zh":"四川","py":"Sìchuān","en":"Sichuan","cities":[{"id":"chengdu","zh":"成都","py":"Chéngdū","en":"Chengdu","lat":30.67,"lon":104.07,"note":"Sichuan’s capital: pandas, teahouses and spicy food.","stops":[["A","大熊猫繁育研究基地","Dàxióngmāo Fánzhí Yánjiū Jīdì","Giant Panda Breeding Base","Giant pandas live among bamboo groves just outside Chengdu, where you can watch them munch, climb and nap. Early morning is when they are most active.","",30.74,104.14,1],["A","宽窄巷子","Kuān-Zhǎi Xiàngzi","Wide and Narrow Alleys","Three parallel lanes of old courtyard houses from the Qing dynasty, now filled with teahouses, snack shops and small galleries.","",30.67,104.05],["A","锦里","Jǐnlǐ","Jinli Ancient Street","A lantern-lit old street next to the Wuhou Shrine, with snack stalls, craft shops and tea houses in the style of the Three Kingdoms.","",30.65,104.05],["A","武侯祠","Wǔhóu Cí","Wuhou Shrine","A temple for Zhuge Liang, the brilliant strategist of the Three Kingdoms, which is also a shrine for his lord Liu Bei, set among cypress trees.","",30.65,104.05],["A","杜甫草堂","Dùfǔ Cǎotáng","Du Fu Thatched Cottage","The simple home where the Tang poet Du Fu lived for four years, now a peaceful garden with bamboo, ponds and a museum.","",30.66,104.03],["A","都江堰","Dūjiāngyàn","Dujiangyan irrigation system","An irrigation system begun around 256 BC that still waters the Chengdu plain. It splits a river without a dam, and still works after more than 2,000 years.","It irrigates the Chengdu plain without a dam, and has done for more than 2,200 years.",31.0,103.62,1],["A","青城山","Qīngchéng Shān","Mount Qingcheng","A Taoist mountain covered in green forest and temples, one of the birthplaces of Taoism, and quiet and cool in summer.","",30.9,103.57],["A","春熙路","Chūnxī Lù","Chunxi Road","Chengdu's big pedestrian shopping street, with department stores and fashion shops, and a lively place in the evening.","",30.66,104.08],["A","鹤鸣茶社","Hèmíng Cháshè","Heming Teahouse","A well-known teahouse in People's Park, where people sit in bamboo chairs, sip tea and chat all afternoon, and ear cleaners go from table to table.","",30.66,104.06],["D","麻婆豆腐","Mápó dòufu","Mapo tofu","Soft tofu and minced beef in a bright red, hot and numbing sauce of chili bean paste and Sichuan pepper. It was created in Chengdu in the 19th century.","\"Mapo\" is said to mean a pockmarked grandmother, after the woman who first made it.",null,null,1],["D","回锅肉","Huíguōròu","Twice-cooked pork","Pork belly boiled, sliced and stir-fried with chili bean paste and leeks. It is often called the soul of Sichuan cooking."],["D","宫保鸡丁","Gōngbǎo jīdīng","Kung pao chicken","Diced chicken with peanuts and dried chilies, in a sweet, sour and spicy sauce, said to be named after a Qing official."],["D","夫妻肺片","Fūqī fèipiàn","Husband-and-wife beef slices","Cold sliced beef and beef offal in a spicy chili-oil sauce with peanuts and herbs, with an old Chengdu street-food story."],["D","鱼香肉丝","Yúxiāng ròusī","Fish-fragrant shredded pork","Shredded pork with wood-ear mushrooms in a sweet, sour and spicy sauce that was originally used for fish. There is no fish in it.","There is no fish in it. The name refers to a sauce style once used for cooking fish."],["D","抄手","Chāoshǒu","Sichuan wontons","Sichuan wontons, whose name means folded hands, are served in broth or in a red chili-oil sauce."],["D","赖汤圆","Lài tāngyuán","Lai glutinous rice balls","Chewy glutinous rice balls with a sweet sesame or bean filling, served in a warm broth, a century-old Chengdu snack."],["D","蛋烘糕","Dànhōnggāo","Egg pancake","A thin, soft, pan-fried pancake folded around a sweet or savory filling, a Chengdu street snack."],["D","钟水饺","Zhōng shuǐjiǎo","Zhong dumplings","Dumplings in a sweet and spicy red-oil sauce, from a shop that has been selling them for around 100 years."],["D","甜水面","Tiánshuǐ miàn","Sweet-water noodles","Thick noodles in a sweet and savory sauce of soy, garlic and sesame, a classic Chengdu snack."],["D","串串香","Chuànchuànxiāng","Skewer hotpot","Skewers dipped into a bubbling, spicy pot. You pay by counting the empty sticks at the end of the meal."],["C","盖碗茶","Gàiwǎnchá","Lidded-bowl tea","Tea served in a bowl with a lid and a saucer, a fixture of Chengdu teahouses, where you can sit for hours with refills."],["C","川剧变脸","Chuānjù biànliǎn","Face-changing in Sichuan opera","Performers in Sichuan opera swap painted masks in the blink of an eye, with a wave of a fan or a sweep of a cloak, and their secrets are closely guarded.","",null,null,1],["C","蜀绣","Shǔxiù","Sichuan embroidery","Sichuan embroidery uses very fine stitches and silk threads, often to depict pandas, flowers and fish, one of the four great styles of Chinese embroidery."],["C","蜀锦","Shǔjǐn","Shu brocade","A brocade woven in Chengdu since ancient times and traded along the Silk Road, famed for its rich colors and patterns."],["C","郫县豆瓣","Píxiàn dòubàn","Pixian chili bean paste","A fermented paste of broad beans and chili from Pixian, the essential base of Sichuan cooking, deep red and savory.","",30.8,103.89]]},{"id":"zigong","zh":"自贡","py":"Zìgòng","en":"Zigong","lat":29.34,"lon":104.78,"note":"A salt-making city, also known for lanterns and dinosaur fossils.","stops":[["D","担担面","Dàndànmiàn","Dandan noodles","Noodles with chili oil, minced pork and preserved vegetables. The name comes from vendors who carried the noodles on a shoulder pole."],["D","冷吃兔","Lěngchītù","Cold-eaten rabbit","Rabbit pieces cooked dry with chilies and spices, then eaten cold. A famous snack from Zigong."],["C","自贡灯会","Zìgòng Dēnghuì","Zigong Lantern Festival","Giant lantern figures, such as dinosaurs and dragons, light up Zigong around the Spring Festival, in one of the biggest lantern shows in China."]]},{"id":"leshan","zh":"乐山","py":"Lèshān","en":"Leshan","lat":29.57,"lon":103.77,"note":"Where three rivers meet below a giant Buddha.","stops":[["A","乐山大佛","Lèshān Dàfó","Leshan Giant Buddha","A 71-meter Buddha carved into a cliff where three rivers meet. The carving took about 90 years in the Tang dynasty, and is a UNESCO World Heritage Site.","Carving took roughly 90 years, and it was begun to calm the dangerous rivers below.",29.54,103.77,1],["A","峨眉山","Éméi Shān","Mount Emei","One of China's four sacred Buddhist mountains, with temples, misty forests and mischievous monkeys on the way up.","",29.57,103.33],["A","峨眉山金顶","Éméi Shān Jīndǐng","Golden Summit of Mount Emei","The top of Mount Emei, where people come for sunrises, a sea of clouds and a gilded temple with a big golden statue.","",29.52,103.33],["D","棒棒鸡","Bàngbàngjī","Bang bang chicken","Cold shredded chicken in a sesame and chili sauce. The name comes from beating the cooked chicken with a stick to make it tender."],["D","钵钵鸡","Bōbōjī","Bobo chicken","Chicken and other skewered food that is served cold in a bowl of spicy red oil, a Leshan snack."],["D","翘脚牛肉","Qiáojiǎo niúròu","Qiaojiao beef soup","A peppery beef and offal soup, served with vegetables and noodles, a Leshan specialty."],["D","西坝豆腐","Xībà dòufu","Xiba tofu","Tofu from the Xiba district fried and grilled until crisp outside and soft inside, and eaten with a dipping sauce."]]},{"id":"deyang","zh":"德阳","py":"Déyáng","en":"Deyang","lat":31.13,"lon":104.4,"note":"The city next to the Sanxingdui ruins.","stops":[["A","三星堆","Sānxīngduī","Sanxingdui","A Bronze Age site where giant bronze masks with bulging eyes and a golden mask were found, from a mysterious ancient kingdom that left no writing.","Its bronze masks have bulging eyes and a few are taller than a person.",31.0,104.24,1],["C","绵竹年画","Miánzhú niánhuà","Mianzhu New Year prints","Colorful woodblock prints from Mianzhu, hung on doors at the Spring Festival to bring luck.","",31.34,104.22],["C","剑南春","Jiànnánchūn","Jiannanchun baijiu","A well-known Sichuan baijiu, made in Mianzhu with a long history that goes back to the Tang dynasty.","",31.34,104.22]]},{"id":"mianyang","zh":"绵阳","py":"Miányáng","en":"Mianyang","lat":31.47,"lon":104.68,"note":"Sichuan’s second-biggest city by many counts, a science and technology centre.","stops":[["D","绵阳米粉","Miányáng mǐfěn","Mianyang rice noodles","Rice noodles in a rich, spicy beef broth, a Mianyang breakfast favorite."]]},{"id":"guangyuan","zh":"广元","py":"Guǎngyuán","en":"Guangyuan","lat":32.44,"lon":105.84,"note":"A northern Sichuan city on the old road to Shaanxi.","stops":[["D","蒸凉面","Zhēng liángmiàn","Steamed cold noodles","Steamed noodles served cool with chili oil, vinegar and garlic, a refreshing dish from Guangyuan."]]},{"id":"nanchong","zh":"南充","py":"Nánchōng","en":"Nanchong","lat":30.84,"lon":106.11,"note":"A city on the Jialing River, home to the old town of Langzhong.","stops":[["A","阆中古城","Làngzhōng Gǔchéng","Langzhong Ancient City","A well-preserved old town on a bend of the Jialing River, with Tang and Song layout, courtyard houses, and a gate tower.","",31.55,105.97],["D","张飞牛肉","Zhāng Fēi niúròu","Zhang Fei beef","Spiced, air-dried beef from Langzhong, named after the Three Kingdoms general Zhang Fei."]]},{"id":"yibin","zh":"宜宾","py":"Yíbīn","en":"Yibin","lat":28.77,"lon":104.64,"note":"Where the Yangtze begins, at the meeting of the Jinsha and Min rivers.","stops":[["D","宜宾燃面","Yíbīn ránmiàn","Yibin burning noodles","Oily, spicy noodles that were said to burn if you light them, from Yibin's streets."],["D","李庄白肉","Lǐzhuāng báiròu","Lizhuang white pork","Thinly sliced boiled pork rolled around a garlic and chili sauce, a classic of Lizhuang."],["C","五粮液","Wǔliángyè","Wuliangye baijiu","A famous baijiu made from five grains in Yibin, which is one of the most valued liquors in China.","",28.76,104.58]]},{"id":"luzhou","zh":"泸州","py":"Lúzhōu","en":"Luzhou","lat":28.87,"lon":105.44,"note":"A river city famous for its liquor.","stops":[]},{"id":"yaan","zh":"雅安","py":"Yǎ’ān","en":"Ya’an","lat":29.98,"lon":103.01,"note":"A rainy city in western Sichuan, known for tea and pandas.","fun":"Ya’an is nicknamed the Rain City for its many wet days.","stops":[["D","雅鱼","Yǎyú","Ya fish","A cold-water fish from the rivers of Ya'an, cooked in a spicy broth, a local delicacy."],["C","花椒","Huājiāo","Sichuan pepper","The spice that makes your mouth tingle. Hanyuan County is famous for it, and cooks across Sichuan use it.","Sichuan pepper is not a chili. Its tingle comes from a different compound, so it feels numb rather than hot.",29.35,102.65]]},{"id":"garze","zh":"康定","py":"Kāngdìng","en":"Kangding","lat":30.05,"lon":101.96,"note":"The seat of Garze Prefecture, where Han and Tibetan cultures meet.","stops":[["A","海螺沟","Hǎiluógōu","Hailuogou Glacier Park","A glacier that flows down into a forest, with hot springs nearby, a place where ice meets greenery.","",29.58,101.99],["A","稻城亚丁","Dàochéng Yàdīng","Daocheng Yading","Three snow peaks in a remote Tibetan valley, with blue lakes and wide meadows, often called the last Shangri-La.","",28.43,100.33],["D","酥油茶","Sūyóuchá","Butter tea","Tea churned with yak butter and salt, a daily Tibetan drink that keeps people warm at altitude."],["D","糌粑","Zānba","Tsampa","Roasted barley flour mixed with butter tea and kneaded by hand, a Tibetan staple."]]},{"id":"aba","zh":"阿坝州","py":"Ābà Zhōu","en":"Aba Prefecture","lat":31.9,"lon":102.22,"note":"A mountain prefecture in north-west Sichuan with Tibetan and Qiang communities.","stops":[["A","九寨沟","Jiǔzhàigōu","Jiuzhaigou Valley","Turquoise lakes, terraced waterfalls and forests in a valley of Tibetan villages. The name means Nine Village Valley, and it is a UNESCO World Heritage Site.","",33.26,103.92,1],["A","黄龙","Huánglóng","Huanglong","Terraced pools of golden limestone that wind down a valley, said to look like a yellow dragon, and are a UNESCO World Heritage Site.","",32.75,103.83],["A","四姑娘山","Sìgūniang Shān","Mount Siguniang","A range of snowy peaks with grasslands and glacier valleys, nicknamed the Oriental Alps.","",31.1,102.9],["A","松潘古城","Sōngpān Gǔchéng","Songpan Ancient Town","An old frontier town with walls and gates, a base for horse treks into the mountains.","",32.64,103.6],["C","青稞酒","Qīngkējiǔ","Highland barley wine","A Tibetan drink brewed from highland barley, slightly sweet and sour, served at festivals."]]},{"id":"liangshan","zh":"西昌","py":"Xīchāng","en":"Xichang","lat":27.89,"lon":102.26,"note":"The seat of Liangshan Prefecture, known for its sunshine.","stops":[["C","火把节","Huǒbǎjié","Torch Festival","The Yi people's festival of fire, wrestling and dancing, with torches carried through the fields at night, to drive away evil.","",27.89,102.26],["C","彝族漆器","Yízú qīqì","Yi lacquerware","Wooden bowls and cups painted in red, black and yellow in traditional Yi patterns, a craft of the Liangshan area.","",27.89,102.26]]},{"id":"panzhihua","zh":"攀枝花","py":"Pānzhīhuā","en":"Panzhihua","lat":26.58,"lon":101.72,"note":"A sunny steel city in the south of Sichuan, named for the kapok flower.","stops":[["D","攀枝花芒果","Pānzhīhuā mángguǒ","Panzhihua mangoes","Sweet mangoes grown in the warm, dry valleys of Panzhihua, which ripen early in the year."]]},{"id":"meishan","zh":"眉山","py":"Méishān","en":"Meishan","lat":30.08,"lon":103.85,"note":"The hometown of the Song poet Su Shi.","stops":[["D","东坡肘子","Dōngpō zhǒuzi","Dongpo braised pork knuckle","A rich braised pork knuckle named for the poet Su Dongpo, who was born in Meishan."]]},{"id":"dazhou","zh":"达州","py":"Dázhōu","en":"Dazhou","lat":31.21,"lon":107.47,"note":"A city in the east of Sichuan, on the road to Chongqing.","stops":[["D","灯影牛肉","Dēngyǐng niúròu","Lamp-shadow beef","Beef sliced so thin you could see a lamp through it, then dried and spiced, a Dazhou specialty."]]},{"id":"neijiang","zh":"内江","py":"Nèijiāng","en":"Neijiang","lat":29.58,"lon":105.06,"note":"Called the sweet city, for its sugar-cane history.","stops":[]},{"id":"guangan","zh":"广安","py":"Guǎng’ān","en":"Guang’an","lat":30.46,"lon":106.63,"note":"A city in eastern Sichuan, hometown of Deng Xiaoping.","stops":[]},{"id":"chongqing","zh":"重庆","py":"Chóngqìng","en":"Chongqing","lat":29.56,"lon":106.55,"note":"A mountain city on two rivers, with towers, bridges and steep stairs.","stops":[["A","解放碑","Jiěfàngbēi","Jiefangbei","The central pedestrian district of Chongqing, around a tall monument, with shops and restaurants.","",29.56,106.58],["A","洪崖洞","Hóngyádòng","Hongyadong","A cliffside block of stilted buildings that glows at night above the Jialing River, which looks like a scene from a fantasy film.","The stilted-house style (diaojiaolou) is traditional in the Chongqing hills.",29.56,106.58],["A","磁器口古镇","Cíqìkǒu Gǔzhèn","Ciqikou Ancient Town","An old river port of stone lanes, teahouses and snack stalls, with a taste of old Chongqing.","",29.58,106.45],["A","李子坝轻轨站","Lǐzibà Qīngguǐ Zhàn","Liziba Station","A light-rail line that runs straight through an apartment block, which has become a symbol of Chongqing's vertical city.","The train runs through the middle of an apartment building, and is a famous photo spot.",29.54,106.53],["A","长江索道","Chángjiāng Suǒdào","Yangtze River Cableway","A cable car across the Yangtze, which gives views of the city's skyline and the river below.","",29.56,106.58],["D","重庆火锅","Chóngqìng huǒguō","Chongqing hotpot","A bubbling pot of beef tallow, chilies and Sichuan pepper, in which you cook meat, tripe and vegetables. This fiery meal is the pride of Chongqing.","",null,null,1],["D","重庆小面","Chóngqìng xiǎomiàn","Chongqing noodles","A spicy, numbing bowl of noodles that many locals eat for breakfast, with a rich, oily sauce."],["D","酸辣粉","Suānlàfěn","Hot and sour sweet-potato noodles","Glass noodles made of sweet potato starch in a sour and spicy broth with peanuts and chili oil."],["D","毛血旺","Máoxuèwàng","Mao xue wang","Duck blood, tripe and other ingredients simmered in a very spicy broth, a Chongqing classic."],["D","水煮鱼","Shuǐzhǔyú","Water-boiled fish","Fish slices poached in a layer of hot chili oil, with bean sprouts. It is said to have started in Chongqing."],["D","酸菜鱼","Suāncàiyú","Fish with pickled mustard greens","Fish in a sour and peppery broth with pickled mustard greens, a favorite family dish."],["D","歌乐山辣子鸡","Gēlèshān làzǐjī","Geleshan spicy chicken","Chicken pieces buried in a heap of dried chilies, from Gele Mountain, where you hunt for the pieces.","",29.58,106.43],["D","豆花饭","Dòuhuāfàn","Soft tofu with rice","Soft tofu eaten with rice and a spicy dipping sauce, a simple, filling Chongqing meal."],["D","糍粑","Cíbā","Glutinous rice cake","Sticky rice cakes rolled in brown sugar and soy flour, a sweet snack."],["C","江湖菜","Jiānghúcài","Jianghu cuisine","Bold, home-style dishes that began in small riverside restaurants, and are cooked with strong flavors."],["C","川江号子","Chuānjiāng hàozi","Chuanjiang boatmen’s chants","Work songs sung by boat trackers on the upper Yangtze, with a rhythm that matched the hauling of boats."]],"muni":"Chongqing"},{"id":"dazu","zh":"大足","py":"Dàzú","en":"Dazu","lat":29.7,"lon":105.72,"note":"A district known for its carved cliffs.","stops":[],"muni":"Chongqing"},{"id":"wulong","zh":"武隆","py":"Wǔlóng","en":"Wulong","lat":29.33,"lon":107.76,"note":"A district of caves, gorges and natural bridges.","stops":[],"muni":"Chongqing"},{"id":"fengjie","zh":"奉节","py":"Fèngjié","en":"Fengjie","lat":31.02,"lon":109.46,"note":"A Yangtze town at the entrance to the Three Gorges.","stops":[["A","白帝城","Báidìchéng","Baidicheng","A temple on a hill at the head of the Three Gorges, famous in poems by Li Bai and Du Fu.","",31.04,109.58],["A","瞿塘峡","Qútáng Xiá","Qutang Gorge","The first and shortest of the Three Gorges, with steep cliffs on both sides of the river.","",31.03,109.55],["D","奉节脐橙","Fèngjié qíchéng","Fengjie navel oranges","Sweet navel oranges grown on the hills above the Yangtze, harvested in winter."]],"muni":"Chongqing"},{"id":"wushan","zh":"巫山","py":"Wūshān","en":"Wushan","lat":31.07,"lon":109.88,"note":"A town at the Wu Gorge, one of the Three Gorges.","stops":[["D","巫山脆李","Wūshān cuìlǐ","Wushan crisp plums","Crunchy, sweet plums that grow on the slopes of Wushan, picked in early summer."]],"muni":"Chongqing"},{"id":"fuling","zh":"涪陵","py":"Fúlíng","en":"Fuling","lat":29.7,"lon":107.39,"note":"A city where the Wu and Yangtze rivers meet.","stops":[["D","涪陵榨菜","Fúlíng zhàcài","Fuling pickled mustard tuber","A salty, spicy pickle made from mustard tuber, which is a famous export of Fuling, enjoyed with congee."]],"muni":"Chongqing"},{"id":"youyang","zh":"酉阳","py":"Yǒuyáng","en":"Youyang","lat":28.84,"lon":108.77,"note":"A mountain county with Tujia and Miao communities.","stops":[],"muni":"Chongqing"},{"id":"beibei","zh":"北碚","py":"Běibèi","en":"Beibei","lat":29.8,"lon":106.44,"note":"A district on the Jialing River, known for hot springs and hills.","stops":[],"muni":"Chongqing"},{"id":"nanchuan","zh":"南川","py":"Nánchuān","en":"Nanchuan","lat":29.16,"lon":107.1,"note":"A district in the south of Chongqing, on the way to Jinfo Mountain.","stops":[],"muni":"Chongqing"},{"id":"rongchang","zh":"荣昌","py":"Róngchāng","en":"Rongchang","lat":29.4,"lon":105.59,"note":"A district known for its crafts and its pigs.","stops":[["D","荣昌烤鹅","Róngchāng kǎo’é","Rongchang roast goose","Crisp roast goose from Rongchang, a local specialty, with juicy meat."]],"muni":"Chongqing"},{"id":"fengdu","zh":"丰都","py":"Fēngdū","en":"Fengdu","lat":29.86,"lon":107.73,"note":"A Yangtze town linked to ghost stories.","stops":[["A","丰都鬼城","Fēngdū Guǐchéng","Fengdu Ghost City","A hill covered in temples and statues about the afterlife, a place of folklore and legends.","",29.87,107.73],["D","丰都麻辣鸡块","Fēngdū málà jīkuài","Fengdu spicy chicken pieces","Chicken chopped small and cooked with a heap of chilies and Sichuan pepper, a spicy specialty of Fengdu."]],"muni":"Chongqing"},{"id":"zhongxian","zh":"忠县","py":"Zhōngxiàn","en":"Zhong County","lat":30.3,"lon":108.04,"note":"A Yangtze county with a famous temple on a rock.","stops":[["A","石宝寨","Shíbǎozhài","Shibaozhai","A wooden temple tower built up the side of a rock beside the Yangtze, like a multi-story pagoda.","",30.41,108.17],["D","忠州豆腐乳","Zhōngzhōu dòufǔrǔ","Zhongzhou fermented tofu","A savory fermented tofu with a long local history, used to flavor rice and vegetables."]],"muni":"Chongqing"},{"id":"jiangjin","zh":"江津","py":"Jiāngjīn","en":"Jiangjin","lat":29.29,"lon":106.26,"note":"A Yangtze-side district south-west of the city centre.","stops":[["D","江津青花椒","Jiāngjīn qīnghuājiāo","Jiangjin green Sichuan pepper","A bright, numbing green Sichuan pepper grown around Jiangjin, with a fresh fragrance."]],"muni":"Chongqing"},{"id":"wanzhou","zh":"万州","py":"Wànzhōu","en":"Wanzhou","lat":30.81,"lon":108.41,"note":"A big river port on the Yangtze in the east of Chongqing.","stops":[["D","万州烤鱼","Wànzhōu kǎoyú","Wanzhou grilled fish","Fish grilled whole, then simmered in a spicy sauce with vegetables, a famed dish of Wanzhou."]],"muni":"Chongqing"}],"hue":8,"munis":{"Chongqing":"Chongqing is a municipality in its own right, directly under the national government, not a part of Sichuan. It was split from Sichuan in 1997 and sits next to it, so it is visited here."},"air":{"zh":"成都天府国际机场","py":"Chéngdū Tiānfǔ Guójì Jīchǎng","en":"Chengdu Tianfu International Airport","code":"TFU","lat":30.32,"lon":104.44,"note":"The newer of Chengdu's two big airports, opened in 2021. Welcome to Sichuan."}},{"id":"singapore","zh":"新加坡","py":"Xīnjiāpō","en":"Singapore","cities":[{"id":"singapore-central","zh":"新加坡中心","py":"Xīnjiāpō Zhōngxīn","en":"Central Singapore","lat":1.29,"lon":103.85,"note":"The downtown, with the skyline, river and Chinatown.","stops":[["A","鱼尾狮公园","Yúwěishī Gōngyuán","Merlion Park","A fountain of the Merlion, a half-lion, half-fish figure that is the symbol of Singapore, spouting water into the bay in front of the city skyline.","",1.29,103.85,1],["A","滨海湾金沙","Bīnhǎi Wān Jīnshā","Marina Bay Sands","A hotel of three towers topped by a ship-shaped rooftop with an infinity pool and a view across Marina Bay.","",1.28,103.86],["A","滨海湾花园","Bīnhǎi Wān Huāyuán","Gardens by the Bay","A garden by the bay with giant Supertrees, steel tree-like structures covered in plants, that light up at night. Two glass domes hold cool-weather plants.","",1.28,103.86,1],["A","牛车水","Niúchēshuǐ","Chinatown","Chinatown is an old district of shophouses, temples and food stalls, with lanterns and busy markets.","",1.28,103.84],["A","佛牙寺龙华院","Fóyá Sì Lónghuá Yuàn","Buddha Tooth Relic Temple","A large temple in Tang-dynasty style that houses a relic said to be a tooth of the Buddha.","",1.28,103.84],["A","小印度","Xiǎo Yìndù","Little India","A colorful area of Indian shops, temples and restaurants, with garlands, spices, silk and the smell of curry.","",1.31,103.85],["A","甘榜格南","Gānbǎng Génán","Kampong Glam","The Malay quarter of Singapore, with Arab Street, textile shops, cafés and the Sultan Mosque.","",1.3,103.86],["A","苏丹回教堂","Sūdān Huí Jiàotáng","Sultan Mosque","A mosque with a golden dome, the biggest in Singapore, and the heart of the Malay-Muslim community.","",1.3,103.86],["A","新加坡河","Xīnjiāpō Hé","Singapore River","The river where Singapore's trade began, lined with old warehouses that are now restaurants and bars, and crossed by bridges.","",1.29,103.85],["A","乌节路","Wūjié Lù","Orchard Road","A famous shopping street with malls, department stores and fashion brands, lit up in bright festive lights at Christmas.","",1.3,103.83],["A","新加坡国家博物馆","Xīnjiāpō Guójiā Bówùguǎn","National Museum of Singapore","The oldest museum in the country, with a neoclassical building, which tells the story of Singapore from its early days.","",1.3,103.85],["A","新加坡植物园","Xīnjiāpō Zhíwùyuán","Singapore Botanic Gardens","A garden of old trees, lakes and orchids, a UNESCO World Heritage Site, and the only tropical garden with this status.","",1.31,103.82],["A","莱佛士酒店","Láifúshì Jiǔdiàn","Raffles Hotel","A colonial hotel, opened in 1887, where the Singapore Sling cocktail was created. It is a white building with palms and verandas.","",1.29,103.85],["D","海南鸡饭","Hǎinán jīfàn","Hainanese chicken rice","Poached chicken with rice cooked in chicken stock, with chili, ginger and dark soy. It is considered the national dish of Singapore.","",null,null,1],["D","辣椒螃蟹","Làjiāo pángxiè","Chili crab","A whole crab stir-fried in a sweet and spicy tomato-chili sauce, with an egg ribbon. You eat it with your hands, and use fried buns to soak up the sauce.","",null,null,1],["D","叻沙","Lèshā","Laksa","A coconut curry noodle soup with prawns, fish cake and cockles, a Peranakan classic."],["D","咖椰吐司","Kāyē tǔsī","Kaya toast","Toast with coconut jam and butter, served with soft-boiled eggs and sweet coffee, a traditional breakfast."],["D","肉骨茶","Ròugǔ chá","Bak kut teh","Pork rib soup with lots of pepper and garlic, eaten with rice and fried dough, in a rich, peppery broth."],["D","炒粿条","Chǎoguǒtiáo","Char kway teow","Flat rice noodles fried over high heat with egg, cockles, Chinese sausage and sweet soy sauce, with a smoky aroma."],["D","沙爹","Shādiē","Satay","Skewers of marinated meat grilled over charcoal and served with a peanut sauce, rice cakes and cucumber."],["D","福建面","Fújiàn miàn","Hokkien mee","Egg and rice noodles stir-fried with prawns, squid and pork in a rich shrimp stock."],["D","煎蚝","Jiānháo","Oyster omelet","A crispy omelet of oysters, egg and starch, served with chili sauce. A favorite hawker dish."],["D","新加坡司令","Xīnjiāpō sīlìng","Singapore Sling","A pink cocktail with gin, cherry liqueur and pineapple juice, which was first mixed at the Raffles Hotel."],["D","小贩中心","Xiǎofàn zhōngxīn","Hawker center","Open-air food courts with dozens of stalls offering cheap, delicious dishes. Singapore's hawker culture is on UNESCO's list of intangible heritage."],["C","多元文化","Duōyuán wénhuà","Multiculturalism","Chinese, Malay, Indian and other communities live side by side, and their festivals and foods are a part of daily life."],["C","新加坡式英语","Xīnjiāpō shì yīngyǔ","Singlish","Singlish is a local English mixed with Chinese, Malay and Tamil, with short sentences and the particle lah."],["C","国庆","Guóqìng","National Day","Singapore's National Day on August 9 is celebrated with parades, flypasts and fireworks over the bay."],["C","排灯节","Pái dēngjié","Deepavali","Deepavali is the Hindu festival of lights, when Little India is hung with lights and decorations."]]},{"id":"sentosa","zh":"圣淘沙","py":"Shèngtáoshā","en":"Sentosa","lat":1.25,"lon":103.83,"note":"A resort island south of the city.","stops":[["A","新加坡环球影城","Xīnjiāpō Huánqiú Yǐngchéng","Universal Studios Singapore","A theme park on Sentosa Island, with movie-themed rides and shows.","",1.25,103.83],["A","海洋馆","Hǎiyángguǎn","S.E.A. Aquarium","A large aquarium with thousands of sea animals, including a huge viewing window into an ocean habitat.","",1.26,103.82],["A","西乐索海滩","Xīlèsuǒ Hǎitān","Siloso Beach","A lively beach on Sentosa, with beach bars, volleyball courts and a view of passing ships.","",1.25,103.81]]},{"id":"east-coast","zh":"东海岸","py":"Dōnghǎi’àn","en":"East Coast","lat":1.31,"lon":103.93,"note":"A coast of beaches, seafood and Peranakan culture.","stops":[["A","东海岸公园","Dōnghǎi’àn Gōngyuán","East Coast Park","A long seaside park with cycling paths, beaches and seafood restaurants, a favorite place for weekend outings.","",1.3,103.91],["A","樟宜机场星耀樟宜","Zhāngyí Jīchǎng Xīngyàozhāngyí","Jewel Changi","A garden mall at Changi Airport, with a 40-meter indoor waterfall, known as the Rain Vortex, surrounded by trees and shops.","",1.36,103.99],["A","乌敏岛","Wūmǐndǎo","Pulau Ubin","A small island that keeps the old village life, where you can cycle on dirt paths through forests and mangroves.","",1.41,103.97],["D","娘惹糕","Niángrěgāo","Nyonya kueh","Colorful steamed cakes made of rice flour, coconut and pandan, the sweets of the Peranakan community."],["D","椰浆饭","Yējiāng fàn","Nasi lemak","Rice cooked in coconut milk and served with fried fish, anchovies, egg and spicy sambal, a Malay breakfast favorite."],["D","加东叻沙","Jiādōng lèshā","Katong laksa","A curry noodle soup from Katong, with short noodles that you can eat with a spoon alone."]]},{"id":"west","zh":"西部","py":"Xībù","en":"West Singapore","lat":1.34,"lon":103.72,"note":"A nature and science area.","stops":[["A","裕廊飞禽公园","Yùláng Fēiqín Gōngyuán","Jurong Bird Park","A bird park with thousands of colorful birds, including a large walk-in aviary and bird shows.","",1.32,103.71],["A","中华花园","Zhōnghuá Huāyuán","Chinese Garden","A garden of Chinese design with pagodas, bridges and a pond, a quiet place by the lake.","",1.34,103.73],["A","日本花园","Rìběn Huāyuán","Japanese Garden","A Japanese garden with stone paths, bridges and ponds, and quiet corners for rest.","",1.34,103.73],["A","南洋理工大学","Nányáng Lǐgōng Dàxué","Nanyang Technological University","A university with a modern campus, with large green spaces and an unusual building shaped like a stack of round plates.","",1.35,103.68]]},{"id":"north","zh":"北部","py":"Běibù","en":"North Singapore","lat":1.42,"lon":103.79,"note":"A green north with zoos and wetlands.","stops":[["A","新加坡动物园","Xīnjiāpō Dòngwùyuán","Singapore Zoo","A zoo where many animals live in open enclosures without bars, and visitors can have breakfast with orangutans.","",1.4,103.79],["A","夜间野生动物园","Yèjiān Yěshēng Dòngwùyuán","Night Safari","The world's first nocturnal zoo, where you can walk or ride a tram through dim forests to see animals that are awake at night.","",1.4,103.79],["D","榴莲","Liúlián","Durian","Durian is called the king of fruits, with a strong smell, a creamy flesh and a very sweet taste. It is banned on public transport in Singapore."]]}],"air":{"zh":"新加坡樟宜机场","py":"Xīnjiāpō Zhāngyí Jīchǎng","en":"Singapore Changi Airport","code":"SIN","lat":1.36,"lon":103.99,"note":"A famous airport with a huge indoor waterfall. Welcome to Singapore."}},{"id":"taiwan","zh":"台湾","py":"Táiwān","en":"Taiwan","cities":[{"id":"taipei","zh":"台北","py":"Táiběi","en":"Taipei","lat":25.03,"lon":121.57,"note":"The capital of Taiwan, a city of night markets and tea.","stops":[["A","台北101","Táiběi 101","Taipei 101","A tall tower with eight sections that recall a stalk of bamboo, once the tallest building in the world. A huge steel ball inside it steadies the tower in typhoons.","",25.03,121.56,1],["A","故宫博物院","Gùgōng Bówùyuàn","National Palace Museum","A museum with hundreds of thousands of imperial treasures, including jade, bronzes and paintings, that were moved from Beijing in the 1940s. A carved jade cabbage is among the favorites.","",25.1,121.55,1],["A","中正纪念堂","Zhōngzhèng Jìniàntáng","Chiang Kai-shek Memorial Hall","A white hall with a blue roof, set in a large square with gardens, with a hall that houses a statue of Chiang Kai-shek and a guard-changing ceremony.","",25.04,121.52],["A","龙山寺","Lóngshānsì","Longshan Temple","A temple in Taipei that is a center of folk faith, where worshippers burn incense to many gods, with carved dragons on the roof.","",25.04,121.5],["A","士林夜市","Shìlín Yèshì","Shilin Night Market","The largest night market in Taipei, with food stalls, games and shops. You can sample fried chicken, oyster omelets and sweet drinks until late.","",25.09,121.52,1],["A","九份","Jiǔfèn","Jiufen","A hillside town of old mining streets, tea houses and red lanterns, with views of the sea, said to have inspired a famous animated film.","",25.11,121.84],["A","十分瀑布","Shífēn Pùbù","Shifen Waterfall","A wide waterfall, called Taiwan's Niagara, near a railway town where people release sky lanterns.","",25.04,121.78],["A","淡水老街","Dànshuǐ Lǎojiē","Tamsui Old Street","A harbor town at the mouth of the Tamsui River, with an old street of snacks and a sunset view over the water.","",25.17,121.44],["A","阳明山","Yángmíngshān","Yangmingshan","A national park above Taipei with hot springs, flower fields and volcanic hills, which is spectacular in cherry blossom season.","",25.16,121.55],["A","西门町","Xīméntīng","Ximending","A pedestrian area of youth culture, with cinemas, shops, street performers and snacks.","",25.04,121.51],["A","北投温泉","Běitóu Wēnquán","Beitou Hot Springs","A hot spring district with steaming valleys, old bathhouses and a museum, a place to unwind in a warm bath.","",25.14,121.51],["D","牛肉面","Niúròumiàn","Taiwanese beef noodle soup","A bowl of beef noodle soup with chunks of braised beef in a spicy or clear broth. It is the island's unofficial national dish, with a yearly competition.","",null,null,1],["D","小笼包","Xiǎolóngbāo","Xiaolongbao","Soup dumplings made famous by a shop in Taipei. Thin-skinned and filled with broth, they are eaten with ginger and vinegar."],["D","卤肉饭","Lǔròufàn","Braised pork rice","Pork stewed in soy sauce and served over rice, a classic comfort food with a rich, sweet and savory taste."],["D","珍珠奶茶","Zhēnzhū nǎichá","Bubble tea","Milk tea with chewy tapioca pearls, first made in Taiwan in the 1980s. It is drunk through a wide straw, and has become popular around the world.","Two tea shops in Taiwan both claim to have invented it in the 1980s.",null,null,1],["D","臭豆腐","Chòudòufǔ","Stinky tofu","Fermented tofu fried until crisp, with a very strong smell and a savory flavor, served with pickled cabbage and chili."],["D","蚵仔煎","Hézǎijiān","Oyster omelet","A starchy omelet with small oysters, egg and greens, topped with sweet and spicy sauce, a night market favorite."],["D","凤梨酥","Fènglí sū","Pineapple cake","A shortbread pastry with pineapple jam, a Taiwanese gift that visitors take home."],["D","盐酥鸡","Yánsūjī","Salt and pepper chicken","Fried chicken bites with salt, pepper and basil, a night market snack."],["D","刨冰","Bàobīng","Shaved ice","Mountains of shaved ice with toppings such as mango, beans and condensed milk, a cool treat for summer."],["D","鸡排","Jīpái","Giant fried chicken cutlet","A giant fried chicken cutlet, bigger than a face, sprinkled with pepper, and eaten from a paper bag as you stroll."],["C","布袋戏","Bùdàixì","Glove puppetry","Glove puppetry, in which small, beautifully dressed puppets are moved by the hand, and act out martial-arts dramas."],["C","歌仔戏","Gēzǐxì","Taiwanese opera","Taiwanese opera, which grew out of folk songs, has love stories and heroic tales told in the Hokkien language."],["C","天灯","Tiāndēng","Sky lanterns","Paper lanterns with wishes written on them are released into the sky, and carry hopes and prayers."],["C","中元节","Zhōngyuánjié","Ghost Festival","The Ghost Festival in the seventh lunar month, when families make offerings of food and burn paper money for ancestors and wandering spirits."]]},{"id":"kaohsiung","zh":"高雄","py":"Gāoxióng","en":"Kaohsiung","lat":22.63,"lon":120.3,"note":"A southern port city and art hub.","stops":[["A","莲池潭龙虎塔","Liánchí Tán Lónghǔ Tǎ","Dragon and Tiger Pagodas","Two seven-story pagodas shaped like a dragon and a tiger stand by Lotus Pond. You enter through the dragon's mouth and exit through the tiger's for good luck.","",22.68,120.29],["A","佛光山","Fóguāngshān","Fo Guang Shan","A large Buddhist monastery with a huge Buddha statue and many halls, with a museum and vegetarian food.","",22.76,120.44],["A","旗津","Qíjīn","Cijin Island","A narrow island with seafood restaurants, a beach and a lighthouse, a short ferry ride from Kaohsiung.","",22.6,120.27],["A","六合夜市","Liùhé Yèshì","Liuhe Night Market","A famous night market in Kaohsiung, with seafood, papaya milk, grilled meat and other snacks.","",22.63,120.3],["A","美丽岛站","Měilì Dǎozhàn","Formosa Boulevard Station","A subway station with a huge glass dome, the Dome of Light, among the most beautiful in the world.","",22.63,120.3],["D","木瓜牛奶","Mùguā niúnǎi","Papaya milk","A sweet drink of papaya and milk, blended until it is smooth, a Kaohsiung favorite."],["D","烤乌鱼子","Kǎo wūyúzi","Grilled mullet roe","Mullet roe that is salted, dried and grilled, and is thinly sliced and eaten with garlic and radish, a delicacy."],["D","担仔面","Dānzǎimiàn","Danzi noodles","A small bowl of noodles with a savory sauce, shrimp and minced pork, a snack that first started with fishermen."],["D","棺材板","Guāncáibǎn","Coffin bread","Thick toast hollowed out and filled with a creamy seafood or chicken stew, a Tainan invention."]]},{"id":"tainan","zh":"台南","py":"Táinán","en":"Tainan","lat":23.0,"lon":120.23,"note":"The oldest city in Taiwan.","stops":[["A","赤崁楼","Chìkànlóu","Chihkan Tower","A building from the Dutch era with a Chinese-style roof, which was once the seat of Dutch rule in Tainan.","",22.99,120.2],["A","安平古堡","Ānpíng Gǔbǎo","Anping Fort","A fort built by the Dutch in the 17th century, with brick walls, and a view of the old harbor of Anping.","",23.0,120.16],["A","孔庙","Kǒngmiào","Tainan Confucius Temple","The first Confucius temple in Taiwan, built in 1665, in a quiet garden of old trees.","",22.99,120.2],["A","神农街","Shénnóng Jiē","Shennong Street","An old lane of old merchant houses, with lanterns, cafés and small shops, which is especially lovely in the evening.","",22.99,120.19],["D","度小月担仔面","Dùxiǎoyuè dānzǎimiàn","Du Xiao Yue noodles","A well-known noodle shop in Tainan that has been selling its small bowls of noodles since 1895."],["D","牛肉汤","Niúròutāng","Beef soup","A morning hot beef soup made with thin slices of fresh beef poured over with hot broth, a Tainan breakfast."],["D","鳝鱼意面","Shànyú yìmiàn","Eel noodles","Egg noodles stir-fried with eel in a sweet-sour sauce, a Tainan specialty."],["D","虱目鱼粥","Shīmùyú zhōu","Milkfish porridge","A porridge with milkfish, a typical Tainan breakfast, with a light flavor."]]},{"id":"taichung","zh":"台中","py":"Táizhōng","en":"Taichung","lat":24.15,"lon":120.67,"note":"A central city of art and bubble tea.","stops":[["A","彩虹眷村","Cǎihóng Juàncūn","Rainbow Village","A military dependents' village painted by a former soldier in bright colors and patterns, now an art spot.","",24.13,120.6],["A","高美湿地","Gāoměi Shīdì","Gaomei Wetlands","A tidal flat where the sunset reflects on shallow water, with windmills and birds on the horizon.","",24.31,120.55],["A","逢甲夜市","Féngjiǎ Yèshì","Fengjia Night Market","A big night market near a university in Taichung, known for creative snacks and cheap fashion.","",24.18,120.65],["D","太阳饼","Tàiyáng bǐng","Sun cake","A flaky pastry with a sweet malt filling, a Taichung specialty and a popular gift."]]},{"id":"hualien","zh":"花莲","py":"Huālián","en":"Hualien","lat":23.98,"lon":121.6,"note":"A gateway to the Taroko Gorge.","stops":[["A","太鲁阁","Tàilǔgé","Taroko Gorge","A marble canyon with cliff paths and tunnels cut into the rock, where a river has carved a deep gorge through the mountains. It is the best-known natural sight on the east coast.","",24.16,121.62,1],["A","花东纵谷","Huādōng Zònggǔ","East Rift Valley","A long valley of rice fields and farms between two mountain ranges, with a slow rhythm of country life.","",23.5,121.35],["D","麻糬","Máshǔ","Mochi","Chewy rice cakes rolled in peanut or sesame powder, a Hualien specialty."],["D","扁食","Biǎnshí","Bianshi","Wonton soup with thin skins and a clear broth, a local classic in Hualien."],["C","阿美族","Āměizú","Amis people","The largest Indigenous people on the east coast, known for their songs, dances and their harvest festivals."],["C","丰年祭","Fēngniánjì","Harvest Festival","A harvest festival of the Amis people, with singing, dancing and a feast to thank the ancestors."]]},{"id":"nantou","zh":"南投","py":"Nántóu","en":"Nantou","lat":23.91,"lon":120.69,"note":"The mountains and Sun Moon Lake.","stops":[["A","日月潭","Rìyuètán","Sun Moon Lake","A lake in the mountains, with a shape that looks like a sun on one side and a moon on the other. A cycling path circles the lake, and boats cross the water.","",23.86,120.92,1],["A","阿里山","Ālǐshān","Alishan","A mountain known for a sunrise above a sea of clouds, giant old cypress trees and a small mountain train.","",23.51,120.8],["A","玉山","Yùshān","Yushan","The highest mountain in Taiwan, at about 3,950 meters, whose summit is reached by a long hike.","",23.47,120.96],["A","清境农场","Qīngjìng Nóngchǎng","Qingjing Farm","A high-mountain farm with grasslands and sheep, with views of the mountains and a European feel.","",24.06,121.17],["D","高山茶","Gāoshān chá","High mountain tea","A tea grown at high altitude, where cool, misty weather gives it a sweet, smooth taste."],["D","阿里山茶","Ālǐshān chá","Alishan tea","A well-known oolong from the slopes of Alishan, with a floral aroma and a mellow taste."],["C","邵族","Shàozú","Thao people","A small Indigenous people who live around Sun Moon Lake, with their own language and customs."]]},{"id":"yilan","zh":"宜兰","py":"Yílán","en":"Yilan","lat":24.75,"lon":121.75,"note":"A rice and hot-spring county on the northeast coast.","stops":[["D","三星葱","Sānxīng cōng","Sanxing scallion","Scallions grown in the fertile soil of Sanxing in Yilan, thicker and sweeter than most."],["D","卜肉","Boròu","Bourou","Fried pork rolls, crisp outside and juicy inside, a local snack in Yilan."]]},{"id":"taitung","zh":"台东","py":"Táidōng","en":"Taitung","lat":22.76,"lon":121.14,"note":"A laid-back southeast coast.","stops":[["A","兰屿","Lányǔ","Orchid Island","An island off the southeast coast, home of the Tao people, with traditional boats and flying fish festivals.","",22.05,121.55],["D","释迦","Shìjiā","Sugar apple","The sugar apple is a sweet, creamy fruit with a bumpy green skin, a Taitung specialty."],["D","池上饭包","Chíshàng fànbāo","Chishang lunchbox","A famous railway lunchbox of rice, pork and pickles, which is sold at Chishang station."],["C","达悟族","Dáwùzú","Tao people","An island people of Orchid Island, known for their flying fish traditions and their carved boats."]]},{"id":"pingtung","zh":"屏东","py":"Píngdōng","en":"Pingtung","lat":22.67,"lon":120.49,"note":"The southern tip with beaches.","stops":[["A","垦丁","Kěndīng","Kenting","A beach and national park at the southern tip of the island, with coral reefs, a lighthouse and a lively beach town.","",21.95,120.8],["D","黑珍珠莲雾","Hēizhēnzhū liánwù","Black pearl wax apple","A sweet, crisp, dark red fruit, a Pingtung specialty known as the black pearl wax apple."],["D","万峦猪脚","Wànluán zhūjiǎo","Wanluan pork knuckle","A famous braised pork knuckle, cooked slowly in soy sauce, from Wanluan."]]},{"id":"hsinchu","zh":"新竹","py":"Xīnzhú","en":"Hsinchu","lat":24.8,"lon":120.97,"note":"The silicon city.","stops":[["D","新竹米粉","Xīnzhú mǐfěn","Hsinchu rice vermicelli","Thin rice noodles dried in the wind of Hsinchu, which are stir-fried with mushrooms, meat and dried shrimp."],["D","贡丸","Gòngwán","Meatball","A bouncy pork meatball, often served in soup, a Hsinchu favorite."]]},{"id":"keelung","zh":"基隆","py":"Jīlóng","en":"Keelung","lat":25.13,"lon":121.74,"note":"A rainy port city with a night market.","stops":[["D","营养三明治","Yíngyǎng sānmíngzhì","Nutrition sandwich","A fried sandwich from Keelung's night market with tomato, ham, cucumber and a sweet sauce."],["D","天妇罗","Tiānfù luó","Keelung tempura","Keelung's fried fish cake is soft and chewy, and is served with sweet sauce, a local street snack."]]},{"id":"kinmen","zh":"金门","py":"Jīnmén","en":"Kinmen","lat":24.45,"lon":118.32,"note":"A small island group close to Xiamen.","stops":[["D","金门高粱酒","Jīnmén gāoliángjiǔ","Kinmen sorghum liquor","A strong sorghum liquor made on Kinmen, which is famous in Taiwan and often sold as a gift."],["D","贡糖","Gòngtáng","Gong candy","A peanut candy that is crumbly and sweet, and a Kinmen specialty."]]}],"air":{"zh":"台北桃园国际机场","py":"Táiběi Táoyuán Guójì Jīchǎng","en":"Taiwan Taoyuan International Airport","code":"TPE","lat":25.08,"lon":121.23,"note":"Taiwan's main international airport, west of Taipei. Welcome to Taiwan."}},{"id":"xinjiang","zh":"新疆","py":"Xīnjiāng","en":"Xinjiang","cities":[{"id":"urumqi","zh":"乌鲁木齐","py":"Wūlǔmùqí","en":"Urumqi","lat":43.83,"lon":87.62,"note":"The capital of Xinjiang, said to be the city farthest from any ocean.","stops":[["A","新疆国际大巴扎","Xīnjiāng Guójì Dàbāzhā","Xinjiang Grand Bazaar","A giant market with a tall tower in Urumqi, selling carpets, dried fruit, nuts, knives, musical instruments and silk, in the style of a Central Asian bazaar.","",43.78,87.61,1],["A","新疆维吾尔自治区博物馆","Xīnjiāngwéiwú’ěrzìzhìqū Bówùguǎn","Xinjiang Museum","A museum that holds mummies from the Tarim Basin, including the Loulan Beauty, along with Silk Road treasures and local peoples' costumes.","",43.8,87.58],["A","天山天池","Tiānshān Tiānchí","Heavenly Lake of Tianshan","A deep blue mountain lake under snow-capped peaks and forests of spruce, with a calm surface that mirrors the mountains. It is a classic Xinjiang view.","",43.89,88.13,1],["A","南山牧场","Nánshān Mùchǎng","Nanshan Pasture","A mountain pasture where Kazakh herders keep horses and sheep, with green meadows, pine forests and felt tents in summer.","",43.45,87.2],["D","大盘鸡","Dàpánjī","Big plate chicken","Chicken, potatoes and peppers in a spicy sauce, served on a big plate with wide belt noodles. A hearty dish that was born in Xinjiang in the 1980s.","",null,null,1],["D","羊肉串","Yángròuchuàn","Lamb skewers","Chunks of lamb on skewers, grilled over charcoal and dusted with cumin and chili, the smell of every Xinjiang evening."],["D","抓饭","Zhuāfàn","Polo","Polo is rice cooked with lamb, carrots and raisins in a big pot, a festive and filling dish of Uyghur cuisine."],["D","馕","Náng","Naan","A round baked bread with a crisp, golden crust, made in a clay oven. Naan is eaten at every meal, and some are as big as a plate."],["D","拌面","Bànmiàn","Laghman","Laghman is hand-pulled noodles served with a stir-fried topping of meat and vegetables, a Xinjiang staple."],["D","烤包子","Kǎo bāozi","Samsa","Samsa are baked pastries filled with lamb and onion, with a crisp, flaky crust, and are sold hot from the oven."],["D","馕坑肉","Nángkēngròu","Pit-baked meat","Meat roasted in the naan oven, a deep pit of clay, so that it is tender, juicy and rich."],["D","葡萄干","Pútáogān","Raisins","Turpan raisins come in many colors, from green to black, and are dried in airy brick houses in the dry desert wind."],["D","哈密瓜","Hāmìguā","Hami melon","Hami melons have orange flesh and a very sweet taste, grown in the oases of eastern Xinjiang, and once a tribute to emperors."],["C","十二木卡姆","Shí’èr mùkǎmǔ","Twelve Muqam","A huge set of songs, music and dance of the Uyghur people, with twelve main suites that take about 24 hours to perform in full. It is on UNESCO's list."],["C","艾德莱斯绸","Ài déláisī chóu","Atlas silk","Atlas silk is a cloth dyed in bold, bright, blurred patterns, woven by Uyghur craftspeople in Hotan."],["C","麦西热甫","Màixī rèfǔ","Meshrep","A gathering with music, dance, songs, games and food, where the whole community joins in."],["C","达瓦孜","Dáwǎzī","Dawaz","The Uyghur art of tightrope walking, in which performers walk on a rope high above the ground, with little more than a balancing pole."]]},{"id":"turpan","zh":"吐鲁番","py":"Tǔlǔfān","en":"Turpan","lat":42.95,"lon":89.19,"note":"A desert oasis below sea level, known for grapes.","stops":[["A","火焰山","Huǒyànshān","Flaming Mountain","A red sandstone ridge that seems to burn in the heat of the desert sun, known from the novel Journey to the West.","",42.88,89.58],["A","葡萄沟","Pútáogōu","Grape Valley","A green valley of vineyards in the desert, with grape trellises, shady paths and a sweet harvest in late summer.","",42.96,89.23],["A","交河故城","Jiāohé Gùchéng","Jiaohe Ruins","An ancient city built on a river island, with remains of streets and temples, left in the desert since the 14th century.","",42.95,89.07],["A","高昌故城","Gāochāng Gùchéng","Gaochang Ruins","The remains of a Silk Road city of the Gaochang kingdom, where the monk Xuanzang stayed on his way to India.","",42.85,89.53],["A","苏公塔","Sūgōngtǎ","Emin Minaret","A minaret built of mud brick in the 18th century with patterns of bricks, a landmark of Turpan.","",42.92,89.23],["A","艾丁湖","Àidīnghú","Aydingkol Lake","A dry salt lake with a salty crust, the lowest point in China, about 154 meters below sea level.","",42.65,89.17],["A","吐峪沟","Tǔyùgōu","Tuyoq Valley","A canyon village with old Buddhist caves and a traditional Uyghur settlement of mud houses.","",42.85,89.8],["D","烤全羊","Kǎoquányáng","Roast whole lamb","A whole lamb roasted in the oven, served on a large platter at feasts and celebrations."],["D","吐鲁番葡萄","Tǔlǔfān pútáo","Turpan grapes","Seedless grapes in many varieties, grown in the hot desert oasis under long sunlight, and sold fresh or dried."]]},{"id":"kashgar","zh":"喀什","py":"Kāshí","en":"Kashgar","lat":39.47,"lon":75.99,"note":"An old Silk Road city at the western edge of China.","stops":[["A","艾提尕尔清真寺","Ài Tígǎ’ěr Qīngzhēnsì","Id Kah Mosque","One of the largest mosques in China, standing on the main square of Kashgar, with a bright yellow front and tall minarets. Thousands pray here on Fridays.","",39.47,75.99,1],["A","喀什老城","Kāshí Lǎochéng","Kashgar Old City","A maze of mud-brick houses and narrow lanes in Kashgar, with craftsmen's workshops and teahouses.","",39.47,75.99],["A","香妃墓","Xiāngfēi Mù","Fragrant Concubine Tomb","A tomb complex with green tiles and domes, where several generations of a Uyghur family are buried, and linked by legend to a Qing imperial concubine.","",39.5,76.0],["A","星期日大巴扎","Xīngqīrì Dàbāzhā","Sunday Bazaar","A weekly market in Kashgar where farmers, herders and traders meet to buy and sell livestock, spices, cloth and food.","",39.47,76.0],["A","慕士塔格峰","Mùshìtǎgé Fēng","Muztagh Ata","A high snow peak in the Pamirs, called the Father of Ice Mountains, with a broad, rounded dome that is more than 7,500 meters high.","",38.28,75.12],["A","卡拉库里湖","Kǎlā Kùlǐ Hú","Karakul Lake","A lake at the foot of the Pamirs, with a very blue color against white mountains, where Kyrgyz herders graze their yaks.","",38.45,75.05],["D","烤羊肉串","Kǎo yángròu chuàn","Kashgar skewers","Lamb on skewers from Kashgar, grilled over charcoal and sprinkled with cumin and salt."],["D","酸奶","Suānnǎi","Kashgar yogurt","A thick yogurt served with honey or sugar, a popular dessert on Kashgar's streets."],["D","切糕","Qiēgāo","Qiegao","A block of walnuts, almonds, raisins and dried fruit set in sugar syrup, and sliced by weight to order."],["C","热瓦甫","Rèwǎfǔ","Rawap","The rawap is a Uyghur long-necked lute with a carved body and skin top, with a lively, sharp tone."]]},{"id":"yining","zh":"伊宁","py":"Yīníng","en":"Yining","lat":43.91,"lon":81.32,"note":"The Ili valley city near Kazakhstan.","stops":[["A","薰衣草田","Xūnyīcǎo Tián","Lavender fields","In early summer, the fields around Yining turn purple with lavender, and the air is filled with its scent.","",44.05,81.5],["A","赛里木湖","Sàilǐmù Hú","Sayram Lake","A big blue lake high in the mountains, surrounded by meadows, often called the last tear of the Atlantic.","",44.6,81.2],["A","那拉提草原","Nàlātí Cǎoyuán","Narat Grassland","A grassland at the foot of the Tianshan, with rolling green hills, spruce forests and herds of horses and sheep.","",43.33,84.0],["A","喀拉峻草原","Kālā Jùn Cǎoyuán","Kalajun Grassland","A high alpine meadow with wide views, wildflowers and Kazakh herders' tents in summer.","",43.37,82.2],["D","伊犁马奶酒","Yīlí mǎnǎijiǔ","Ili kumis","Fermented mare's milk, mildly sour and slightly fizzy, a traditional Kazakh drink."],["D","伊犁薄皮包子","Yīlí báopí bāozi","Ili thin-skinned buns","Buns filled with lamb and onion, with a thin skin so that you can see the filling, steamed until juicy."],["C","冬不拉","Dōngbùlā","Dombra","The dombra is a Kazakh two-stringed lute, used to accompany songs and stories on the steppe."]]},{"id":"altay","zh":"阿勒泰","py":"Ālètài","en":"Altay","lat":47.85,"lon":88.14,"note":"A northern region of forests, lakes and skiing.","stops":[["A","喀纳斯湖","Kānàsī Hú","Kanas Lake","A lake whose color changes from green to blue with the seasons, among forests and peaks in the Altai Mountains. In autumn, the trees turn gold.","",48.7,87.03,1],["A","禾木村","Hé Mùcūn","Hemu Village","A wooden village of Tuvan people with log cabins, smoke rising from chimneys and golden larches in autumn.","",48.65,87.45],["A","可可托海","Kěkětuō Hǎi","Koktokay","A mining town and gorge of rock and rivers in the Altai, known for rare minerals and wild scenery.","",46.8,89.8],["D","奶茶","Nǎichá","Milk tea","Salty milk tea of the Kazakhs, served with bread and butter, and a warm welcome for guests."],["D","手抓肉","Shǒu zhuāròu","Hand-grabbed meat","Boiled lamb with noodles, eaten by hand, a Kazakh feast."],["D","冷水鱼","Lěngshuǐ yú","Cold-water fish","Fish from the cold, clear rivers and lakes of the Altai, often grilled or stewed."],["C","图瓦人","Túwǎ rén","Tuvan people","A small people who live in the Kanas area, with their own language and customs, known for their log houses and their music."]]},{"id":"kuqa","zh":"库车","py":"Kùchē","en":"Kuqa","lat":41.72,"lon":82.96,"note":"An old Buddhist kingdom on the northern Silk Road.","stops":[["A","克孜尔千佛洞","Kèzī’ěr Qiānfúdòng","Kizil Caves","Some of the earliest Buddhist cave paintings in China, in a cliff above a river, with murals in colors from the Silk Road.","",41.78,82.5],["D","库车大馕","Kùchē dànáng","Kuqa big naan","A giant naan, as large as a table top, baked in Kuqa and often shared among a family."],["D","库车小白杏","Kùchē xiǎobáixìng","Kuqa white apricot","A small, sweet white apricot from Kuqa, which ripens in early summer and is soft and juicy."]]},{"id":"hotan","zh":"和田","py":"Hétián","en":"Hotan","lat":37.11,"lon":79.92,"note":"A jade and silk oasis on the southern Silk Road.","stops":[["D","和田大枣","Hétián dàzǎo","Hotan jujubes","Large, sweet jujubes from Hotan, dried in the desert sun, a popular snack and gift."],["D","核桃","Hétáo","Walnut","Hotan's walnuts have thin shells and a rich, creamy kernel, grown in old orchards."]]},{"id":"korla","zh":"库尔勒","py":"Kù’ěrlè","en":"Korla","lat":41.76,"lon":86.15,"note":"A pear city on the edge of the Taklamakan.","stops":[["A","博斯腾湖","Bósīténg Hú","Bosten Lake","The largest inland freshwater lake in China, with reeds, birds and a desert shore, a popular destination.","",41.95,87.0],["D","库尔勒香梨","Kù’ěrlè xiānglí","Korla fragrant pear","A sweet and juicy pear with a thin skin and a fragrance, grown near Korla and well known across China."]]},{"id":"aksu","zh":"阿克苏","py":"Ākèsū","en":"Aksu","lat":41.17,"lon":80.26,"note":"A city known for apples.","stops":[["D","阿克苏苹果","Ākèsū píngguǒ","Aksu apples","Crisp, sweet apples with a bright color, grown in the sunny, dry Aksu region."]]},{"id":"hami","zh":"哈密","py":"Hāmì","en":"Hami","lat":42.82,"lon":93.52,"note":"A melon city between the desert and the mountains.","stops":[["D","葡萄","Pútáo","Hami grapes","Hami grapes are sweet and juicy and grown in the dry climate of eastern Xinjiang."]]},{"id":"karamay","zh":"克拉玛依","py":"Kèlāmǎyī","en":"Karamay","lat":45.58,"lon":84.89,"note":"An oil city in the Junggar Basin.","stops":[["D","克拉玛依烤肉","Kèlāmǎyī kǎoròu","Karamay barbecue","Grilled meat from the oil city of Karamay, a favorite with workers and visitors."]]},{"id":"changji","zh":"昌吉","py":"Chāngjí","en":"Changji","lat":44.01,"lon":87.31,"note":"A Hui prefecture east of Urumqi.","stops":[["D","昌吉拌面","Chāngjí bànmiàn","Changji laghman","A hearty noodle dish of hand-pulled noodles with a rich stir-fried topping."]]},{"id":"shihezi","zh":"石河子","py":"Shíhézi","en":"Shihezi","lat":44.3,"lon":86.04,"note":"A planned oasis city built by army settlers.","stops":[["D","石河子葡萄","Shíhézi pútáo","Shihezi grapes","Grapes grown by settlers on the oasis of Shihezi, a green city in the desert, which are sweet and juicy."]]}],"air":{"zh":"乌鲁木齐地窝堡国际机场","py":"Wūlǔmùqí Dìwōbǎo Guójì Jīchǎng","en":"Urumqi Diwopu International Airport","code":"URC","lat":43.91,"lon":87.47,"note":"The main airport of Xinjiang and the gateway to Central Asia. Welcome to Xinjiang."}},{"id":"xizang","zh":"西藏","py":"Xīzàng","en":"Tibet (Xizang)","cities":[{"id":"lhasa","zh":"拉萨","py":"Lāsà","en":"Lhasa","lat":29.65,"lon":91.12,"note":"The capital of Tibet, at the foot of the Potala Palace.","stops":[["A","布达拉宫","Bùdálā Gōng","Potala Palace","A palace-fortress rising from a red hill above Lhasa, once the winter home of the Dalai Lamas. Its white and red walls and golden roofs make it the symbol of Tibet. It is a UNESCO World Heritage Site.","A UNESCO World Heritage Site.",29.66,91.12,1],["A","大昭寺","Dàzhāosì","Jokhang Temple","The most sacred temple in Tibet, built in the seventh century in the old city of Lhasa. Pilgrims prostrate in front of its doors, and inside it holds a revered statue of the Buddha.","",29.65,91.13,1],["A","八廓街","Bākuòjiē","Barkhor Street","A circuit around the Jokhang Temple, full of pilgrims spinning prayer wheels, and stalls selling prayer flags, jewelry and butter lamps.","",29.65,91.13],["A","罗布林卡","Luóbù Línkǎ","Norbulingka","A summer palace and garden of the Dalai Lamas, with pavilions, trees and ponds, where Tibetans picnic in summer.","",29.65,91.09],["A","哲蚌寺","Zhébàngsì","Drepung Monastery","Once one of the largest monasteries in the world, with white buildings that climb a hillside, and housing thousands of monks.","",29.69,91.05],["A","色拉寺","Sèlāsì","Sera Monastery","A monastery famed for its monks' debates in the courtyard, where they clap and argue about Buddhist teachings in the afternoon.","",29.7,91.14],["A","纳木错","Nàmùcuò","Namtso Lake","A great salt lake high on the plateau, at about 4,700 meters, with a deep turquoise color under a vast sky and with snow peaks beyond. It is one of Tibet's sacred lakes.","",30.7,90.55,1],["A","西藏博物馆","Xīzàng Bówùguǎn","Tibet Museum","A museum of Tibetan history and art, with thangka paintings, religious objects and displays on daily life on the plateau.","",29.64,91.09],["D","酥油茶","Sūyóuchá","Butter tea","Tea churned with yak butter and salt, a hot, rich drink that warms Tibetans at high altitude, and which welcomes every guest.","",null,null,1],["D","糌粑","Zānbā","Tsampa","Roasted barley flour, the staple of Tibet. You mix it with butter tea and knead it into a ball with your fingers."],["D","藏面","Zàngmiàn","Tibetan noodles","Thick noodles in a beef broth, a warm, simple meal in Lhasa's noodle shops."],["D","牦牛肉","Máoniúròu","Yak meat","Dried or stewed yak, with a rich flavor and lean meat, a staple of the plateau."],["D","青稞酒","Qīngkējiǔ","Chang barley beer","Chang is a mild drink made from barley, offered at festivals and weddings, often accompanied by song."],["D","酸奶","Suānnǎi","Yak yogurt","A thick, sweet yogurt from yak milk, a Tibetan favorite, especially at the Shoton Festival."],["D","藏式包子","Zàngshì bāozi","Momo","Momo are dumplings filled with yak or beef, steamed or fried, eaten with a hot chili sauce."],["D","甜茶","Tiánchá","Sweet tea","A sweet milky tea, sold in Lhasa's teahouses, where people gather to talk over cheap, hot glasses of tea."],["C","藏历新年","Zànglì xīnnián","Losar","Losar is the Tibetan New Year, with family feasts, prayers, new clothes and offerings of barley and fried cakes."],["C","雪顿节","Xuědùnjié","Shoton Festival","A summer festival in Lhasa, with a giant thangka painting unveiled on a hillside, plus Tibetan opera and yogurt feasts."],["C","藏戏","Zàngxì","Tibetan opera","Tibetan opera is a masked drama that combines song, dance and storytelling, often about Buddhist tales."],["C","唐卡","Tángkǎ","Thangka","Thangka are painted scrolls of Buddhist figures, made with mineral pigments and gold, and take months or years to complete."]]},{"id":"shigatse","zh":"日喀则","py":"Rìkāzé","en":"Shigatse","lat":29.27,"lon":88.88,"note":"The second city of Tibet, seat of the Panchen Lama.","stops":[["A","扎什伦布寺","Zhāshénlúnbù Sì","Tashilhunpo Monastery","The seat of the Panchen Lamas in Shigatse, with a giant gilded statue of Maitreya, the Buddha of the future.","",29.26,88.87],["A","萨迦寺","Sàjiāsì","Sakya Monastery","A fortress-like monastery painted in red, white and gray, the center of the Sakya school of Tibetan Buddhism.","",28.9,88.02],["A","珠穆朗玛峰","Zhūmùlǎngmǎ Fēng","Mount Everest","The highest mountain in the world, at 8,849 meters, on the border of Tibet and Nepal. Its Tibetan name is Chomolungma.","",28.0,86.93],["A","珠峰大本营","Zhūfēng Dàběnyíng","Everest Base Camp","The Tibetan base camp on the north side of Everest, with a tent village and a view of the north face.","",28.14,86.85],["A","白居寺","Báijūsì","Palcho Monastery","A monastery in Gyantse with a nine-story stupa that holds thousands of paintings and statues.","",28.92,89.6],["A","江孜宗山古堡","Jiāngzī Zōngshān Gǔbǎo","Gyantse Dzong","A fortress on a hill above Gyantse, which saw a battle in 1904 and has a wide view over the town.","",28.92,89.6],["A","羊卓雍错","Yángzhuóyōng Cuò","Yamdrok Lake","A turquoise lake shaped like a scorpion, one of the three great sacred lakes of Tibet, with mountain views.","",28.97,90.45],["A","卡若拉冰川","Kǎruòlā Bīngchuān","Karola Glacier","A glacier by the roadside where you can see the ice from a view platform, at a high mountain pass.","",28.95,90.27],["D","藏香猪","Zàngxiāng zhū","Tibetan fragrant pig","A small, black pig of the plateau, raised in the mountains and known for its tender and tasty meat."],["D","酥油饼","Sūyóu bǐng","Butter cakes","Bread fried in butter, crisp outside and soft inside, a popular snack at festivals."],["D","牦牛酸奶","Máoniú suānnǎi","Yak yogurt","A thick yogurt from the milk of yaks, tangy and creamy, sold in many homes in the villages."]]},{"id":"nyingchi","zh":"林芝","py":"Línzhī","en":"Nyingchi","lat":29.65,"lon":94.36,"note":"The green southeast, called the Switzerland of Tibet.","stops":[["A","雅鲁藏布大峡谷","Yǎlǔ Zàngbù Dàxiágǔ","Yarlung Tsangpo Grand Canyon","The deepest canyon in the world, which the Yarlung Tsangpo River cuts around the eastern end of the Himalayas, in a steep, green gorge.","",29.6,95.0],["A","南迦巴瓦峰","Nánjiābāwǎ Fēng","Namcha Barwa","A snow peak at the bend of the river, often hidden by clouds, so that seeing it is considered a gift.","",29.63,95.05],["A","巴松措","Bāsōngcuò","Basum Lake","A forest lake in a valley of pines and snow peaks, with a temple on a small island and calm, clear water.","",30.0,93.9],["A","色季拉山","Sèjìlā Shān","Sejila Mountain","A pass with views of Namcha Barwa on a clear day, among rhododendron forests.","",29.65,94.7],["A","鲁朗林海","Lǔlǎng Línhǎi","Lulang Forest","A forest and meadow that look like an alpine landscape, with wooden houses and grazing cattle.","",29.7,94.8],["D","林芝松茸","Línzhī sōngrōng","Nyingchi matsutake","Wild matsutake mushrooms from the forests of Nyingchi, prized for their aroma, and served in soup or grilled."],["D","石锅鸡","Shíguō jī","Stone pot chicken","Chicken cooked with herbs in a stone pot from Mêdog, where the soapstone gives the soup its special taste."],["C","门巴族","Ménbāzú","Monpa people","A small people of the forests near the Himalayas, known for their wooden bowls and bamboo crafts."],["C","珞巴族","Luòbāzú","Lhoba people","A small people in the far southeast of Tibet, known for their hunting traditions and bamboo and cane crafts."]]},{"id":"shannan","zh":"山南","py":"Shānnán","en":"Shannan","lat":29.24,"lon":91.77,"note":"The cradle of Tibetan civilization.","stops":[["A","雍布拉康","Yōngbù Lākāng","Yumbulagang","An ancient palace on a hill that is said to have been built in the second century BCE as the first palace of Tibet.","",29.22,91.77],["A","桑耶寺","Sāngyésì","Samye Monastery","The first Buddhist monastery in Tibet, built in the eighth century in the shape of a mandala, with halls and stupas around a central temple.","",29.32,91.52],["A","藏王墓","Zàngwáng Mù","Tombs of the Tibetan Kings","Burial mounds of the Tibetan emperors of the seventh to ninth centuries, grassy hills in a valley with stone pillars.","",29.22,91.76],["D","青稞饼","Qīngkē bǐng","Barley cake","A flatbread made of barley flour, baked or toasted, a traditional food of the farming valleys."],["C","藏医药","Zàng yīyào","Tibetan medicine","Tibetan medicine is a medical system with centuries of history, which uses herbs, minerals, diet and massage."]]},{"id":"nagqu","zh":"那曲","py":"Nàqū","en":"Nagqu","lat":31.48,"lon":92.05,"note":"A high grassland where nomads live.","stops":[["D","牦牛肉干","Máoniúròu gàn","Yak jerky","Dried yak meat is chewy and savory, an ideal snack for long journeys across the plateau."]]},{"id":"ngari","zh":"阿里","py":"Ālǐ","en":"Ngari","lat":32.5,"lon":80.1,"note":"The remote far west, with Mount Kailash.","stops":[["A","冈仁波齐","Gāngrén Bōqí","Mount Kailash","A holy mountain for Buddhists, Hindus, Jains and Bon followers, shaped like a four-sided pyramid. No one is allowed to climb it, but pilgrims walk around it.","",31.07,81.31,1],["A","玛旁雍错","Mǎpángyōng Cuò","Lake Manasarovar","A holy lake near Mount Kailash, among the highest freshwater lakes in the world, where pilgrims bathe for blessing.","",30.65,81.5],["D","阿里羊肉","Ālǐ yángròu","Ngari lamb","Lamb from the high plateau of Ngari, with a tender, sweet taste, grown on mountain grass."],["C","转山","Zhuànshān","Kailash kora","The kora is a walk around the mountain, a circuit of about 52 kilometers, said to bring merit, which pilgrims complete in about three days.","A circuit of about 52 km, said to bring merit."]]},{"id":"qamdo","zh":"昌都","py":"Chāngdōu","en":"Qamdo","lat":31.14,"lon":97.17,"note":"A city at the meeting of three rivers in the east.","stops":[]}],"air":{"zh":"拉萨贡嘎国际机场","py":"Lāsà Gònggā Guójì Jīchǎng","en":"Lhasa Gonggar Airport","code":"LXA","lat":29.3,"lon":90.91,"note":"One of the highest airports in the world, at about 3,570 meters. Welcome to Tibet."}},{"id":"yunnan","zh":"云南","py":"Yúnnán","en":"Yunnan","cities":[{"id":"kunming","zh":"昆明","py":"Kūnmíng","en":"Kunming","lat":25.04,"lon":102.71,"note":"The City of Eternal Spring, with mild weather all year.","stops":[["A","滇池","Diānchí","Dian Lake","A huge plateau lake beside Kunming, ringed by hills. In winter, black-headed gulls arrive from Siberia and people feed them from the shore.","",24.85,102.69],["A","石林","Shílín","Stone Forest","Gray limestone pillars rise like a petrified forest across the land, shaped over millions of years. The Sani people, a branch of the Yi, tell the legend of Ashima here.","",24.82,103.29,1],["A","翠湖公园","Cuìhú Gōngyuán","Green Lake Park","Kunming's city-center park, with lotus ponds, willow-lined paths and old men playing chess. It is a good place to see the slow side of the Spring City.","",25.05,102.7],["A","云南民族村","Yúnnán Mínzúcūn","Yunnan Nationalities Village","A theme park with homes, dances and food from many of Yunnan's 25 minority peoples, a quick way to see how varied the province is.","",24.94,102.67],["A","西山龙门","Xīshān Lóngmén","Dragon Gate at Western Hills","A path carved into a cliff by hand over decades, climbing high above Dian Lake to a view over the water.","",24.95,102.63],["A","圆通寺","Yuántōngsì","Yuantong Temple","Kunming's biggest Buddhist temple, set in a sunken courtyard with a pond and a pavilion, and cherry blossoms in spring.","",25.06,102.71],["A","金马碧鸡坊","Jīnmǎ Bìjīfāng","Golden Horse and Jade Rooster Archways","Two archways facing each other in the old city, a symbol of Kunming. Twice a year, at sunset, their shadows are said to meet.","",25.04,102.71],["D","过桥米线","Guòqiáo mǐxiàn","Crossing-the-bridge noodles","A bowl of boiling-hot broth with a layer of oil that keeps it hot. You add raw meat, quail eggs, vegetables and rice noodles, and it cooks at your table. The name comes from a legend about a wife who carried lunch over a bridge to her husband.","",null,null,1],["D","汽锅鸡","Qìguō jī","Steam-pot chicken","Chicken steamed in a special clay pot with a chimney in the middle, so the soup is clean and light, with no water added."],["D","鲜花饼","Xiānhuā bǐng","Flower cake","A flaky pastry filled with edible rose petals and sugar. It is a typical Kunming gift, and is best eaten fresh."],["D","烤乳扇","Kǎo rǔshàn","Grilled milk fan","A thin sheet of dried cow's milk cheese, grilled over charcoal and rolled with rose jam or sugar. A snack of the Bai people."],["D","野生菌火锅","Yěshēng jūn huǒguō","Wild mushroom hot pot","In the rainy season, markets fill with wild mushrooms, and cooks put a dozen kinds in one pot. Yunnan is a mushroom-lover's paradise, though it is best to go where cooks know what is safe."],["D","云腿月饼","Yúntuǐ yuèbǐng","Yunnan ham mooncake","A mooncake with a salty-sweet filling of Xuanwei ham, a Yunnan twist on the festival treat."]]},{"id":"dali","zh":"大理","py":"Dàlǐ","en":"Dali","lat":25.61,"lon":100.27,"note":"An old Bai kingdom between a lake and a snowy range.","stops":[["A","大理古城","Dàlǐ Gǔchéng","Dali Old Town","A walled town with cobbled streets, cafés, shops and the Cangshan range behind it. Its gates and towers are built in the Bai style.","",25.69,100.16],["A","崇圣寺三塔","Chóngshèng Sì Sāntǎ","Three Pagodas of Chongsheng Temple","Three stone pagodas stand side by side before the Cang Mountains, more than 1,000 years old. The tallest has 16 levels. They are the most famous view in Dali, especially with their reflection in the pool.","",25.71,100.15,1],["A","洱海","Ěrhǎi","Erhai Lake","A big, bright lake shaped like an ear, which the Bai people call their mother lake. Cycling along its shore, with the Cangshan mountains beyond, is the best way to see it.","",25.8,100.2],["A","苍山","Cāngshān","Cangshan Mountain","A range of nineteen peaks behind Dali, snowy in winter. A cable car and walking paths lead along the mountain.","",25.68,100.07],["A","喜洲古镇","Xǐzhōu Gǔzhèn","Xizhou Ancient Town","A Bai town with white-walled courtyards, carved gateways and painted designs. It is known for its flatbread and its rice fields.","",25.85,100.14],["A","双廊古镇","Shuāngláng Gǔzhèn","Shuanglang Ancient Town","A fishing village on the lakeshore, now filled with guesthouses and cafés that look over the water.","",25.94,100.19],["D","乳饼","Rǔbǐng","Rubing cheese","A firm white Bai cheese, sliced and fried or grilled until golden, with a mild, milky taste."],["D","酸辣鱼","Suānlà yú","Sour and spicy fish","Fish from Erhai, simmered in a sour and spicy broth with tomatoes and herbs, a Dali favorite."],["D","喜洲粑粑","Xǐzhōu bābā","Xizhou baba","A round flatbread with a crisp crust, baked in a clay oven, and filled with salty meat or sweet sugar."],["D","白族三道茶","Báizú sāndào chá","Bai three-course tea","A tea ceremony of three courses for guests: first bitter, then sweet, then with a spicy aftertaste. It stands for the stages of life."],["C","白族扎染","Báizú zārǎn","Bai tie-dye","Cloth that is tied, then dipped in a plant dye to get blue-and-white patterns, made in Zhoucheng village."],["C","三月街","Sānyuè jiē","March Fair","An ancient fair held every spring in Dali, where traders, herders and performers gather for horse races, songs and selling goods."]]},{"id":"lijiang","zh":"丽江","py":"Lìjiāng","en":"Lijiang","lat":26.87,"lon":100.23,"note":"An old Naxi town under a snow mountain.","stops":[["A","丽江古城","Lìjiāng Gǔchéng","Lijiang Old Town","A maze of cobbled lanes, canals and wooden houses of the Naxi people, with water flowing through every street. It is a UNESCO World Heritage Site, and its lanterns glow in the evening.","A UNESCO World Heritage Site.",26.87,100.23,1],["A","玉龙雪山","Yùlóngxuě Shān","Jade Dragon Snow Mountain","A rugged mountain range with a snow-covered peak north of Lijiang, rising to about 5,600 meters. A cable car goes up to the glacier, and the lakes below are known as Blue Moon Valley.","",27.1,100.18,1],["A","束河古镇","Shùhé Gǔzhèn","Shuhe Ancient Town","A quieter old town than Lijiang, with a clear stream, willows and a market square where the tea-horse caravans once stopped.","",26.92,100.2],["A","黑龙潭","Hēilóngtán","Black Dragon Pool","A pond with a pavilion and a bridge, with the snow-capped mountain reflected in the water on a clear day.","",26.89,100.22],["A","虎跳峡","Hǔtiàoxiá","Tiger Leaping Gorge","One of the deepest gorges in the world, where the Yangtze roars between two snow mountains. Hikers can walk along the cliff trail.","",27.19,100.1],["A","蓝月谷","Lányuègǔ","Blue Moon Valley","A valley of milky-blue pools at the foot of the snow mountain, whose color comes from minerals in the water.","",27.12,100.22],["D","腊排骨火锅","Là páigǔ huǒguō","Cured ribs hot pot","A hot pot of smoked pork ribs, a warming dish in the cold mountains."],["D","丽江粑粑","Lìjiāng bābā","Lijiang baba","A big, flat bread filled with ham, sugar or beans, fried until crisp on the edges."],["D","鸡豆凉粉","Jīdòu liángfěn","Chickpea jelly","A cool, soft jelly made of chickpea flour, served with hot chili, vinegar and herbs on a warm day."],["C","纳西古乐","Nàxī gǔyuè","Naxi ancient music","An old music played on ancient instruments, said to preserve the sound of Tang and Song courts. The elderly musicians still perform it."],["C","东巴文","Dōngbāwén","Dongba script","A pictographic script of the Naxi, written by priests for centuries. It is among the few picture scripts still in use in the world."]]},{"id":"xishuangbanna","zh":"西双版纳","py":"Xīshuāngbǎnnà","en":"Xishuangbanna","lat":22.01,"lon":100.8,"note":"A tropical area on the Mekong with Dai culture.","stops":[["A","野象谷","Yěxiàng Gǔ","Wild Elephant Valley","A forest valley where wild Asian elephants live. You can walk along a skybridge and watch from above, but sightings are a matter of luck.","",22.17,100.87],["A","热带植物园","Rèdài Zhíwùyuán","Tropical Botanical Garden","A garden of tropical rainforest plants with palms, orchids and giant trees, set along a bend of a river.","",21.92,101.25],["D","菠萝饭","Bōluó fàn","Pineapple rice","Sticky purple rice steamed in a pineapple shell, sweet and fragrant. A Dai dish."],["D","香茅草烤鱼","Xiāngmáocǎo kǎoyú","Lemongrass grilled fish","Fish stuffed with lemongrass and herbs, wrapped in leaves, and grilled over charcoal. A Dai specialty."],["D","普洱茶","Pǔ’ěrchá","Pu'er tea","A tea that is pressed into cakes and aged, so that it gets a deep, earthy taste. Some old cakes sell for a lot of money."],["C","泼水节","Pōshuǐjié","Water Splashing Festival","The Dai New Year in April, when everyone splashes water on each other for good luck. It is a joyful, soaking festival."],["C","孔雀舞","Kǒngquèwǔ","Peacock dance","A Dai dance in which the performer imitates a peacock with graceful arms and hands, in a costume with a long tail."]]},{"id":"shangrila","zh":"香格里拉","py":"Xiānggélǐlā","en":"Shangri-La","lat":27.83,"lon":99.71,"note":"A Tibetan highland town in the far northwest.","stops":[["A","松赞林寺","Sōngzànlín Sì","Songzanlin Monastery","The largest Tibetan Buddhist monastery in Yunnan, with golden roofs on a hillside, sometimes called the little Potala. Its prayer halls are lined with bright murals.","",27.85,99.72,1],["A","普达措国家公园","Pǔdácuò Guójiā Gōngyuán","Pudacuo National Park","A highland park with lakes, meadows and pine forests at about 3,500 meters, where yaks graze by the water.","",27.83,99.99],["A","独克宗古城","Dúkèzōng Gǔchéng","Dukezong Old Town","A hill town with a giant golden prayer wheel at the top, and wooden houses and shops along the streets below.","",27.82,99.7],["D","酥油茶","Sūyóuchá","Butter tea","Tea churned with yak butter and salt, a warm drink at altitude, which Tibetan families serve to guests."],["D","牦牛肉","Máoniúròu","Yak meat","The meat of the yak, dried, boiled or stewed. It is a lean, strong-tasting meat of the highlands."]]},{"id":"honghe","zh":"红河","py":"Hónghé","en":"Honghe","lat":23.37,"lon":103.38,"note":"A prefecture famous for terraced rice fields.","stops":[["A","元阳梯田","Yuányáng Tītián","Yuanyang Rice Terraces","Thousands of rice terraces carved into the mountainsides by the Hani people over 1,300 years. In winter, the flooded fields reflect the sky in colors of pink, gold and blue at dawn.","A UNESCO World Heritage Site.",23.1,102.77,1],["D","建水烧豆腐","Jiànshuǐ shāo dòufǔ","Jianshui grilled tofu","Small blocks of tofu grilled on a charcoal brazier until they puff up, then dipped in a spicy sauce, and eaten on the street."],["D","蒙自过桥米线","Měngzì guòqiáo mǐxiàn","Mengzi crossing-the-bridge noodles","Mengzi's take on crossing-the-bridge noodles, said to be the original, with a rich, fragrant broth."]]},{"id":"baoshan","zh":"保山","py":"Bǎoshān","en":"Baoshan","lat":25.11,"lon":99.17,"note":"A western city near the Burma border.","stops":[["A","腾冲","Téngchōng","Tengchong","A town in the far west near the border with Myanmar, known for volcanoes, hot springs and a long history of trade.","",25.02,98.49],["A","和顺古镇","Héshùn Gǔzhèn","Heshun Ancient Town","A village built by merchants who traded abroad, with grand houses, a library and ponds with lotus.","",25.03,98.45],["D","腾冲大救驾","Téngchōng dà jiùjià","Tengchong Da Jiu Jia","Fried rice cake with ham and vegetables. Legend says it saved an emperor on the run, giving it the name Great Rescue."],["D","保山咖啡","Bǎoshān kāfēi","Baoshan coffee","Yunnan grows most of China's coffee, and Baoshan's beans have a smooth, mild taste."]]},{"id":"puer","zh":"普洱","py":"Pǔ’ěr","en":"Pu'er","lat":22.79,"lon":100.97,"note":"The home of the tea named after it.","stops":[]},{"id":"lincang","zh":"临沧","py":"Líncāng","en":"Lincang","lat":23.88,"lon":100.09,"note":"A border city of tea and coffee.","stops":[["D","临沧红茶","Líncāng hóngchá","Lincang black tea","A strong, sweet black tea from old trees, which the Chinese call red tea."]]},{"id":"zhaotong","zh":"昭通","py":"Zhāotōng","en":"Zhaotong","lat":27.34,"lon":103.72,"note":"A northern city on the way to Sichuan.","stops":[["D","昭通苹果","Zhāotōng píngguǒ","Zhaotong apples","Crisp apples grown on the high plateau of northeast Yunnan, with a sweet flavor and bright red color."]]},{"id":"wenshan","zh":"文山","py":"Wénshān","en":"Wenshan","lat":23.37,"lon":104.24,"note":"A karst area near Vietnam, home to a famous herb.","stops":[["A","普者黑","Pǔzhěhēi","Puzhehei","A karst landscape of lakes, lotus fields and little islands, which you can cross in a wooden boat. The Yi people live in the villages around it.","",23.64,104.04],["D","文山三七鸡","Wénshān sānqī jī","Sanqi chicken","Chicken stewed with notoginseng, a medicinal root grown in Wenshan, a hearty and warming soup."]]},{"id":"chuxiong","zh":"楚雄","py":"Chǔxióng","en":"Chuxiong","lat":25.04,"lon":101.55,"note":"A prefecture of the Yi people.","stops":[["D","彝族坨坨肉","Yízú tuótuóròu","Yi tuotuo pork","Big chunks of boiled pork, served with salt and chili, a hearty meal for Yi festivals."],["C","火把节","Huǒbǎjié","Torch Festival","A Yi festival in summer when villages light torches and bonfires, dance and wrestle through the night to chase away evil."]]}],"air":{"zh":"昆明长水国际机场","py":"Kūnmíng Zhǎngshuǐ Guójì Jīchǎng","en":"Kunming Changshui International Airport","code":"KMG","lat":25.1,"lon":102.93,"note":"The main airport of Yunnan, in the highlands. Welcome to Yunnan."}},{"id":"zhejiang","zh":"浙江","py":"Zhèjiāng","en":"Zhejiang","cities":[{"id":"hangzhou","zh":"杭州","py":"Hángzhōu","en":"Hangzhou","lat":30.27,"lon":120.15,"note":"A lake city and old capital, home to West Lake and a tech boom.","stops":[["A","西湖","Xīhú","West Lake","A lake ringed by hills, causeways, willows and pagodas, loved by poets for over a thousand years. Su Dongpo and Bai Juyi each built a causeway here. It is a UNESCO World Heritage Site, and the heart of Hangzhou.","A UNESCO World Heritage cultural landscape.",30.24,120.14,1],["A","灵隐寺","Língyǐnsì","Lingyin Temple","A Buddhist temple founded in the fourth century, tucked into a wooded hill, with thousands of stone carvings along the cliff nearby. It is one of the oldest and most visited temples in China.","",30.24,120.1,1],["A","雷峰塔","Léifēngtǎ","Leifeng Pagoda","A pagoda on the lakeshore, built again in 2002, tied to the legend of the White Snake. Its sunset view over West Lake is a famous one.","",30.23,120.15],["A","断桥","Duànqiáo","Broken Bridge","A small stone bridge on West Lake where, in the White Snake legend, the lovers met in the rain. In winter, a dusting of snow on the arch gives the bridge its name.","",30.26,120.15],["A","西溪湿地","Xīxī Shīdì","Xixi Wetland","A wetland of waterways, reeds and persimmon trees inside the city, which you explore by boat. A quiet escape from the crowds.","",30.26,120.06],["A","龙井村","Lóngjǐngcūn","Longjing Village","A village among hills of tea bushes, where Dragon Well tea is grown. Visitors can taste fresh tea in the farmers' homes.","",30.22,120.11],["A","六和塔","Liùhétǎ","Six Harmonies Pagoda","A pagoda of thirteen outside levels beside the Qiantang River, built in the tenth century to calm the river's tidal bore.","",30.2,120.12],["A","河坊街","Héfāng Jiē","Hefang Street","A restored old street with shops, teahouses and snack stalls, lit by lanterns in the evening.","",30.24,120.17],["D","西湖醋鱼","Xīhú cùyú","West Lake fish in vinegar","A whole fish poached and covered with a glossy sweet-and-sour sauce. A classic of Hangzhou cooking, and sometimes an acquired taste."],["D","东坡肉","Dōngpōròu","Dongpo pork","Squares of pork belly braised slowly in soy sauce and rice wine until they melt in the mouth. Named for the poet Su Dongpo, who is said to have created the dish while governor of Hangzhou.","",null,null,1],["D","龙井虾仁","Lóngjǐng xiārén","Longjing shrimp","River shrimp stir-fried with fresh Dragon Well tea leaves, a light and fragrant dish, subtle in color and taste."],["D","叫花鸡","Jiàohuā jī","Beggar's chicken","Chicken stuffed with herbs, wrapped in lotus leaves and clay, and baked. You crack the clay open at the table. Legend says a beggar invented it."],["D","片儿川","Piān’er chuān","Pianerchuan noodles","A bowl of noodles with sliced pork, bamboo shoots and pickled greens, a favorite breakfast in Hangzhou."],["D","龙井茶","Lóngjǐngchá","Longjing tea","A flat green tea, pan-fried by hand, with a fresh, nutty taste. It is grown around West Lake and is among the best-known teas in China. Fresh spring leaves are the most prized."],["C","越剧","Yuèjù","Yue opera","A gentle, lyrical opera that began in Zhejiang, traditionally sung entirely by women, famous for love stories like Butterfly Lovers."]]},{"id":"ningbo","zh":"宁波","py":"Níngbō","en":"Ningbo","lat":29.87,"lon":121.55,"note":"A port city and old trade center.","stops":[["A","天一阁","Tiānyīgé","Tianyi Pavilion","A library built in the 1500s, one of the oldest private libraries in Asia, which survived fires thanks to its design with water around it.","",29.87,121.54],["A","老外滩","Lǎo Wàitān","Old Bund","A riverside stretch of old European-style buildings, once a trading port, now with cafés and bars.","",29.88,121.56],["A","天童寺","Tiāntóngsì","Tiantong Temple","A large Chan Buddhist temple deep in a forest, where Japanese monks once came to study.","",29.8,121.78],["A","河姆渡遗址","Hémǔdù Yízhǐ","Hemudu Site","A site of a neolithic village about 7,000 years old, where rice, boats and wooden houses on stilts were found.","",30.0,121.35],["D","宁波汤圆","Níngbō tāngyuán","Ningbo tangyuan","Rice balls filled with black sesame and lard, boiled and served in sweet soup. A famous Ningbo dessert, eaten at festivals."],["D","宁波年糕","Níngbō niángāo","Ningbo rice cake","Chewy rice cake, stir-fried with vegetables or pork, or boiled in soup, a staple of Ningbo."],["D","咸蟹","Xiánxiè","Salted crab","Raw crab pickled in brine, served with rice, a strong coastal taste for the brave."]]},{"id":"shaoxing","zh":"绍兴","py":"Shàoxīng","en":"Shaoxing","lat":30.0,"lon":120.58,"note":"A canal town of wine, writers and bridges.","stops":[["A","鲁迅故里","Lǔxùn Gùlǐ","Lu Xun's Hometown","The old home of the writer Lu Xun and the streets from his stories, with a school, a garden and a tavern. It gives a feel for the water town of the early 1900s.","",30.0,120.59],["A","兰亭","Lántíng","Orchid Pavilion","A garden where, in 353, Wang Xizhi and his friends wrote poems over wine and he wrote a famous piece of calligraphy.","",29.97,120.54],["A","乌篷船","Wūpéngchuán","Black-awning boats","Small boats with a black bamboo canopy, rowed by hand, that carry visitors through the canals.","",30.0,120.59],["D","绍兴黄酒","Shàoxīng huángjiǔ","Shaoxing wine","A rice wine aged in clay jars, amber in color, used in cooking and drunk warm. The best-known drink of Shaoxing, and the base of many Zhejiang dishes.","",null,null,1],["D","茴香豆","Huíxiāngdòu","Fennel beans","Dried broad beans simmered with fennel, a snack with wine, famous from a Lu Xun story."],["D","霉干菜扣肉","Méigāncài kòuròu","Preserved greens with pork","Pork belly steamed over salty dried greens until rich and soft, a hearty home dish."],["D","臭豆腐","Chòudòufǔ","Shaoxing stinky tofu","Tofu that is fermented until it smells strong, then fried. It is crisp outside, soft inside, and loved by many."]]},{"id":"wenzhou","zh":"温州","py":"Wēnzhōu","en":"Wenzhou","lat":28.0,"lon":120.7,"note":"A coastal city of merchants.","stops":[["A","雁荡山","Yàndàngshān","Yandang Mountain","A mountain of strange peaks, waterfalls and caves, with the cliffs lit at night in a show of light.","",28.37,121.05],["A","江心屿","Jiāngxīnyǔ","Jiangxin Island","An island in the river with two pagodas, a poet's retreat since the Tang dynasty.","",28.02,120.65],["A","楠溪江","Nánxījiāng","Nanxi River","A clear river winding through old villages and hills, perfect for rafting.","",28.45,120.55],["D","鱼丸","Yúwán","Wenzhou fish balls","Springy fish balls in a clear soup, a Wenzhou breakfast snack."],["D","瓯柑","Ōugān","Ou tangerines","A sweet, fragrant tangerine with a thin skin, once a tribute to the emperor."]]},{"id":"jiaxing","zh":"嘉兴","py":"Jiāxīng","en":"Jiaxing","lat":30.75,"lon":120.76,"note":"A water town where the Communist Party held an early meeting.","stops":[["A","南湖","Nánhú","South Lake","A lake where a founding meeting of the Communist Party was concluded on a boat in 1921. A replica boat is on display.","",30.75,120.78],["A","乌镇","Wūzhèn","Wuzhen","A canal town with stilt houses, stone bridges, waterside teahouses and a theater. It looks beautiful in the evening with lights on the water, and hosts a World Internet Conference.","",30.64,120.49,1],["A","西塘","Xītáng","Xitang","A water town known for its covered walkways along the canals, so you can walk in the rain.","",30.95,120.89],["D","嘉兴粽子","Jiāxīng zòngzi","Jiaxing zongzi","Sticky rice dumplings wrapped in bamboo leaves, with a fatty pork or sweet bean filling. Jiaxing is the most famous place for them."],["D","南湖菱","Nánhú líng","South Lake water chestnut","A water plant with a sweet, crisp taste, harvested from the lake in autumn."]]},{"id":"huzhou","zh":"湖州","py":"Húzhōu","en":"Huzhou","lat":30.89,"lon":120.09,"note":"A lake city of silk, ink brushes and bamboo.","stops":[["A","莫干山","Mògànshān","Mogan Mountain","A mountain covered in bamboo, with old villas and cool summer air, a retreat for Shanghai residents.","",30.6,119.88],["A","南浔古镇","Nánxún Gǔzhèn","Nanxun Ancient Town","A silk-trading town where wealthy merchants built grand houses, with a mix of Chinese and European styles.","",30.87,120.42],["D","湖笔","Húbǐ","Huzhou brush","Writing brushes made in Huzhou for 700 years, loved by calligraphers, made of goat or weasel hair."],["D","太湖银鱼","Tàihú yínyú","Taihu whitebait","Tiny, transparent fish from Lake Tai, often scrambled with egg or in soup."]]},{"id":"jinhua","zh":"金华","py":"Jīnhuá","en":"Jinhua","lat":29.08,"lon":119.65,"note":"A city with a famous ham and the Yiwu market.","stops":[["A","义乌小商品城","Yìwū Xiǎoshāngpǐn Chéng","Yiwu International Trade City","The world's biggest wholesale market for small goods, from toys to Christmas decorations, with hundreds of thousands of products.","",29.31,120.07],["A","横店影视城","Héngdiàn Yǐngshìchéng","Hengdian World Studios","A giant film studio with copies of the Forbidden City, a Qing street and old Hong Kong, where many Chinese films and dramas are shot.","",29.15,120.32],["D","金华火腿","Jīnhuá huǒtuǐ","Jinhua ham","A dry-cured ham with a deep red color and rich taste, aged for a year or more. It flavors soups and stir-fries."]]},{"id":"taizhou","zh":"台州","py":"Tāizhōu","en":"Taizhou","lat":28.66,"lon":121.42,"note":"A coastal city with an old city wall.","stops":[["A","天台山","Tiāntáishān","Tiantai Mountain","A Buddhist mountain, the birthplace of the Tiantai school, with temples among cliffs and waterfalls.","",29.17,121.03],["D","台州海鲜","Tāizhōu hǎixiān","Taizhou seafood","Fresh crabs, shrimps and fish from the East China Sea, usually steamed or braised."]]},{"id":"zhoushan","zh":"舟山","py":"Zhōushān","en":"Zhoushan","lat":30.0,"lon":122.21,"note":"An island city and fishing port.","stops":[["A","普陀山","Pǔtuóshān","Mount Putuo","An island sacred to Guanyin, the bodhisattva of compassion, with temples, sea views and sandy beaches. Pilgrims come by ferry to burn incense and pray.","",30.01,122.38,1],["A","朱家尖","Zhūjiājiān","Zhujiajian","An island with long sandy beaches, popular with summer visitors.","",29.92,122.39],["D","舟山海鲜","Zhōushān hǎixiān","Zhoushan seafood","Yellow croaker, crab, shrimp and shellfish from the fishing grounds around Zhoushan."],["D","带鱼","Dàiyú","Hairtail fish","A long silver fish, fried or braised, which is a favorite of the Zhejiang coast."]]},{"id":"lishui","zh":"丽水","py":"Líshuǐ","en":"Lishui","lat":28.45,"lon":119.92,"note":"A green mountain city with terraced fields.","stops":[["A","龙泉青瓷","Lóngquán Qīngcí","Longquan celadon","Celadon pottery with a soft green glaze, made here for around 1,700 years, once exported worldwide.","",28.07,119.14]]},{"id":"quzhou","zh":"衢州","py":"Qúzhōu","en":"Quzhou","lat":28.94,"lon":118.87,"note":"A city with a Confucius family temple in the south.","stops":[["D","衢州鸭头","Qúzhōu yātóu","Quzhou duck head","A braised duck head snack, spicy and rich, popular in Quzhou."]]}],"air":{"zh":"杭州萧山国际机场","py":"Hángzhōu Xiāoshān Guójì Jīchǎng","en":"Hangzhou Xiaoshan International Airport","code":"HGH","lat":30.23,"lon":120.43,"note":"The main airport of Zhejiang, southeast of Hangzhou. Welcome to Zhejiang."}}]};
